local config = {
  ui_story_5057_50570001_1_dialog_content = "Resor Denuo Valley sangat luar biasa—",
  ui_story_5057_50570001_2_dialog_content = "Sangat luar biasa—!",
  ui_story_5057_50570001_3_dialog_content = "Tidak hanya memiliki banyak hidangan unik.",
  ui_story_5057_50570001_4_dialog_content = "Ini bahkan memiliki makanan dari Longzhou yang baru pertama kali saya lihat!",
  ui_story_5057_50570001_5_dialog_content = "Belum lagi banyak wahana hiburan yang mengasyikkan.",
  ui_story_5057_50570001_6_dialog_content = "Meskipun banyak di antaranya terlalu menakutkan untuk selera saya—",
  ui_story_5057_50570001_7_dialog_content = "Menakutkan adalah yang membuatnya menyenangkan.",
  ui_story_5057_50570001_8_dialog_content = "Saya masih bisa memancing, bernyanyi, mendapatkan terapi oksigen, dan pijat.",
  ui_story_5057_50570001_9_dialog_content = "Sungguh menenangkan.",
  ui_story_5057_50570001_10_dialog_content = "Ya, tapi seandainya harganya lebih... terjangkau.",
  ui_story_5057_50570001_11_dialog_content = "Iya, itu benar.",
  ui_story_5057_50570001_12_dialog_content = "...",
  ui_story_5057_50570001_13_dialog_content = "...",
  ui_story_5057_50570001_14_dialog_content = "Tunggu sebentar, Vice, berapa banyak yang sudah kita habiskan di resort ini?",
  ui_story_5057_50570001_15_dialog_content = "Yah, uh, saya terlalu asyik dalam liburan sampai lupa menghitung jumlahnya.",
  ui_story_5057_50570001_16_dialog_content = "Kita harus mencari tahu sekarang!",
  ui_story_5057_50570001_17_dialog_content = "T-Tunggu sebentar, ini tidak mungkin... Apakah kita salah menghitung di suatu tempat?",
  ui_story_5057_50570001_18_dialog_content = "Ini setara dengan anggaran untuk dua bulan!",
  ui_story_5057_50570001_19_dialog_content = "Saya sudah mengulanginya selusin kali...",
  ui_story_5057_50570001_20_dialog_content = "Hmm, setelah diperhatikan lebih dekat, sepertinya saya bertanggung jawab atas sebagian besar pengeluaran...",
  ui_story_5057_50570001_21_dialog_content = "Tapi ini juga salahku, karena aku yang mengelola dana tersebut. Sepertinya kita...",
  ui_story_5057_50570001_22_dialog_content = "Tidak, tidak, aku tidak bisa membiarkan kamu menanggung semuanya... Aku akan mencari pekerjaan di Umbraton!",
  ui_story_5057_50570001_23_dialog_content = "Saya akan menebusnya bahkan jika saya harus bekerja tiga pekerjaan sehari.",
  ui_story_5057_50570001_24_dialog_content = "Mengapa kalian berdua hanya duduk di sini?",
  ui_story_5057_50570001_25_dialog_content = "Kamu tidak ingin menjelajahi lebih banyak lagi resort ini?",
  ui_story_5057_50570001_26_dialog_content = "Oh, hai, Lorelei... Vice dan saya sedang istirahat.",
  ui_story_5057_50570001_27_dialog_content = "Ada masalah? Kamu terlihat agak murung.",
  ui_story_5057_50570001_28_dialog_content = "Kau bisa beritahu?",
  ui_story_5057_50570001_29_dialog_content = "Sejujurnya, kami menghabiskan anggaran selama dua bulan untuk bersenang-senang di sini.",
  ui_story_5057_50570001_30_dialog_content = "Whoa, kedengarannya tak bagus... Ada yang bisa saya bantu?",
  ui_story_5057_50570001_31_dialog_content = "Terima kasih atas pemikiran Anda, tetapi kami tidak menerima uang tanpa alasan.",
  ui_story_5057_50570001_32_dialog_content = "Bukan uang, tapi kesempatan kerja!",
  ui_story_5057_50570001_33_dialog_content = "Saya kebetulan membutuhkan seorang asisten. Deskripsi pekerjaan mencakup hal-hal umum. Intinya, ahli dalam segala bidang.",
  ui_story_5057_50570001_34_dialog_content = "Enam jam sehari, dan kamu akan mengembalikan defisit dalam setengah bulan.",
  ui_story_5057_50570001_35_dialog_content = "Jadi, kau tertarik?",
  ui_story_5057_50570001_36_dialog_content = "Ya ya ya!",
  ui_story_5057_50570001_37_dialog_content = "Iya, aku juga!",
  ui_story_5057_50570001_38_dialog_content = "Oh, tapi saya hanya butuh satu asisten.",
  ui_story_5057_50570001_39_dialog_content = "Saya bisa ini, Vice!",
  ui_story_5057_50570001_40_dialog_content = "Saya menghabiskan uangnya, jadi saya harus bertanggung jawab.",
  ui_story_5057_50570101_1_dialog_content = "Lorelei!",
  ui_story_5057_50570101_2_dialog_content = "Maaf, saya terlambat.",
  ui_story_5057_50570101_3_dialog_content = "Oh, kamu benar-benar membuatku menunggu.",
  ui_story_5057_50570101_4_dialog_content = "Tapi karena kamu baru saja mulai, aku akan membiarkanmu kali ini.",
  ui_story_5057_50570101_5_dialog_content = "Biasanya, jika seorang asisten terlambat, saya akan membuat mereka bekerja hingga larut malam.",
  ui_story_5057_50570101_6_dialog_content = "T-Tolong jangan! Saya juga punya pekerjaan malam!",
  ui_story_5057_50570101_7_dialog_content = "Kurasa kamu benar-benar kekurangan uang...",
  ui_story_5057_50570101_8_dialog_content = "Saya bisa menawarkan kamu pekerjaan penuh waktu.",
  ui_story_5057_50570101_9_dialog_content = "Berapa banyak kamu ingin bekerja tanpa henti setiap hari?",
  ui_story_5057_50570101_10_dialog_content = "Tolong berhenti bercanda!",
  ui_story_5057_50570101_11_dialog_content = "Heheh, kamu langsung tahu ya.",
  ui_story_5057_50570101_12_dialog_content = "Sebenarnya, saya sangat senang jika kamu membantu sepanjang waktu, PlayerName.",
  ui_story_5057_50570101_13_dialog_content = "Baik dalam kemampuan maupun karakter, kamu cocok dengan deskripsi tersebut.",
  ui_story_5057_50570101_14_dialog_content = "Uh, mungkin saat aku bangkrut dan tak punya rumah?",
  ui_story_5057_50570101_15_dialog_content = "Tentu, saya menantikan itu nanti.",
  ui_story_5057_50570101_16_dialog_content = "Tidak, jangan!",
  ui_story_5057_50570101_17_dialog_content = "Oh, aku dengar kamu ingin menangkap kupu-kupu, jadi aku mengumpulkan beberapa peralatan yang berguna.",
  ui_story_5057_50570101_18_dialog_content = "Apa pendapat kamu tentang jaring ini? Saya gunakan untuk menangkap serangga di Eraveil.",
  ui_story_5057_50570101_19_dialog_content = "Mungkin kasar, tetapi sangat praktis. Saya menangkap banyak bug dengannya.",
  ui_story_5057_50570101_20_dialog_content = "Hmm, saya pikir Cena menyampaikan informasi yang salah.",
  ui_story_5057_50570101_21_dialog_content = "Mungkin tidak mungkin menangkap Dewi Denuo dengan ini.",
  ui_story_5057_50570101_22_dialog_content = "Haha, ini, uh... pasti tidak mungkin menangkap Dewi Denuo dengan ini.",
  ui_story_5057_50570101_23_dialog_content = "Saya rasa ini akan menjadi tantangan yang cukup dengan peralatan yang kita miliki sekarang.",
  ui_story_5057_50570101_24_dialog_content = "Tapi kamu kan Caelestite terkenal, benar? Aku memang menghabiskan banyak uang untuk menyewa kamu.",
  ui_story_5057_50570101_25_dialog_content = "Uh, ya, benar. Karena kamu adalah majikan, saya akan berusaha sebaik mungkin.",
  ui_story_5057_50570101_26_dialog_content = "Tapi mengapa Dewi Denuo?",
  ui_story_5057_50570101_27_dialog_content = "Ahem, apakah kamu masih ingat slogan asli untuk promosi resor tersebut?",
  ui_story_5057_50570101_28_dialog_content = "\"Ingin mengabulkan keinginan terbesar Anda? Datanglah mencari Dewi Denuo yang membawa keberuntungan!\"",
  ui_story_5057_50570101_29_dialog_content = "Itu saja?",
  ui_story_5057_50570101_30_dialog_content = "Iya, benar.",
  ui_story_5057_50570101_31_dialog_content = "Itu karena kamu terus mengulanginya di telinga saya...",
  ui_story_5057_50570101_32_dialog_content = "Ya, dan saya bangga melihat kamu menghafal slogan itu.",
  ui_story_5057_50570101_33_dialog_content = "Tentu tentu. Jangan ngelantur.",
  ui_story_5057_50570101_34_dialog_content = "Oh baik... Jadi, banyak yang terjadi sebelumnya, seperti yang kamu tahu.",
  ui_story_5057_50570101_35_dialog_content = "Kemudian tiba-tiba, muncul rumor bahwa Dewi Denuo telah meninggalkan resor.",
  ui_story_5057_50570101_36_dialog_content = "Uh, bukankah itu iklan palsu sejak awal?",
  ui_story_5057_50570101_37_dialog_content = "Ini bukan iklan palsu jika kamu tidak bisa membuktikannya!",
  ui_story_5057_50570101_38_dialog_content = "Tapi jika ada rumor yang mengatakan itu salah, saya harus menghasilkan bukti yang membantahnya.",
  ui_story_5057_50570101_39_dialog_content = "Jadi rencanamu adalah menangkap Dewi Denuo?",
  ui_story_5057_50570101_40_dialog_content = "Tentu saja kami tidak benar-benar akan menangkapnya, tapi setidaknya mendapatkan fotonya.",
  ui_story_5057_50570101_41_option_content = "Akan kucoba semampuku.",
  ui_story_5057_50570101_42_dialog_content = "Oke. Aku tidak yakin bisa melakukannya, tapi aku akan melakukan yang terbaik.",
  ui_story_5057_50570101_43_dialog_content = "Luar biasa, itu asisten andalanku!",
  ui_story_5057_50570101_44_option_content = "Saya rasa itu sulit.",
  ui_story_5057_50570101_45_dialog_content = "Mungkin mustahil dengan jaring seperti ini.",
  ui_story_5057_50570101_46_dialog_content = "Hei, jangan menyerah begitu mudah! Aku akan memberimu kenaikan gaji jika kamu menangkap satu.",
  ui_story_5057_50570101_X46_dialog_content = "Jangan khawatir, saya tidak meminta Anda untuk benar-benar menangkapnya, jadi santai saja.",
  ui_story_5057_50570101_X47_dialog_content = "Jaga agar dewi tetap tenang dan masih cukup lama untuk saya ambil gambarnya!",
  ui_story_5057_50570101_47_dialog_content = "Ah! Udara di sini sangat menenangkan.",
  ui_story_5057_50570101_48_dialog_content = "Ya, seolah-olah itu bisa membersihkan dan menyegarkan jiwa Anda.",
  ui_story_5057_50570101_49_dialog_content = "Tepat sekali, penilaian yang sangat objektif dan relevan.",
  ui_story_5057_50570101_50_dialog_content = "Mari kita tidak buang waktu lagi dan mulailah pencarian. Gunakan kemampuan psikis Anda dengan baik!",
  ui_story_5057_50570101_51_dialog_content = "Mengapa rasanya aku seperti anjing pemburu sekarang?",
  ui_story_5057_50570101_52_dialog_content = "Kau pasti bisa, Caelestite.",
  ui_story_5057_50570101_53_dialog_content = "<color=#e8d9bb>Beberapa jam kemudian</color>",
  ui_story_5057_50570101_54_dialog_content = "L-Lupakan saja, aku tidak bisa dapat petunjuk apa-apa...",
  ui_story_5057_50570101_55_dialog_content = "Saya telah menggunakan kekuatan pikiran saya dan ini membuat otak saya lelah...",
  ui_story_5057_50570101_56_dialog_content = "Ayo istirahat dulu. Saya juga mulai lelah berjalan dengan sepatu hak tinggi ini.",
  ui_story_5057_50570101_57_dialog_content = "Saya cukup yakin saya mengingatkan kamu untuk mengganti sepatu yang lebih nyaman.",
  ui_story_5057_50570101_58_dialog_content = "Ya, tapi saya terburu-buru sehingga lupa melakukannya.",
  ui_story_5057_50570101_59_dialog_content = "Tapi sebagai seorang wanita sejati, saya bisa melintasi medan yang sulit seolah-olah itu adalah lantai marmer yang halus dalam sepatu hak tinggi.",
  ui_story_5057_50570101_60_dialog_content = "Itu sangat menakjubkan...",
  ui_story_5057_50570101_61_dialog_content = "Uh, kenapa kamu menatapku...?",
  ui_story_5057_50570101_62_dialog_content = "Jangan bergerak, PlayerName.",
  ui_story_5057_50570101_63_dialog_content = "Aku melihat sesuatu yang mirip Dewi Denuo di belakangmu.",
  ui_story_5057_50570101_64_dialog_content = "A-Apakah kamu yakin? Kenapa aku tidak bisa merasakannya?",
  ui_story_5057_50570101_65_dialog_content = "Belum begitu yakin. Saya perlu mendekat.",
  ui_story_5057_50570101_66_dialog_content = "Hei, berbahaya ke arah itu!",
  ui_story_5057_50570101_67_dialog_content = "Ini melarikan diri!",
  ui_story_5057_50570101_68_dialog_content = "Kabur! Sungguh terlihat seperti Dewi Denuo!",
  ui_story_5057_50570101_69_dialog_content = "Awas kaki Anda, Lorelei!",
  ui_story_5057_50570101_70_dialog_content = "Ugh!",
  ui_story_5057_50570101_71_dialog_content = "Apa kamu baik-baik saja, Lorelei?",
  ui_story_5057_50570101_72_dialog_content = "Y-Ya, aku baik-baik saja...",
  ui_story_5057_50570101_73_dialog_content = "Aku baru saja tersandung...",
  ui_story_5057_50570101_X74_dialog_content = "Saya pikir kameranya juga rusak ...",
  ui_story_5057_50570101_74_dialog_content = "Lupakan kameranya. Apakah kamu terluka?",
  ui_story_5057_50570101_75_dialog_content = "Mungkin pergelangan kaki terkilir... tumit sepatu Anda juga patah.",
  ui_story_5057_50570101_76_dialog_content = "Kaus kaki dan kaki Anda kotor karena menginjak lumpur...",
  ui_story_5057_50570101_77_dialog_content = "Maaf, PlayerName... Seharusnya aku mendengarkanmu dan mengganti sepatu.",
  ui_story_5057_50570101_78_dialog_content = "<color=#e8d9bb>Cabang dan semak menggores kaki Lorelei, mengeluarkan jejak darah kecil. Pergelangan kakinya terlihat bengkak dan terpelintir.</color>",
  ui_story_5057_50570101_79_dialog_content = "Jangan pikirkan itu sekarang. Kita harus pergi melihat apakah kamu memiliki tulang yang patah.",
  ui_story_5057_50570101_80_dialog_content = "Tentu saja... ayo kembali. Bisa tolong carikan batang kayu untuk saya gunakan sebagai tongkat?",
  ui_story_5057_50570101_81_dialog_content = "Apa yang kamu katakan? Kamu bahkan tidak bisa berdiri sekarang.",
  ui_story_5057_50570101_82_dialog_content = "Hanya akan memperburuk cedera jika kamu mencoba berjalan kembali.",
  ui_story_5057_50570101_83_dialog_content = "<color=#e8d9bb>Saya membelakangi Lorelei dan jongkok.</color>",
  ui_story_5057_50570101_84_dialog_content = "Ayo. Aku akan menggendongmu di punggungku.",
  ui_story_5057_50570101_85_dialog_content = "Saya dewasa, bisa jalan sendiri. Hanya anak-anak yang perlu digendong di punggung orang...",
  ui_story_5057_50570101_86_dialog_content = "Tapi menurut saya, orang yang berpura-pura menjadi dewasa sebenarnya adalah anak-anak.",
  ui_story_5057_50570101_87_dialog_content = "Lagipula, bukankah tugas bos untuk mengatur karyawannya?",
  ui_story_5057_50570101_88_dialog_content = "Baiklah, kalau kau bersikeras.",
  ui_story_5057_50570101_89_dialog_content = "<color=#e8d9bb>Dengan sedikit keengganan, Lorelei naik ke punggungku dengan canggung.</color>",
  ui_story_5057_50570101_90_dialog_content = "Baiklah. Saya kira saya tidak punya niat untuk membiarkan uang saya sia-sia.",
  ui_story_5057_50570101_91_dialog_content = "Tahan erat dan ayo kembali.",
  ui_story_5057_50570101_92_dialog_content = "Baiklah…",
  ui_story_5057_50570101_93_dialog_content = "eh...",
  ui_story_5057_50570101_94_dialog_content = "Ya?",
  ui_story_5057_50570101_95_dialog_content = "Terima kasih.",
  ui_story_5057_50570101_96_dialog_content = "<color=#e8d9bb>Ketika kami kembali, Lorelei tertidur di punggungku, mengobrol dalam mimpi aneh dan tidak masuk akal sepanjang perjalanan.</color>",
  ui_story_5057_50570102_1_dialog_content = "PlayerName!",
  ui_story_5057_50570102_2_dialog_content = "Kesini, cepat!",
  ui_story_5057_50570102_3_dialog_content = "Saya datang!",
  ui_story_5057_50570102_4_dialog_content = "Bagaimana kondisi kakimu hari ini?",
  ui_story_5057_50570102_5_dialog_content = "Sudah bagus sekarang! Jangan meremehkan kemampuan pemulihan saya. Tentu saja, kamu juga berperan dalam pemulihan ini.",
  ui_story_5057_50570102_6_dialog_content = "Tidak masalah. Saya kan asisten Anda.",
  ui_story_5057_50570102_7_dialog_content = "Even jika aku tidak, aku tidak akan meninggalkan kamu sendirian. Kamu adalah teman penting bagiku.",
  ui_story_5057_50570102_8_dialog_content = "Teman... Itu mengingatkanku!",
  ui_story_5057_50570102_9_dialog_content = "Pasti banyak spesialisasi di Eraveil, kan? Kita harus jadi mitra bisnis!",
  ui_story_5057_50570102_10_dialog_content = "Ini di bawah kemampuanmu untuk jadi asistenku, jadi bagaimana kalau kita bekerja sama?",
  ui_story_5057_50570102_11_dialog_content = "Bagaimana bisa kamu melihat peluang bisnis di mana-mana, Lorelei? Tapi aku harus mengakui kamu sangat pandai dalam hal itu...",
  ui_story_5057_50570102_12_dialog_content = "Oh, aku menghabiskan semalaman berpikir dan menyadari bahwa terlalu sulit mencoba menangkap Dewi Denuo dengan jaring.",
  ui_story_5057_50570102_13_dialog_content = "Oh, saya menghubungi teman dan meminjam kamera yang tahan air dan tahan benturan!",
  ui_story_5057_50570102_14_dialog_content = "Dengan cara ini, kita bisa mengambil foto saat kita bertemu dengannya.",
  ui_story_5057_50570102_15_dialog_content = "Nah, bukankah orang-orang masih akan mengatakan bahwa fotonya telah diedit?",
  ui_story_5057_50570102_16_dialog_content = "Apa? Bagaimana kamu bisa memanipulasi foto?",
  ui_story_5057_50570102_17_dialog_content = "Haha... Sebenarnya, cukup banyak orang di Umbraton yang mampu melakukan itu.",
  ui_story_5057_50570102_18_dialog_content = "Tapi bukan itu intinya! Mari kita tunda Denuo Goddess untuk hari ini.",
  ui_story_5057_50570102_19_dialog_content = "Hah? Jadi kenapa kamu terburu-buru ingin aku di sini?",
  ui_story_5057_50570102_20_dialog_content = "Membalas budi padamu, tentu saja, PlayerName.",
  ui_story_5057_50570102_21_dialog_content = "Saya membayar hutang-hutang saya.",
  ui_story_5057_50570102_22_dialog_content = "Semua biaya hari ini ditanggung oleh saya, jadi nikmati rasanya memiliki akses ke seluruh resor!",
  ui_story_5057_50570102_24_dialog_content = "Ini adalah area rahasia di taman air, bukan? Sungguh menakjubkan! Saya tidak pikir kamu pernah ke tempat ini sebelumnya.",
  ui_story_5057_50570102_25_dialog_content = "Ya, ini pertama kalinya saya di sini... Saya tidak tahu kalau ada area tersembunyi di taman air.",
  ui_story_5057_50570102_26_dialog_content = "Jika saya tahu lebih awal, saya tidak perlu menunggu di antrian panjang!",
  ui_story_5057_50570102_27_dialog_content = "Meskipun lebih spektakuler daripada yang ada di luar, tempat ini tidak dibuka untuk umum.",
  ui_story_5057_50570102_28_dialog_content = "Yang berarti ini adalah taman bermain pribadi dan personal saya!",
  ui_story_5057_50570102_29_dialog_content = "Jadi ini adalah hak istimewa bos?",
  ui_story_5057_50570102_30_dialog_content = "Uh-huh, benar sekali!",
  ui_story_5057_50570102_31_dialog_content = "Jadi, saya bisa nongkrong di sini juga?",
  ui_story_5057_50570102_32_dialog_content = "Tentu saja! Nikmati saja perosotan dan segalanya. Silakan minum dan makan tanpa perlu menunggu di antrian.",
  ui_story_5057_50570102_33_dialog_content = "Luar biasa!",
  ui_story_5057_50570102_34_dialog_content = "Wow, ini keren!",
  ui_story_5057_50570102_35_dialog_content = "Sangat menyenangkan terus menaiki seluncuran air tanpa harus kembali ke antrian!",
  ui_story_5057_50570102_36_dialog_content = "Kamu terlalu terobsesi dengan slide, PlayerName.",
  ui_story_5057_50570102_37_dialog_content = "Itu karena kamu belum pernah mengalami antrian yang sangat panjang untuk perosotan di luar sana, Lorelei!",
  ui_story_5057_50570102_38_dialog_content = "Hei, kenapa kamu tidak ganti ke pakaian renang dan menikmati ini bersama saya?",
  ui_story_5057_50570102_39_dialog_content = "Saya bisa melakukannya tanpa mengubah!",
  ui_story_5057_50570102_40_dialog_content = "Lihat!",
  ui_story_5057_50570102_41_dialog_content = "Jadi, menurutmu kesenangan itu menyiram air pada saya?",
  ui_story_5057_50570102_42_dialog_content = "Betapa kekanak-kanakan! Saya tidak akan ikut campur!",
  ui_story_5057_50570102_43_dialog_content = "Kanak-kanak, katamu? Rasakan ini!",
  ui_story_5057_50570102_44_dialog_content = "Guyuran, guyuran!",
  ui_story_5057_50570102_45_dialog_content = "... Guyuran!",
  ui_story_5057_50570102_46_dialog_content = "Hei!",
  ui_story_5057_50570102_47_dialog_content = "Tunggu sebentar, apa yang kau pikir sedang kau lakukan? Bukankah kau bilang itu kanak-kanak?",
  ui_story_5057_50570102_48_dialog_content = "Tidak, maksud saya itu terlalu kekanak-kanakan untuk anak-anak.",
  ui_story_5057_50570102_49_dialog_content = "Tapi aku baru menyadari bahwa ini bagus untukku! Splash—!",
  ui_story_5057_50570102_50_dialog_content = "Hei, di mana Lorelei?",
  ui_story_5057_50570102_51_dialog_content = "Kemana dia menghilang?",
  ui_story_5057_50570102_52_dialog_content = "Maaf membuat anda menunggu! Aku baru saja mengganti pakaianku yang basah.",
  ui_story_5057_50570102_53_dialog_content = "Oh, dan terima kasih juga untuk handukmu.",
  ui_story_5057_50570102_54_dialog_content = "Wow... Saya kira itu sebabnya Anda adalah bosnya. Anda menyiapkan pakaian cadangan?",
  ui_story_5057_50570102_55_dialog_content = "Tidak heran Anda tidak perlu berganti pakaian renang.",
  ui_story_5057_50570102_56_dialog_content = "Kamu adalah apa yang kamu kenakan. Saya memiliki banyak pakaian bukan karena saya kaya, tetapi karena saya perlu menjaga citra profesional untuk bisnis saya.",
  ui_story_5057_50570102_57_dialog_content = "Apa yang sangat ... alasan bundaran itu.",
  ui_story_5057_50570102_58_dialog_content = "Pokoknya, tidak ada jalan pintas yang benar dalam hidup, bahkan untuk orang kaya, tetapi ada teknik-tekniknya.",
  ui_story_5057_50570102_59_dialog_content = "Teknik?",
  ui_story_5057_50570102_60_dialog_content = "Tahu kan, setiap orang di resor ini tampaknya kaya atau terkenal.",
  ui_story_5057_50570102_61_dialog_content = "Tapi tidak semuanya kaya... Beberapa di antara mereka bahkan tidak diundang olehku.",
  ui_story_5057_50570102_62_dialog_content = "Apa? Mereka bisa datang ke sini tanpa undanganmu?",
  ui_story_5057_50570102_63_dialog_content = "Ya, mereka menggunakan koneksi mereka untuk datang ke sini dan membuat lebih banyak koneksi.",
  ui_story_5057_50570102_64_dialog_content = "Oh, yang disebut jaringan, kan?",
  ui_story_5057_50570102_65_dialog_content = "Benar! Kamu cukup tajam.",
  ui_story_5057_50570102_66_dialog_content = "Jadi kamu mengerti sekarang? Mengundang kamu ke tempat bermain pribadiku adalah persetujuan atas hubungan kita.",
  ui_story_5057_50570102_67_dialog_content = "Oke! Kamu bukan hanya bosku tapi juga teman yang hebat. Aku tahu itu sejak lama.",
  ui_story_5057_50570102_68_dialog_content = "Kenapa kamu...",
  ui_story_5057_50570102_69_dialog_content = "Apa yang harus saya lakukan untuk bisa sampai ke kamu?",
  ui_story_5057_50570102_70_dialog_content = "Saya tidak membahas tentang persahabatan biasa, tetapi jenis bisnis antara orang dewasa...",
  ui_story_5057_50570102_71_dialog_content = "(Apa...? Apakah aku membuatnya marah?)",
  ui_story_5057_50570102_72_dialog_content = "<color=#e8d9bb>Menggeram-</color>",
  ui_story_5057_50570102_73_dialog_content = "Apa itu?",
  ui_story_5057_50570102_74_dialog_content = "Maaf, saya belum makan sejak pagi ini.",
  ui_story_5057_50570102_75_dialog_content = "Ahem, baiklah, mari kita pergi makan sebentar.",
  ui_story_5057_50570102_76_dialog_content = "...",
  ui_story_5057_50570102_77_dialog_content = "...",
  ui_story_5057_50570102_78_dialog_content = "...",
  ui_story_5057_50570102_79_dialog_content = "(Dia menyembunyikan wajahnya dalam makanan dan ini terasa sangat canggung... Apakah dia masih marah padaku?)",
  ui_story_5057_50570102_80_dialog_content = "(Masakannya sangat lezat, tapi ini pertama kalinya aku melihat dia makan tanpa berkata-kata.)",
  ui_story_5057_50570102_81_dialog_content = "(Hei, kita bertatapan! Harus menundukkan kepalaku!)",
  ui_story_5057_50570102_82_dialog_content = "Ehem, jadi...",
  ui_story_5057_50570102_83_dialog_content = "Barbekyunya lezat... Aku pesan untukmu. Cobalah.",
  ui_story_5057_50570102_84_dialog_content = "<color=#e8d9bb>Menyelesaikan kalimatnya, Lorelei menyelam kembali dan menggigit sebongkah besar daging.</color>",
  ui_story_5057_50570102_85_dialog_content = "Ah, tentu, mengerti, trims!",
  ui_story_5057_50570102_86_dialog_content = "Dan, Lorelei, tentang apa yang terjadi di sana...",
  ui_story_5057_50570102_87_dialog_content = "Saya tidak bermaksud bahwa saya tidak ingin menjadi teman Anda, PlayerName.",
  ui_story_5057_50570102_88_dialog_content = "Hanya saja, saya ingin menampilkan diri sebagai orang bisnis yang matang, bukan seseorang yang hanya bergaul dengan teman-teman seperti anak kecil.",
  ui_story_5057_50570102_89_dialog_content = "Saya ingin melepaskan diri—",
  ui_story_5057_50570102_90_option_content = "Aku paham.",
  ui_story_5057_50570102_91_dialog_content = "Saya mengerti bahwa kamu berusaha untuk mendapatkan pengakuan dari orang lain sebagai individu yang mandiri.",
  ui_story_5057_50570102_92_dialog_content = "Tetapi... aku belum dewasa! Saat bersamaku, kamu tidak perlu bersikap dewasa. Santai saja dan jadi diri sendiri.",
  ui_story_5057_50570102_93_dialog_content = "Terima kasih, PlayerName...",
  ui_story_5057_50570102_94_option_content = "Ya, benar.",
  ui_story_5057_50570102_95_dialog_content = "Aku paham maksudmu. Jangan khawatir, aku nggak akan bawa ke hati. Memang wajar kalau teman-teman suka berdebat sesekali!",
  ui_story_5057_50570102_96_dialog_content = "Kamu masih mau berteman dengan saya? Terima kasih, PlayerName.",
  ui_story_5057_50570102_97_dialog_content = "<color=#e8d9bb>Setelah itu, Lorelei kembali menjadi dirinya yang biasa, tertawa dan berbicara denganku sambil menikmati makanan kami. Dia bahkan menemani dan mengobrol denganku hingga larut malam.</color>",
  ui_story_5057_50570201_1_dialog_content = "Hei, aku rasa kamu adalah pembantu yang Lorelei sebutkan?",
  ui_story_5057_50570201_2_dialog_content = "Hei, aku rasa Cena adalah orang yang dibantu yang Lorelei sebutkan?",
  ui_story_5057_50570201_3_dialog_content = "Oh, kamu meniruku sekarang, Caelestite.",
  ui_story_5057_50570201_4_dialog_content = "Mengapa demikian? Apakah kamu mencoba untuk menampilkan pesona dan kematangan seorang pria seperti aku?",
  ui_story_5057_50570201_5_dialog_content = "Tapi itu tidak cocok dengan kategori usia Anda, Caelestite.",
  ui_story_5057_50570201_6_dialog_content = "Bukannya begitu, sih!",
  ui_story_5057_50570201_7_dialog_content = "Jangan narsis! Aku hanya bercanda kok.",
  ui_story_5057_50570201_8_dialog_content = "Saya tidak peduli tentang pesona Anda atau apapun itu.",
  ui_story_5057_50570201_9_dialog_content = "Benarkah? Banyak wanita yang akan tidak setuju.",
  ui_story_5057_50570201_10_dialog_content = "Kamu akan mengalami masalah dalam hubungan lebih cepat atau lambat dengan sikap seperti itu.",
  ui_story_5057_50570201_11_dialog_content = "Hahaha, itu pernyataan yang aneh.",
  ui_story_5057_50570201_12_dialog_content = "Menurut saya, rasa sakit dari penolakan adalah kenyataan hidup yang harus kita semua rasakan.",
  ui_story_5057_50570201_13_dialog_content = "Hidup itu singkat, jadi nikmatilah!",
  ui_story_5057_50570201_14_dialog_content = "Saya tidak percaya itu. Eve Bahkan orang yang paling santai pun akan memiliki perasaan dan merindukan hubungan yang stabil dan harmonis.",
  ui_story_5057_50570201_15_dialog_content = "Itulah yang orang normal pikirkan.",
  ui_story_5057_50570201_16_dialog_content = "Saya berbeda, karena saya Cena.",
  ui_story_5057_50570201_17_dialog_content = "Yah, itu tidak terdengar menarik. Mari kita langsung ke urusan saja.",
  ui_story_5057_50570201_18_dialog_content = "Seperti pepatah, \"Segalanya berubah dan tidak ada yang tetap sama.\"",
  ui_story_5057_50570201_19_dialog_content = "Apa yang saya cintai adalah berkeliaran dan mencoba berbagai pengalaman.",
  ui_story_5057_50570201_20_dialog_content = "Hubungan statis hanya memasang belenggu di sayapku.",
  ui_story_5057_50570201_21_dialog_content = "Benarkah?",
  ui_story_5057_50570201_22_dialog_content = "Semakin Anda mencoba untuk menampilkan diri sebagai kekasih yang hebat, semakin tampak bahwa Anda mengandalkan fasad yang menarik untuk menghindari menghadapi kenyataan.",
  ui_story_5057_50570201_23_dialog_content = "Ahem.",
  ui_story_5057_50570201_24_dialog_content = "Inilah mengapa kamu kaum Caelestite merepotkan.",
  ui_story_5057_50570201_25_dialog_content = "Kode pendiam juga merupakan ukuran orang dewasa yang matang, kamu tahu. Jika tidak, tidak ada kebahagiaan dalam hidup.",
  ui_story_5057_50570201_26_dialog_content = "Oh, aku sedang berpikir betapa mempesona jika seorang wanita cantik membantuku, mengubah waktu kita bersama menjadi kencan romantis.",
  ui_story_5057_50570201_27_dialog_content = "Tapi sekarang saya berakhir dengan anak pintar yang bisa membaca pikiran.",
  ui_story_5057_50570201_28_dialog_content = "Jadi bagaimana kalau kita pergi mendapatkan satu atau dua putaran, mungkin meredam sedikit kekuatan psikis Anda?",
  ui_story_5057_50570201_29_dialog_content = "Saya di sini untuk bekerja, bukan untuk kencan atau minum seperti seseorang yang pasti.",
  ui_story_5057_50570201_30_dialog_content = "Kerja?",
  ui_story_5057_50570201_31_dialog_content = "Masih pagi, belum waktunya bekerja! Ayo pergi bersenang-senang dulu.",
  ui_story_5057_50570201_32_dialog_content = "Aku tahu tempat yang hebat dijamin akan membuatmu terkesima.",
  ui_story_5057_50570201_33_dialog_content = "Naga Malam Putih... memang tempat yang akan membuat pikiranku terpukau.",
  ui_story_5057_50570201_34_option_content = "Naik bersama saya?",
  ui_story_5057_50570201_35_dialog_content = "Maaf, PlayerName, saya tidak tertarik untuk pergi bersama remaja seperti kamu.",
  ui_story_5057_50570201_36_dialog_content = "Lalu apa masalahnya...",
  ui_story_5057_50570201_37_option_content = "Bagaimana ini?",
  ui_story_5057_50570201_38_dialog_content = "Santai. Aku sudah memilih target pertama.",
  ui_story_5057_50570201_39_dialog_content = "Mataku setajam elang yang terlatih...",
  ui_story_5057_50570201_40_dialog_content = "Jadi, bagaimana dengan wanita cantik di sana, dengan seorang bocah laki-laki dan seorang gadis?",
  ui_story_5057_50570201_41_dialog_content = "(Saya melihat ke arah seorang ibu muda yang cantik bersiap untuk antri dengan seorang bocah laki-laki dan adik perempuannya.)",
  ui_story_5057_50570201_42_dialog_content = "(Mereka tampak sangat bahagia meski berdiri dalam kerumunan yang berdesak-desakan.)",
  ui_story_5057_50570201_43_dialog_content = "Kamu nggak akan merayu, kan?",
  ui_story_5057_50570201_44_dialog_content = "Harus lebih cerdas dari itu.",
  ui_story_5057_50570201_45_dialog_content = "Hai, wanita cantik, apakah ini anak-anak Anda? Mereka tampak sangat tertarik pada mainan besar itu.",
  ui_story_5057_50570201_46_dialog_content = "Ya, mereka berdua benar-benar menikmati waktu di sini! Tempat liburan ini sungguh luar biasa!",
  ui_story_5057_50570201_47_dialog_content = "Sebagai manajer Denuo Valley Resort, saya senang mendengar itu!",
  ui_story_5057_50570201_48_dialog_content = "Oleh karena itu, saya harus memastikan kamu dan kedua tamu muda sepenuhnya menikmati nilai uang yang kamu keluarkan!",
  ui_story_5057_50570201_49_dialog_content = "Berikut ini tiga voucher VIP untukmu.",
  ui_story_5057_50570201_50_dialog_content = "Oh, manajer, kamu sangat... Hei!",
  ui_story_5057_50570201_51_dialog_content = "Jaga baik-baik wanita ini dan saudara-saudaranya, PlayerName!",
  ui_story_5057_50570201_52_dialog_content = "<color=#e8d9bb>Tiba-tiba, Cena mendorong ketiga orang itu ke arahku dan dengan cepat menyusul kedua pria yang baru saja mencuri tas tangan ibu itu.</color>",
  ui_story_5057_50570201_53_dialog_content = "Hah?",
  ui_story_5057_50570201_54_dialog_content = "Jangan pernah berpikir untuk kabur!",
  ui_story_5057_50570201_55_dialog_content = "<color=#e8d9bb>Cena berhasil menendang pinggang pencuri terdekat dengan tepat.</color>",
  ui_story_5057_50570201_56_dialog_content = "<color=#e8d9bb>Pencuri yang terkena tendangan terbang dan menabrak temannya, dan mereka berdua jatuh bersama-sama.</color>",
  ui_story_5057_50570201_57_dialog_content = "S-Sial!",
  ui_story_5057_50570201_58_dialog_content = "Akhirnya aku menangkapmu. Berani sekali kamu mengincar wanita di bawah pengawasanku.",
  ui_story_5057_50570201_59_dialog_content = "Tapi tidak apa-apa, sekarang kamu punya semua waktu di dunia untuk menyesalinya.",
  ui_story_5057_50570201_60_dialog_content = "Terima kasih banyak!",
  ui_story_5057_50570201_61_dialog_content = "Ini adalah tugas saya. Kami mengutamakan keselamatan setiap tamu di resor di atas segalanya.",
  ui_story_5057_50570201_62_dialog_content = "Terutama untuk wanita seindah Anda.",
  ui_story_5057_50570201_63_dialog_content = "Baiklah, kita bisa pergi sekarang, Caelestite muda.",
  ui_story_5057_50570201_64_dialog_content = "Dibandingkan dengan saya yang pernah menangkap pencuri legendaris sebagai detektif swasta, kamu sudah cukup baik.",
  ui_story_5057_50570201_65_dialog_content = "Bangga pada dirimu sendiri!",
  ui_story_5057_50570201_66_dialog_content = "Apa? Apa yang telah saya lakukan?",
  ui_story_5057_50570201_67_dialog_content = "<color=#e8d9bb>Setelah itu, Cena mengajak saya makan malam. Kami menyantap makanan sambil dia terus bercerita tentang betapa cantik dan mempesona wanita itu.</color>",
  ui_story_5057_50570201_68_dialog_content = "<color=#e8d9bb>Namun, dia masih belum mengubah kasih sayang itu menjadi tindakan, dan kisah Cena dengan wanita itu berakhir begitu saja.</color>",
  ui_story_5057_50570202_1_dialog_content = "Selamat pagi.",
  ui_story_5057_50570202_2_dialog_content = "Pagi, Caelestite.",
  ui_story_5057_50570202_3_dialog_content = "Apa yang kamu lakukan di tempat seperti ini pagi-pagi begini? Aku sudah mencarimu kemana-mana.",
  ui_story_5057_50570202_4_dialog_content = "Di mana lagi saya akan berada selain di bar? Nongkrong di kolam renang? Itu tidak baik untuk kulitku.",
  ui_story_5057_50570202_5_dialog_content = "Maksud saya adalah, apakah Anda tidak memiliki pekerjaan yang harus dilakukan?",
  ui_story_5057_50570202_6_dialog_content = "Kamu telah mencoba membuatku menganggur bersamamu begitu terang-terangan, itu akan menjadi keajaiban jika Lorelei tidak mengurangi gajiku...",
  ui_story_5057_50570202_7_dialog_content = "Hahaha, kamu hebat dalam segala hal, selain terlalu kaku.",
  ui_story_5057_50570202_8_dialog_content = "Tidakkah kamu tahu cara menjalani hidup sepenuhnya? Dengan jumlah yang sedikit Lorelei bayar kepada saya, saya lebih baik menghabiskan waktu di bar, menunggu pertemuan yang luar biasa.",
  ui_story_5057_50570202_9_dialog_content = "Jadi kapan \"dia\" yang kamu tunggu akan muncul?",
  ui_story_5057_50570202_10_dialog_content = "Hei, keluarkan pikiranmu dari selokan sekarang, Caelestite.",
  ui_story_5057_50570202_11_dialog_content = "Jangan terlalu dangkal. Membuat teman saja sudah sangat indah.",
  ui_story_5057_50570202_12_dialog_content = "Saya terkejut bagaimana kamu bisa memutarbalikkan menjadi salah saya.",
  ui_story_5057_50570202_13_dialog_content = "Hahaha, kamu orang yang sangat menarik.",
  ui_story_5057_50570202_14_dialog_content = "Jangan hanya berdiri di situ, ayo ke sini. Aku tidak akan memakanmu hidup-hidup.",
  ui_story_5057_50570202_15_dialog_content = "Jangan bilang kamu terintimidasi oleh kesan keanggunan saya... Atau kamu hanya tidak suka sifat demi-human pada diri saya?",
  ui_story_5057_50570202_16_dialog_content = "Itu tidak benar!",
  ui_story_5057_50570202_17_dialog_content = "Ini dia. Saya menghargai kenyataan bahwa kamu tidak takut bahkan pada Aurorian seperti saya!",
  ui_story_5057_50570202_18_dialog_content = "Hah? Sudah minum berapa banyak? Masih sadar?",
  ui_story_5057_50570202_19_dialog_content = "Tak satu tetes pun. Mari langsung ke urusan.",
  ui_story_5057_50570202_20_dialog_content = "Wow, perubahan mendadak menjadi serius... Saya tidak terbiasa dengan ini.",
  ui_story_5057_50570202_21_dialog_content = "Ayo, PlayerName, seperti yang baru saja aku katakan, kamu hebat dalam segala hal.",
  ui_story_5057_50570202_22_dialog_content = "Tapi kamu masih terlalu polos dalam hal cinta dan percintaan. Aku khawatir apakah kamu bisa menemukan akhir bahagia untuk dirimu sendiri.",
  ui_story_5057_50570202_23_dialog_content = "Saya bukan orang yang tidak bersalah... Even jika saya memang tidak bersalah, itu bukan urusan Anda!",
  ui_story_5057_50570202_24_dialog_content = "Jangan katakan itu. Kita teman dan aku tidak tahan melihat kamu sia-siakan hidupmu.",
  ui_story_5057_50570202_25_dialog_content = "Setelah merenung sepanjang malam, saya memutuskan untuk menceritakan semua rahasia saya kepada kamu.",
  ui_story_5057_50570202_26_dialog_content = "Aduh… yah…",
  ui_story_5057_50570202_27_option_content = "Saya bisa setuju dengan itu.",
  ui_story_5057_50570202_28_dialog_content = "Itu Caelestite yang aku kenal. Jangan repot-repot memanggilku master. Kita langsung masuk ke intinya.",
  ui_story_5057_50570202_29_option_content = "Tidak, terima kasih.",
  ui_story_5057_50570202_30_dialog_content = "Jangan terlalu kaku. Belajar itu tidak pernah buruk.",
  ui_story_5057_50570202_31_dialog_content = "A-Baiklah...",
  ui_story_5057_50570202_32_dialog_content = "Oke, kita harus membuat skenario...",
  ui_story_5057_50570202_33_dialog_content = "T-Tunggu!",
  ui_story_5057_50570202_34_dialog_content = "Jangan sampai kamu berpikir untuk menyuruhku berdandan untuk itu!",
  ui_story_5057_50570202_35_dialog_content = "Hmm, ide bagus itu... Kamu yakin tidak mau, ya?",
  ui_story_5057_50570202_36_dialog_content = "Tidak mungkin!",
  ui_story_5057_50570202_37_dialog_content = "Baiklah. Kamu murid pertamaku setelah semua.",
  ui_story_5057_50570202_38_dialog_content = "Lalu, mari kita mulai dengan teori-teori dan prinsip-prinsip.",
  ui_story_5057_50570202_39_dialog_content = "Pertama, kamu harus memiliki keberanian untuk mendekatinya, tahu cara memuji dia dan biarkan dia tahu bahwa kamu menghargai sisi terbaiknya.",
  ui_story_5057_50570202_40_dialog_content = "Pujian... Bagaimana cara melakukannya?",
  ui_story_5057_50570202_41_dialog_content = "Coba kutipan puitis, misalnya.",
  ui_story_5057_50570202_42_dialog_content = "\"Kamu cantik dan memabukkan seperti bulan keperakan.\"",
  ui_story_5057_50570202_43_dialog_content = "\"Senyummu menyamai keindahan matahari terbenam yang mempesona.\"",
  ui_story_5057_50570202_44_dialog_content = "Sesuatu yang berpengaruh seperti itu.",
  ui_story_5057_50570202_45_dialog_content = "Oke, sepertinya saya mengerti intinya. Lalu apa?",
  ui_story_5057_50570202_46_dialog_content = "Langkah berikutnya sangat menentukan. Kamu harus menawan seperti saya untuk melakukannya.",
  ui_story_5057_50570202_47_dialog_content = "Kamu mengunci pandanganmu dengan matanya, dengan gairah yang tak terbendung.",
  ui_story_5057_50570202_48_dialog_content = "Lelehkan dia dengan tatapanmu.",
  ui_story_5057_50570202_49_dialog_content = "Kedipkan lembut dan kirim sinyal.",
  ui_story_5057_50570202_50_dialog_content = "Atau jika kamu merasa cukup menawan, kamu bisa memberinya ciuman angin.",
  ui_story_5057_50570202_51_dialog_content = "Tidak ada yang bisa menahan itu!",
  ui_story_5057_50570202_52_dialog_content = "Uh, saya sedang tidak enak badan saat ini...",
  ui_story_5057_50570202_53_dialog_content = "Jadi, kamu merasakan betapa kuatnya itu?",
  ui_story_5057_50570202_54_dialog_content = "Ya...",
  ui_story_5057_50570202_55_dialog_content = "Kemudian datang langkah ketiga. Kamu harus tangguh, atau memiliki rasa malu yang sangat sedikit.",
  ui_story_5057_50570202_56_dialog_content = "Kamu harus punya keberanian untuk membual pada saat yang tepat.",
  ui_story_5057_50570202_57_dialog_content = "Dan sesekali melemparkan kalimat lucu tanpa malu akan membuat lebih banyak orang menyukai Anda.",
  ui_story_5057_50570202_58_dialog_content = "Seperti \"Bertemu seorang wanita seperti kamu pasti adalah hadiahku karena menyelamatkan Astra!\"",
  ui_story_5057_50570202_59_dialog_content = "Ya, aku akui itu agak klise, tapi kamu harus mempelajari bahwa mereka suka pujian!",
  ui_story_5057_50570202_60_dialog_content = "Saya rasa mendengarkan kamu adalah hukuman saya karena mungkin telah menghancurkan Astra di kehidupan sebelumnya...",
  ui_story_5057_50570202_61_dialog_content = "Lumayan juga, kamu cepat belajar!",
  ui_story_5057_50570202_62_dialog_content = "Kamu hampir lulus sekarang. Nanti aku akan ajak kamu untuk uji coba di lapangan.",
  ui_story_5057_50570202_63_dialog_content = "Tidak bisa percaya aku benar-benar di sini...",
  ui_story_5057_50570202_64_dialog_content = "Saya hanya ingin mempelajari sesuatu yang percuma... Itu bukan hal yang buruk, bukan?",
  ui_story_5057_50570202_65_dialog_content = "Jadi di mana Cena? Dia terlambat...",
  ui_story_5057_50570202_66_dialog_content = "PlayerName!",
  ui_story_5057_50570202_67_dialog_content = "Maaf, saya terlambat.",
  ui_story_5057_50570202_68_dialog_content = "Lorelei menarik saya untuk membicarakan pekerjaan. Saya harus berusaha keras untuk melepaskan diri.",
  ui_story_5057_50570202_69_dialog_content = "Kamu nggak nunggu lama, kan? Ini cokelat yang aku ambil dari meja Lorelei.",
  ui_story_5057_50570202_70_dialog_content = "Tidak, saya baru saja tiba di sini... Oh, terima kasih.",
  ui_story_5057_50570202_71_dialog_content = "Ayo, PlayerName, ceritakan siapa yang kamu tertarik di antara kerumunan.",
  ui_story_5057_50570202_72_dialog_content = "Uh, apakah kita benar-benar melakukan ini? Saya tidak suka mendekati orang asing dengan niat seperti itu...",
  ui_story_5057_50570202_73_dialog_content = "Jangan terlalu dipikirkan. Ini hanya latihan, tidak merugikan siapa pun.",
  ui_story_5057_50570202_74_dialog_content = "Tapi jika kamu masih terganggu tentang hal itu, kita harus menghentikannya.",
  ui_story_5057_50570202_75_dialog_content = "Seseorang yang tidak menikmati prosesnya tidak akan pernah bisa menggoyahkan buruannya.",
  ui_story_5057_50570202_76_dialog_content = "Tapi karena kita di sini, kenapa kita berdua tidak sekedar hang out dan bersenang-senang saja?",
  ui_story_5057_50570202_77_dialog_content = "Kita berdua?",
  ui_story_5057_50570202_78_dialog_content = "Saya tidak masalah dengan itu, tapi saya merasa kamu yang mengatur semua ini...",
  ui_story_5057_50570202_79_dialog_content = "Apa yang kalian berdua lakukan di sini?",
  ui_story_5057_50570202_80_dialog_content = "Lorelei?!",
  ui_story_5057_50570202_81_dialog_content = "Cena pergi dengan gembira, jadi saya mengikuti.",
  ui_story_5057_50570202_82_dialog_content = "Saya yakin dia lagi deketin cewek lagi. Siapa korban kali ini?",
  ui_story_5057_50570202_83_dialog_content = "Kamu salah. Aku hanya nongkrong dengan PlayerName hari ini.",
  ui_story_5057_50570202_84_dialog_content = "Nongkrong? Jangan coba-coba menipuku.",
  ui_story_5057_50570202_85_dialog_content = "Ayo, sangat menyakitkan rasanya bosku tidak memercayai aku.",
  ui_story_5057_50570202_86_dialog_content = "Kembali bersamaku dan berhenti merusak Caelestite!",
  ui_story_5057_50570202_87_dialog_content = "Iya, iya...",
  ui_story_5057_50570202_88_dialog_content = "Kita akan lakukan ini lagi nanti, PlayerName!",
  ui_story_5057_50570202_89_dialog_content = "Tidak ada lagi!",
  ui_story_5057_50570202_90_dialog_content = "Hah? Mereka pergi begitu saja?",
  ui_story_5057_50570202_91_dialog_content = "<color=#e8d9bb>Nanti, Cena meminta saya untuk keluar dan mengikuti pelajarannya lagi... Tidak bisa percaya dia orang yang suka mengelak seperti itu.</color>",
  ui_story_5057_50570301_1_dialog_content = "Hmm, saya merasakan sesuatu yang sangat familiar dari kerumunan di sebelah sana.",
  ui_story_5057_50570301_2_dialog_content = "Merasakan berendam dalam cahaya matahari yang berkilauan dan dikelilingi oleh tanaman subur di hutan...",
  ui_story_5057_50570301_3_dialog_content = "Halo, PlayerName, senang bertemu denganmu begitu cepat.",
  ui_story_5057_50570301_4_dialog_content = "Naroxel! Aku tahu itu kamu!",
  ui_story_5057_50570301_5_dialog_content = "Sepertinya kau terkejut.",
  ui_story_5057_50570301_6_dialog_content = "Oh, tidak, tidak sama sekali.",
  ui_story_5057_50570301_7_dialog_content = "Bagaimana cara mengatakannya...",
  ui_story_5057_50570301_8_dialog_content = "Saya cukup terkejut bahwa saya bisa merasakan kehadiranmu tanpa menggunakan kemampuan psikis saya, Naroxel.",
  ui_story_5057_50570301_9_dialog_content = "Suasana udara unik yang kamu miliki... sangat khas.",
  ui_story_5057_50570301_10_dialog_content = "Oh...?",
  ui_story_5057_50570301_11_dialog_content = "(Upss, apakah saya baru saja mengatakan sesuatu yang menyinggung?)",
  ui_story_5057_50570301_12_dialog_content = "Bisakah saya menganggap bahwa kamu memiliki kesan yang baik tentang saya, PlayerName?",
  ui_story_5057_50570301_13_dialog_content = "Oh, ya, tentu saja!",
  ui_story_5057_50570301_14_dialog_content = "Mungkin itu karena kami, Kaum Caelestite, dekat dengan alam.",
  ui_story_5057_50570301_15_dialog_content = "Itulah mengapa aku merasa ada kecocokan dengan kamu saat aku melihatmu.",
  ui_story_5057_50570301_16_dialog_content = "Aku tahu. Senang rasanya kamu begitu menghargai aku.",
  ui_story_5057_50570301_17_dialog_content = "Ngomong-ngomong, kamu lagi sibuk nggak sekarang, PlayerName?",
  ui_story_5057_50570301_18_dialog_content = "Jika demikian, saya ingin meminta Anda untuk menunjukkan kepada saya di sekitar taman.",
  ui_story_5057_50570301_19_dialog_content = "Saya memiliki beberapa hari libur dan akan menghabiskannya di resor ini.",
  ui_story_5057_50570301_20_dialog_content = "Tapi saya masih belum terbiasa dengan wahana yang lebih besar dan belum yakin bagaimana cara benar-benar rileks.",
  ui_story_5057_50570301_21_dialog_content = "Aku membayangkan aku akan jauh lebih bahagia bersama kamu.",
  ui_story_5057_50570301_22_option_content = "Tentu saja, tidak masalah!",
  ui_story_5057_50570301_23_dialog_content = "Saya tahu seluruh resor ini seperti telapak tangan saya sendiri!",
  ui_story_5057_50570301_24_dialog_content = "Biarkan saya menentukan Tur Khusus Caelestite yang dipandu khusus untuk Anda.",
  ui_story_5057_50570301_25_option_content = "Hmm…",
  ui_story_5057_50570301_26_dialog_content = "Apakah kamu memiliki bisnis lain yang harus diurus?",
  ui_story_5057_50570301_27_dialog_content = "Aku tidak seharusnya menahanmu, jadi...",
  ui_story_5057_50570301_28_dialog_content = "Tidak sama sekali! Saya baru saja merencanakan Tur Khusus Caelestite untuk kamu.",
  ui_story_5057_50570301_29_dialog_content = "Lalu, saya mengandalkan kamu, PlayerName.",
  ui_story_5057_50570301_30_dialog_content = "Huff... Tidak bisa percaya aku basah dari kepala sampai kaki.",
  ui_story_5057_50570301_31_dialog_content = "Apa pendapat Anda tentang perjalanan cepat Bluefire Lava ini?",
  ui_story_5057_50570301_32_dialog_content = "Saat mengirim Anda dari ketinggian ke arus, Anda disemprot dengan pancuran air hangat.",
  ui_story_5057_50570301_33_dialog_content = "Pasangkan itu dengan pemandangan yang meniru gunung api dan efek pencahayaan serta suara yang dirancang dengan baik...",
  ui_story_5057_50570301_34_dialog_content = "Pasti akan menciptakan sensasi mendebarkan saat melarikan diri dari gunung api yang akan meletus!",
  ui_story_5057_50570301_35_dialog_content = "Bagaimana perasaanmu, Naroxel? Apakah kegembiraan mengangkat setiap tekanan dari bahunya?",
  ui_story_5057_50570301_36_dialog_content = "Sangat menarik, benar.",
  ui_story_5057_50570301_37_dialog_content = "Ini mengingatkan saya pada tugas kurir ketika saya melewati gunung api yang sedang meletus.",
  ui_story_5057_50570301_38_dialog_content = "Sangat berbahaya. Saya membawa tas selempang penuh dan berlari secepat yang saya bisa.",
  ui_story_5057_50570301_39_dialog_content = "Saya beberapa kali hampir menghadapi malapetaka sebelum akhirnya melarikan diri dari sekitar dan menjaga pesan tetap utuh.",
  ui_story_5057_50570301_40_dialog_content = "Evemeskipun saya menyelesaikan semuanya tepat waktu...",
  ui_story_5057_50570301_41_dialog_content = "Pakaianku terbakar. Aku masih ingat betapa buruknya itu bagiku.",
  ui_story_5057_50570301_42_dialog_content = "Tidak banyak orang yang bisa melakukan itu, Naroxel...",
  ui_story_5057_50570301_43_dialog_content = "Kurasa wahana ini kurang seru untukmu. Ayo ke wahana selanjutnya!",
  ui_story_5057_50570301_44_dialog_content = "Huff... bagaimana dengan yang ini?",
  ui_story_5057_50570301_45_dialog_content = "Brain Blender menampilkan 22 terjun bebas... Angka itu diduga berdasarkan... *retch*",
  ui_story_5057_50570301_46_dialog_content = "Kau baik-baik saja, PlayerName?",
  ui_story_5057_50570301_47_dialog_content = "Aku baik-baik saja, terima kasih...",
  ui_story_5057_50570301_48_dialog_content = "Saya sangat pusing di wahana itu, hampir pingsan, tapi kamu menikmati pemandangannya seperti bukan apa-apa...",
  ui_story_5057_50570301_49_dialog_content = "Sejujurnya, ini adalah pertama kalinya saya menikmati pemandangan dari ketinggian seperti itu.",
  ui_story_5057_50570301_50_dialog_content = "Jadi, saya tidak bisa tidak tenggelam dalamnya.",
  ui_story_5057_50570301_51_dialog_content = "Hmm, sepertinya wahana seperti ini terlalu biasa untukmu, Naroxel...",
  ui_story_5057_50570301_52_dialog_content = "Astaga, mesin ini gila! Gigi palsu emas baruku hampir terlempar dari mulutku!",
  ui_story_5057_50570301_53_dialog_content = "Kamu bilang itu gila? Saya pernah dengar tentang anak ini yang dilempar ke kolam renang dan kemudian langsung menghilang.",
  ui_story_5057_50570301_54_dialog_content = "Setelah itu, setiap orang yang mengendarai Brain Blender dan mencapai puncak tanpa menutup mata akan mendengar isak tangisnya di malam hari.",
  ui_story_5057_50570301_55_dialog_content = "...",
  ui_story_5057_50570301_56_dialog_content = "Naroxel?",
  ui_story_5057_50570301_57_dialog_content = "T-Tidak ada.",
  ui_story_5057_50570301_58_dialog_content = "Dari mana kamu dengar ini? Bukankah ini taman hiburan baru? Bagaimana bisa ada kecelakaan seperti itu?",
  ui_story_5057_50570301_59_dialog_content = "Lihat, tertulis di papan tanda itu, \"Legenda Blender Otak.\"",
  ui_story_5057_50570301_60_dialog_content = "Tidak bisa percaya kamu mau bagikan konten promosi ke orang lain seperti itu cerita yang benar...",
  ui_story_5057_50570301_61_dialog_content = "...",
  ui_story_5057_50570301_62_dialog_content = "Haha, sepertinya ini hanya cerita Cena yang dibuat untuk membangkitkan semangat perjalanan.",
  ui_story_5057_50570301_63_dialog_content = "Jadi, kemana kita harus pergi selanjutnya? Masih banyak wahana seru di sekitar sini!",
  ui_story_5057_50570301_64_dialog_content = "Saya tidak ingin bersikap kasar, tetapi apakah ada tempat dekat untuk beristirahat?",
  ui_story_5057_50570301_65_dialog_content = "Ada tempat berkemah kecil dekat sini dengan tanaman yang subur.",
  ui_story_5057_50570301_66_dialog_content = "Saya ingin pergi ke sana, silakan.",
  ui_story_5057_50570301_67_dialog_content = "Fiuh, lokasi yang hijau seperti ini benar-benar menenangkan.",
  ui_story_5057_50570301_68_dialog_content = "Apakah kamu keberatan jika aku berbaring sebentar?",
  ui_story_5057_50570301_69_dialog_content = "Tidak sama sekali!",
  ui_story_5057_50570301_70_dialog_content = "Semua tumpangan yang kamu berikan sangat menyenangkan dan menggembirakan.",
  ui_story_5057_50570301_71_dialog_content = "Tapi aku merasa benar-benar nyaman di sini, terutama saat kamu bersamaku.",
  ui_story_5057_50570301_72_dialog_content = "Yang ingin saya sampaikan adalah, semoga saya tidak merusak tur spesial yang telah kamu rencanakan untuk saya.",
  ui_story_5057_50570301_73_dialog_content = "Tidak mungkin. Selama kamu senang, aku senang.",
  ui_story_5057_50570301_74_dialog_content = "(Perasaan dikelilingi tanaman hijau ketika saya bertemu Naroxel telah menjadi kenyataan yang nyata...)",
  ui_story_5057_50570301_75_dialog_content = "Saya rasa saya benar-benar tenggelam dalam semua hijau ini...",
  ui_story_5057_50570301_76_dialog_content = "Zzzzz...",
  ui_story_5057_50570301_77_dialog_content = "Hah?",
  ui_story_5057_50570301_78_dialog_content = "(Naroxel tertidur.)",
  ui_story_5057_50570301_79_dialog_content = "(Wajahnya tenang dan damai, bahkan tersenyum.)",
  ui_story_5057_50570301_80_dialog_content = "Hmm...",
  ui_story_5057_50570301_81_dialog_content = "(Aku harus meninggalkannya sendiri untuk saat ini...)",
  ui_story_5057_50570301_82_dialog_content = "<color=#e8d9bb>Nantinya, saya khawatir Naroxel mungkin akan kedinginan, jadi saya menutupinya dengan pakaian saya.</color>",
  ui_story_5057_50570302_1_dialog_content = "Maaf, PlayerName, saya tidak sengaja tertidur.",
  ui_story_5057_50570302_2_dialog_content = "Jangan khawatir. Kamu terlihat jauh lebih baik sekarang.",
  ui_story_5057_50570302_3_dialog_content = "Ya, sudah lama sekali sejak terakhir kali saya bisa bersantai di lingkungan ini.",
  ui_story_5057_50570302_4_dialog_content = "Saya merasa istirahat secara fisik dan mental.",
  ui_story_5057_50570302_5_dialog_content = "Itu luar biasa.",
  ui_story_5057_50570302_6_dialog_content = "Sebenarnya, saya punya permintaan...",
  ui_story_5057_50570302_7_dialog_content = "Beritahu saya dan akan kucoba semampuku.",
  ui_story_5057_50570302_8_dialog_content = "Bisakah kita lewati semua wahana seru nanti?",
  ui_story_5057_50570302_9_dialog_content = "Tentu!",
  ui_story_5057_50570302_10_dialog_content = "Untuk wahana yang tidak terlalu menegangkan, kita bisa mencoba bianglala.",
  ui_story_5057_50570302_11_dialog_content = "Ini menghadap seluruh resor, dan pemandangan dari atas sangat bagus!",
  ui_story_5057_50570302_12_dialog_content = "Atau jika Anda menginginkan suasana alam, opsi dek observasi jurang tersedia.",
  ui_story_5057_50570302_13_dialog_content = "Ini memiliki pemandangan yang megah dengan banyak jalur untuk mendaki.",
  ui_story_5057_50570302_14_dialog_content = "Oh, dan ada hutan sungai di bawah tebing itu. Kamu pasti akan menyukainya.",
  ui_story_5057_50570302_15_dialog_content = "Itu dekat dengan tempat kita berada sekarang.",
  ui_story_5057_50570302_16_dialog_content = "Hutan sungai... Itu memang terdengar santai dan menenangkan.",
  ui_story_5057_50570302_17_dialog_content = "Ayo pergi ke sana.",
  ui_story_5057_50570302_18_dialog_content = "Betapa mempesonanya ini...",
  ui_story_5057_50570302_19_dialog_content = "Aliran sungai jernih dan hutan yang subur benar-benar bisa membuatmu rileks.",
  ui_story_5057_50570302_20_dialog_content = "Aroma kaya dari tanaman di udara juga sangat menyegarkan.",
  ui_story_5057_50570302_21_dialog_content = "Terima kasih, PlayerName, telah menunjukkan pemandangan indah ini kepada saya.",
  ui_story_5057_50570302_22_dialog_content = "Aku senang kau menyukainya.",
  ui_story_5057_50570302_23_dialog_content = "Kemari, PlayerName.",
  ui_story_5057_50570302_24_dialog_content = "Ada apa?",
  ui_story_5057_50570302_25_dialog_content = "Ini adalah merica, dapat digunakan sebagai bumbu setelah kamu menggilingnya.",
  ui_story_5057_50570302_26_dialog_content = "Ini pedas dan pelengkap yang bagus untuk hidangan di musim dingin.",
  ui_story_5057_50570302_27_dialog_content = "Inilah konjac, yang konon bisa menyadarkan pikiran Anda. Itu dimakan di banyak tempat.",
  ui_story_5057_50570302_28_dialog_content = "Oh, dan pohon ini di sini, seratnya cukup fleksibel dan tahan lama untuk diolah menjadi tali busur.",
  ui_story_5057_50570302_29_dialog_content = "Saya tidak tahu kamu memiliki pemahaman yang mendalam tentang tanaman, Naroxel.",
  ui_story_5057_50570302_30_dialog_content = "Nah, kurir terkadang menghadapi situasi tak terduga dalam pengiriman mereka.",
  ui_story_5057_50570302_31_dialog_content = "Jadi, bagian dari pekerjaan kita adalah mempelajari hal-hal yang dapat membantu orang lain.",
  ui_story_5057_50570302_32_dialog_content = "Kurir terdengar seperti pilihan karier yang sangat mengesankan...",
  ui_story_5057_50570302_33_dialog_content = "Hahaha... Dove selalu muncul dalam pikiran saya saat membahas kurir, mungkin karena dia meninggalkan kesan yang besar pada saya.",
  ui_story_5057_50570302_34_dialog_content = "Dove suka bersantai, tapi dia memang membantu kamu banyak, bukan?",
  ui_story_5057_50570302_35_dialog_content = "Itu mengingatkan saya! Lumamber di awal-awal berasal dari Dove.",
  ui_story_5057_50570302_36_dialog_content = "Saya senang kurir berperan dalam perjalanan Anda, PlayerName.",
  ui_story_5057_50570302_37_dialog_content = "Ah, lihat ke sana.",
  ui_story_5057_50570302_38_dialog_content = "Daun-daun memiliki pola yang khas. Ini bisa jadi spesies unik khusus di daerah ini.",
  ui_story_5057_50570302_39_dialog_content = "Oh ya? Biarku lihat.",
  ui_story_5057_50570302_40_dialog_content = "(Naroxel terasa berbeda hari ini entah kenapa, tapi aku tidak bisa menjelaskannya dengan pasti...)",
  ui_story_5057_50570302_41_dialog_content = "PlayerName?",
  ui_story_5057_50570302_42_dialog_content = "Maaf! Saya tidak bermaksud menatap, hanya melamun sebentar!",
  ui_story_5057_50570302_43_dialog_content = "Sangat lembab di oasis, terkadang menyebabkan sesak napas dan kehilangan fokus.",
  ui_story_5057_50570302_44_dialog_content = "Ayo lanjut.",
  ui_story_5057_50570302_45_dialog_content = "Tentu. Hati-hati langkahmu dan jangan tersandung.",
  ui_story_5057_50570302_46_dialog_content = "Terima kasih untuk pengingatnya.",
  ui_story_5057_50570302_47_dialog_content = "(Apakah aku melihat sesuatu?)",
  ui_story_5057_50570302_48_dialog_content = "(Ada kesedihan di mata Naroxel.)",
  ui_story_5057_50570302_49_dialog_content = "Sebenarnya... saya sangat senang menghabiskan liburan bersama kamu, PlayerName.",
  ui_story_5057_50570302_50_dialog_content = "Apa?",
  ui_story_5057_50570302_51_dialog_content = "Saya telah menyukai Caelestite dan cara hidup mereka sejak lama.",
  ui_story_5057_50570302_52_dialog_content = "Karena saya memiliki darah setengah manusia yang biasanya tidak menyukai musim dingin, namun saya lahir di Northland...",
  ui_story_5057_50570302_53_dialog_content = "Saya selalu merindukan Eraveil yang menyenangkan dan beriklim sedang sepanjang waktu.",
  ui_story_5057_50570302_54_dialog_content = "Tapi ketika saya mengantar di sana, tempat itu tidak dikenali dan tidak ada kehidupan...",
  ui_story_5057_50570302_55_dialog_content = "Ya...",
  ui_story_5057_50570302_56_option_content = "Tapi saya tidak akan menyerah pada rumah saya.",
  ui_story_5057_50570302_57_dialog_content = "Eraveil berarti segalanya bagi saya, dan suatu hari nanti saya akan mengembalikan kemegahannya.",
  ui_story_5057_50570302_58_option_content = "Kini sudah menjadi reruntuhan.",
  ui_story_5057_50570302_59_dialog_content = "Saya tidak yakin apakah saya memiliki kemampuan untuk mengembalikan kejayaan masa lalu.",
  ui_story_5057_50570302_60_dialog_content = "Kamu harus percaya pada diri sendiri dan teman-temanmu.",
  ui_story_5057_50570302_61_dialog_content = "Kamu benar, Naroxel.",
  ui_story_5057_50570302_62_dialog_content = "Aku tahu aku tidak salah tentangmu.",
  ui_story_5057_50570302_63_dialog_content = "Saya senang kamu tidak lari dari tanggung jawabmu dan memilih untuk membangun kembali Eraveil.",
  ui_story_5057_50570302_64_dialog_content = "Saya tahu akan ada banyak rintangan di depan, tetapi kamu punya bantuan dari saya.",
  ui_story_5057_50570302_65_dialog_content = "(Naroxel memegang tanganku dan aku merasa tangannya dingin.)",
  ui_story_5057_50570302_66_dialog_content = "Untuk masa depan Kaum Caelestite dan Eraveil.",
  ui_story_5057_50570302_67_dialog_content = "<color=#e8d9bb>Kemudian kami naik bianglala bersama, Naroxel dan saya, dan menikmati pemandangan malam di Denuo Valley Resort.</color>",
  ui_story_5057_50570401_1_dialog_content = "Di mana tamunya? Hanya satu menit lagi dari waktu yang kita sepakati untuk bertemu...",
  ui_story_5057_50570401_2_dialog_content = "PlayerName...?",
  ui_story_5057_50570401_3_dialog_content = "Suara itu... Michenny?",
  ui_story_5057_50570401_4_dialog_content = "Kamu bukan pemandunya, bukan, PlayerName?",
  ui_story_5057_50570401_5_dialog_content = "Saya! Kamu tamunya, aku tahu. Tidak heran kamu tepat waktu.",
  ui_story_5057_50570401_6_dialog_content = "Aku tersanjung. Ngomong-ngomong, bagaimana kamu bisa bekerja sebagai pemandu di sini?",
  ui_story_5057_50570401_7_dialog_content = "Nah, eh... Ini persis seperti yang terlihat, saya mengambil pekerjaan...",
  ui_story_5057_50570401_8_dialog_content = "Pekerjaan? Aku paham, itu saat kamu menukar waktu kamu dengan uang.",
  ui_story_5057_50570401_9_dialog_content = "Ya, itu deskripsi yang sangat akurat!",
  ui_story_5057_50570401_10_dialog_content = "Baiklah, sepertinya aku akan membiarkan kamu memimpin jalan, PlayerName.",
  ui_story_5057_50570401_11_dialog_content = "Ya, serahkan padaku!",
  ui_story_5057_50570401_12_dialog_content = "Biru Langit, Matriks Fantasi, Naga Malam Putih, Tembakan Halo... Kami sudah mencoba semuanya.",
  ui_story_5057_50570401_13_dialog_content = "Semua berkat kamu, PlayerName. Mungkin aku tidak akan bisa mencoba begitu banyak sendirian.",
  ui_story_5057_50570401_14_dialog_content = "Di sini, minumlah. Baru saja saya dinginkan dengan Luminatics.",
  ui_story_5057_50570401_15_dialog_content = "Terima kasih!",
  ui_story_5057_50570401_16_dialog_content = "Glek, glek...",
  ui_story_5057_50570401_17_dialog_content = "Ah—! Jauh lebih enak saat dingin.",
  ui_story_5057_50570401_18_dialog_content = "Setelah semua, tujuan datang ke taman adalah untuk bersenang-senang.",
  ui_story_5057_50570401_19_dialog_content = "Senang juga melihat kamu menepikan tata krama demi kesenangan murni.",
  ui_story_5057_50570401_20_dialog_content = "Saya sangat bahagia, benar.",
  ui_story_5057_50570401_21_dialog_content = "Sangat menyenangkan di sini, dengan banyak hal baru.",
  ui_story_5057_50570401_22_dialog_content = "Oh, apa ini, PlayerName?",
  ui_story_5057_50570401_23_dialog_content = "Ini mesin cakar!",
  ui_story_5057_50570401_24_dialog_content = "Mesin cakar? Aku tak paham.",
  ui_story_5057_50570401_25_dialog_content = "Izinkan saya untuk mendemonstrasikan.",
  ui_story_5057_50570401_26_dialog_content = "Pertama, masukkan beberapa koin.",
  ui_story_5057_50570401_27_dialog_content = "Tunggu sebentar... Itu lima koin, kanan?",
  ui_story_5057_50570401_28_dialog_content = "Ya. Ini menginginkan lima Nightium karena yang satu ini memiliki hadiah yang lebih baik.",
  ui_story_5057_50570401_29_dialog_content = "Setelah memasukkan koin, gunakan tongkat untuk mengatur posisi cakar untuk mengambil.",
  ui_story_5057_50570401_30_dialog_content = "Sekarang pilih sesuatu yang kamu suka!",
  ui_story_5057_50570401_31_dialog_content = "Oke!",
  ui_story_5057_50570401_32_dialog_content = "Pindahkan cakar di atas objek dengan menggunakan tongkat.",
  ui_story_5057_50570401_33_dialog_content = "Lihat dari semua arah untuk menentukan sudut, dan arahkan cakar ke arah itu.",
  ui_story_5057_50570401_34_dialog_content = "Kemudian tekan tombolnya!",
  ui_story_5057_50570401_35_dialog_content = "Wow, ini sedang turun.",
  ui_story_5057_50570401_36_dialog_content = "Ini sudah di genggaman!",
  ui_story_5057_50570401_37_dialog_content = "Ya. Sekarang tunggu cakar untuk mengambil dan menjatuhkannya di kotak hadiah.",
  ui_story_5057_50570401_38_dialog_content = "Aku sangat gugup...",
  ui_story_5057_50570401_39_dialog_content = "Ah!",
  ui_story_5057_50570401_40_dialog_content = "Cakar berputar tepat sebelum menjatuhkannya.",
  ui_story_5057_50570401_41_dialog_content = "Itu terjadi kadang-kadang. Lebih sering kamu gagal mendapatkan hadiah.",
  ui_story_5057_50570401_42_dialog_content = "Jadi apa yang terjadi pada koin saat kamu gagal?",
  ui_story_5057_50570401_43_dialog_content = "Uh, kamu menghabiskannya dan sekarang sudah habis?",
  ui_story_5057_50570401_44_dialog_content = "Apa?!",
  ui_story_5057_50570401_45_dialog_content = "K-Kenapa?",
  ui_story_5057_50570401_46_dialog_content = "Saya tidak mendapatkan hadiah. Bukankah itu berarti saya berhak atas pengembalian dana?",
  ui_story_5057_50570401_47_dialog_content = "Hmm, bagaimana ya menjelaskannya...",
  ui_story_5057_50570401_48_dialog_content = "Kamu jelas telah berusaha dan mengeluarkan uang, tetapi tidak mendapatkan hasil apa pun.",
  ui_story_5057_50570401_49_dialog_content = "Berdasarkan waktu yang dihabiskan, ini setidaknya bernilai lima puluh Nightium.",
  ui_story_5057_50570401_50_dialog_content = "Betulkah? Menurutku, waktunya hanya layak sepuluh Nightium, sejauh yang aku tahu.",
  ui_story_5057_50570401_51_dialog_content = "Hari ini tidak sama!",
  ui_story_5057_50570401_52_dialog_content = "Baiklah…",
  ui_story_5057_50570401_53_option_content = "Apakah karena hari ini liburan?",
  ui_story_5057_50570401_54_dialog_content = "Ya! Bekerja saat liburan dibayar lima kali lipat dari tarif biasa!",
  ui_story_5057_50570401_55_option_content = "Apakah karena saya bekerja sebagai pemandu?",
  ui_story_5057_50570401_56_dialog_content = "Ya. Sebagai pemandu, kamu jauh lebih berharga.",
  ui_story_5057_50570401_57_dialog_content = "Belum lagi menurutku kamu adalah pemandu yang sangat baik dan pantas mendapatkan bonus.",
  ui_story_5057_50570401_58_dialog_content = "Betulkah? Aku baik-baik saja asalkan kamu senang!",
  ui_story_5057_50570401_59_dialog_content = "Juga, usaha yang kamu lakukan seharusnya meminta tambahan lima puluh Nightium!",
  ui_story_5057_50570401_60_dialog_content = "Bersama-sama itu menjadi seratus-lima Nightium, atau dua-ratus-lima untuk dua orang!",
  ui_story_5057_50570401_61_dialog_content = "T-Tunggu sebentar, Michenny!",
  ui_story_5057_50570401_62_dialog_content = "Ini hanya permainan. Kamu tidak bisa melihatnya dengan cara yang sama.",
  ui_story_5057_50570401_63_dialog_content = "Hah?",
  ui_story_5057_50570401_64_dialog_content = "Mari saya katakan begini, kita menghabiskan uang untuk pengalaman, bukan hasilnya.",
  ui_story_5057_50570401_65_dialog_content = "Yang penting di sini adalah menikmati proses yang menyenangkan bersama teman-teman.",
  ui_story_5057_50570401_66_dialog_content = "Begitu juga untuk game ini. Saya menghabiskan koin karena ingin kamu menikmati mesin ini.",
  ui_story_5057_50570401_67_dialog_content = "Menarik...",
  ui_story_5057_50570401_68_dialog_content = "Peluang untuk mendapatkan hadiah rendah, jadi saya tidak mengharapkan apa pun.",
  ui_story_5057_50570401_69_dialog_content = "Saya mengerti...",
  ui_story_5057_50570401_70_dialog_content = "(Saya rasa Michenny mulai mengerti.)",
  ui_story_5057_50570401_71_dialog_content = "Menghabiskan uang untuk membeli pengalaman....",
  ui_story_5057_50570401_72_dialog_content = "Benar.",
  ui_story_5057_50570401_73_dialog_content = "Dan kepuasan emosional dari itu...",
  ui_story_5057_50570401_74_dialog_content = "Benar!",
  ui_story_5057_50570401_75_dialog_content = "Dengan kesempatan untuk mendapatkan hadiah...",
  ui_story_5057_50570401_76_dialog_content = "Ya, itu persisnya!",
  ui_story_5057_50570401_77_dialog_content = "itu...",
  ui_story_5057_50570401_78_dialog_content = "Judi!",
  ui_story_5057_50570401_79_dialog_content = "Saya harus mengaudit kamu sesuai dengan peraturan Lumopolis!",
  ui_story_5057_50570401_80_dialog_content = "W-Wah, jangan membuka paksa lubang koin!",
  ui_story_5057_50570401_81_dialog_content = "<color=#e8d9bb>Kemudian saya berusaha keras untuk membujuk Michenny dan membawanya untuk memenangkan banyak boneka dari mesin cakar.</color>",
  ui_story_5057_50570402_1_dialog_content = "Ehem...",
  ui_story_5057_50570402_2_dialog_content = "Selamat pagi, PlayerName.",
  ui_story_5057_50570402_3_dialog_content = "Pagi, Michenny.",
  ui_story_5057_50570402_4_dialog_content = "Uh, maaf karena kehilangan kendali saat terakhir kali.",
  ui_story_5057_50570402_5_dialog_content = "Hah? Oh, kamu maksud dengan mesin cakar?",
  ui_story_5057_50570402_6_dialog_content = "Saya tidak pikir kamu kehilangan ketenanganmu.",
  ui_story_5057_50570402_7_option_content = "Saya pikir itu cukup lucu.",
  ui_story_5057_50570402_8_dialog_content = "Karena kamu selalu serius sepanjang waktu...",
  ui_story_5057_50570402_9_dialog_content = "Aku menyebutnya melihat sisi lebih rendah hati dari dirimu, dan itu perbedaan yang besar.",
  ui_story_5057_50570402_10_dialog_content = "Ehem... Menurutmu begitu, ya?",
  ui_story_5057_50570402_11_option_content = "Setiap orang terkadang menjadi emosional.",
  ui_story_5057_50570402_12_dialog_content = "Saya yakin itu juga terjadi pada kamu kadang-kadang, Michenny.",
  ui_story_5057_50570402_13_dialog_content = "Maaf kau harus menyaksikannya.",
  ui_story_5057_50570402_14_dialog_content = "Maukah kamu menjadi pemandu saya lagi hari ini, PlayerName?",
  ui_story_5057_50570402_15_dialog_content = "Saya dengan senang hati!",
  ui_story_5057_50570402_16_dialog_content = "Fiuh, banyak juga yang dihabiskan di toko souvenir.",
  ui_story_5057_50570402_17_dialog_content = "Menakutkan betapa banyak barang yang Michenny beli...",
  ui_story_5057_50570402_18_dialog_content = "Kamu merasa ini menakutkan?",
  ui_story_5057_50570402_19_dialog_content = "Kamu tidak berpikir boneka kadal gurun ini imut?",
  ui_story_5057_50570402_20_dialog_content = "Dan kotak ini memiliki permen dengan rasa aneh dari seluruh dunia... Harus beli dalam jumlah besar untuk dibagikan dengan rekan kerja dan teman di rumah.",
  ui_story_5057_50570402_21_dialog_content = "Lalu ada koin peringatan. Ini bukan alat pembayaran yang sah, tetapi gambarnya sangat bagus.",
  ui_story_5057_50570402_22_dialog_content = "Ini akan mengingatkanku pada kesenangan yang kuhadapi bersama PlayerName di sini saat melihatnya.",
  ui_story_5057_50570402_23_dialog_content = "Koin ini memiliki nilai yang jauh melampaui koin biasa.",
  ui_story_5057_50570402_24_dialog_content = "Bukankah itu pelajaran yang kamu ajarkan padaku, PlayerName?",
  ui_story_5057_50570402_25_dialog_content = "Uh, ya, sepertinya begitu.",
  ui_story_5057_50570402_26_dialog_content = "Setelah semua, kamu sedang berlibur langka, jadi kamu harus menghabiskan uang untuk apa yang kamu inginkan dan suka.",
  ui_story_5057_50570402_27_dialog_content = "Sulit untuk menghabiskan uang, bagaimanapun, saat kamu terlalu sibuk bekerja sepanjang waktu.",
  ui_story_5057_50570402_28_dialog_content = "Hiduplah sepenuhnya, yang berarti ketika waktunya tepat, uang yang dihabiskan memiliki arti yang jauh lebih besar dari biasanya.",
  ui_story_5057_50570402_29_dialog_content = "Saya percaya itu yang kamu ajarkan pada saya waktu itu.",
  ui_story_5057_50570402_30_dialog_content = "Wow, kamu cepat belajar, Michenny.",
  ui_story_5057_50570402_31_dialog_content = "Jadi kenapa kamu terlihat terkejut?",
  ui_story_5057_50570402_32_dialog_content = "Karena itu tidak terdengar seperti yang biasanya kamu katakan, sepertinya aku melihat sisi lain dari Michenny!",
  ui_story_5057_50570402_33_dialog_content = "Tentu saja, sifat beragam dari orang-orang membuat sulit untuk mengukur mereka dengan uang.",
  ui_story_5057_50570402_34_dialog_content = "Memiliki berbagai emosi dan penampilan yang berbeda juga memiliki nilai tersendiri dalam arti tertentu.",
  ui_story_5057_50570402_35_dialog_content = "Mengenai kamu melihat sisi lain dariku, aku akan menganggap itu sebagai pujian.",
  ui_story_5057_50570402_36_dialog_content = "Tentu saja!",
  ui_story_5057_50570402_37_dialog_content = "Fiuh, aku dalam suasana hati yang jauh lebih bahagia setelah berbelanja...",
  ui_story_5057_50570402_38_dialog_content = "Hei, bangunan apa itu di sana? Saya rasa kita belum pernah ke sana.",
  ui_story_5057_50570402_39_dialog_content = "Oh, itu adalah atraksi yang belum dibuka untuk umum, tetapi sepertinya mereka sedang mengujinya sekarang.",
  ui_story_5057_50570402_40_dialog_content = "Hmm…",
  ui_story_5057_50570402_41_dialog_content = "Ayo kita lihat. Pengalaman menyeluruh akan lebih bernilai seratus Nightium daripada kenangan menyesal pergi.",
  ui_story_5057_50570402_42_dialog_content = "Hah? Tunggu, Michenny!",
  ui_story_5057_50570402_43_dialog_content = "Berhentilah berlari! Berbahaya mengunjungi atraksi yang belum dibuka!",
  ui_story_5057_50570402_44_dialog_content = "Hey, kenapa pintu ini tidak bisa dibuka?",
  ui_story_5057_50570402_45_dialog_content = "Bukankah itu sempurna? Sulit untuk mendapatkan seluruh premis untuk diri sendiri.",
  ui_story_5057_50570402_46_dialog_content = "Tidak mungkin! Saya juga tidak bisa mengerti apa-apa... Bagaimana kita bisa menikmatinya?",
  ui_story_5057_50570402_47_dialog_content = "*menangis*...",
  ui_story_5057_50570402_48_dialog_content = "Tunggu sebentar, aku dengar sesuatu...",
  ui_story_5057_50570402_49_dialog_content = "Jeritan menyeramkan itu... Apakah itu Eclipsite?",
  ui_story_5057_50570402_50_dialog_content = "Tidak, saya tidak merasakan Darkflow di mana pun di sini!",
  ui_story_5057_50570402_51_dialog_content = "Apakah ini bisa... *gulp*",
  ui_story_5057_50570402_52_dialog_content = "Apa yang membuatmu menelan, PlayerName...",
  ui_story_5057_50570402_53_dialog_content = "Eh, aku ingat sekarang. Di antara wahana yang belum selesai ada rumah hantu bernama Wraith Frenzy.",
  ui_story_5057_50570402_54_dialog_content = "Penuh dengan hal-hal menakutkan di dalamnya...",
  ui_story_5057_50570402_55_dialog_content = "A-Apa? Itu tidak mungkin... Itu kanak-kanak...",
  ui_story_5057_50570402_56_dialog_content = "Aduh…!",
  ui_story_5057_50570402_57_dialog_content = "Eeek!",
  ui_story_5057_50570402_58_dialog_content = "Berhenti mendorong saya, Michenny!",
  ui_story_5057_50570402_59_dialog_content = "Buka pintunya, buka sekarang!",
  ui_story_5057_50570402_60_dialog_content = "Kembalikan... Berikan aku Lumamber-ku, sekarang!!!",
  ui_story_5057_50570402_61_dialog_content = "!!!",
  ui_story_5057_50570402_62_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5057_50570402_63_dialog_content = "M-Michenny...?",
  ui_story_5057_50570402_64_dialog_content = "Jadi, itu bukan Lorelei?",
  ui_story_5057_50570402_65_dialog_content = "<color=#e8d9bb>Jadi, untuk menenangkan Michenny, saya ajak dia makan malam dan memberikan banyak penjelasan tentang cara kerja rumah hantu.</color>",
  ui_story_5057_50570501_1_dialog_content = "Florine...",
  ui_story_5057_50570501_2_dialog_content = "Oh, itu dia.",
  ui_story_5057_50570501_3_dialog_content = "Huft, huft... maaf membuatmu menunggu lama.",
  ui_story_5057_50570501_4_dialog_content = "Tidak apa-apa. Saya juga belum lama di sini.",
  ui_story_5057_50570501_5_dialog_content = "Sebagai ksatria untuk divisi ini, saya memiliki kesabaran.",
  ui_story_5057_50570501_6_dialog_content = "Senang mendengar saya terlambat yang dapat diterima.",
  ui_story_5057_50570501_7_dialog_content = "Setelah mendapatkan pesan Anda, saya segera mengganti pakaian menjadi baju renang dan bergegas ke sana.",
  ui_story_5057_50570501_8_dialog_content = "Hmm…",
  ui_story_5057_50570501_9_dialog_content = "(Sesuatu tentang Florine hari ini...)",
  ui_story_5057_50570501_10_dialog_content = "(Apakah karena dia memakai baju renang?)",
  ui_story_5057_50570501_11_dialog_content = "Sudah cukup melihat, PlayerName?",
  ui_story_5057_50570501_12_dialog_content = "Ups, ketahuan.",
  ui_story_5057_50570501_13_dialog_content = "Rasanya seperti aku berada di bawah cahaya bohlam seribu watt.",
  ui_story_5057_50570501_14_dialog_content = "Maaf, saya tidak bermaksud menatap kamu seperti itu!",
  ui_story_5057_50570501_15_dialog_content = "Uh, baiklah, aku rasa kamu terlihat sangat menggemaskan hari ini, aku tidak bisa menahan diri untuk mencari apa yang membuatmu berbeda.",
  ui_story_5057_50570501_16_dialog_content = "Itu alasan yang cukup lemah, tapi saya menerima.",
  ui_story_5057_50570501_17_dialog_content = "Ngomong-ngomong, kamu juga terus melihat saat terakhir aku mengenakan baju renang.",
  ui_story_5057_50570501_18_dialog_content = "Evemeskipun itu tidak cukup untuk membuat saya marah... atau senang.",
  ui_story_5057_50570501_19_dialog_content = "Kamu harus fokus pada misi yang akan kita jalankan.",
  ui_story_5057_50570501_20_dialog_content = "Ya! Senang kamu tidak marah, Florine.",
  ui_story_5057_50570501_21_dialog_content = "Oh, kamu menyebutkan ada misi untuk hari ini?",
  ui_story_5057_50570501_22_dialog_content = "Kita akan membahas ini saat kita pindah.",
  ui_story_5057_50570501_23_dialog_content = "Tentu saja!",
  ui_story_5057_50570501_24_dialog_content = "Saya bersemangat tentang misi ini. Beritahu saya apa itu.",
  ui_story_5057_50570501_25_dialog_content = "Dan merupakan suatu kehormatan untuk bekerja bersama Florine!",
  ui_story_5057_50570501_26_dialog_content = "Uh, kenapa kamu begitu bersemangat?",
  ui_story_5057_50570501_27_dialog_content = "Mungkin aku menyebutnya misi, tapi sebenarnya tidak ada yang spesial.",
  ui_story_5057_50570501_28_dialog_content = "Sangat mudah, bahkan, dan itu adalah menghabiskan hari libur bersantai di resor.",
  ui_story_5057_50570501_29_dialog_content = "Apa? Itu juga dihitung sebagai misi?",
  ui_story_5057_50570501_30_dialog_content = "Tentu saja, dan saya perlu menulis laporan tentang itu malam ini.",
  ui_story_5057_50570501_31_dialog_content = "Saya tidak perlu mengumpulkannya, tetapi perlu merangkum hari libur.",
  ui_story_5057_50570501_32_dialog_content = "Oke. Haruskah kita ke pantai atau berenang? Mayjadi jalan-jalan atau memancing?",
  ui_story_5057_50570501_33_dialog_content = "Jika ada kerang, kita bisa lihat siapa yang menemukan yang terbesar!",
  ui_story_5057_50570501_34_dialog_content = "Uh, saya tidak punya rencana khusus, jadi kita lihat nanti saat sampai di sana.",
  ui_story_5057_50570501_35_dialog_content = "Namun, kamu tampak sangat antusias.",
  ui_story_5057_50570501_36_dialog_content = "Itu karena hal-hal menarik cenderung terjadi ketika seorang ksatria dari Divisi Investigasi Bidat sedang berlibur bersamaku.",
  ui_story_5057_50570501_37_dialog_content = "Oke, tidak ada yang menarik yang akan terjadi di liburan ini.",
  ui_story_5057_50570501_38_dialog_content = "Saya memiliki perasaan yang kuat!",
  ui_story_5057_50570501_39_dialog_content = "Perasaan? Seperti ada sesuatu yang menarik akan terjadi?",
  ui_story_5057_50570501_40_dialog_content = "Ya!",
  ui_story_5057_50570501_41_dialog_content = "Menarik hanya dengan bersama Florine!",
  ui_story_5057_50570501_42_dialog_content = "Sekarang, itu terlalu jauh...",
  ui_story_5057_50570501_43_dialog_content = "<color=#e8d9bb>Dentang!</color>",
  ui_story_5057_50570501_44_dialog_content = "Ups, maaf.",
  ui_story_5057_50570501_45_dialog_content = "Aku tak apa-apa. Anda tidak terluka, kan?",
  ui_story_5057_50570501_46_dialog_content = "Aku baik-baik saja, trims! Kamu itu lembut dan tampan banget.",
  ui_story_5057_50570501_47_dialog_content = "...",
  ui_story_5057_50570501_48_dialog_content = "Itu ceroboh, hampir menabrakku...",
  ui_story_5057_50570501_49_dialog_content = "...",
  ui_story_5057_50570501_50_dialog_content = "Oh?",
  ui_story_5057_50570501_51_dialog_content = "(F-Florine memiliki tatapan menakutkan di matanya.)",
  ui_story_5057_50570501_52_dialog_content = "Baju renang Anda longgar, PlayerName.",
  ui_story_5057_50570501_53_dialog_content = "Jangan bergerak dan biarkan saya membantu.",
  ui_story_5057_50570501_54_dialog_content = "Apa? Hei?!",
  ui_story_5057_50570501_55_dialog_content = "Tidak terlalu sulit, Florine!",
  ui_story_5057_50570501_56_dialog_content = "Kamu mencekikku!",
  ui_story_5057_50570501_57_dialog_content = "Minum, silakan.",
  ui_story_5057_50570501_58_dialog_content = "Glek, glek...",
  ui_story_5057_50570501_59_dialog_content = "Uh, tentang apa yang baru saja terjadi, aku minta maaf. Aku akui aku kehilangan fokus pada misi.",
  ui_story_5057_50570501_60_dialog_content = "Bagus, kamu dimaafkan.",
  ui_story_5057_50570501_61_dialog_content = "Meskipun kamu tidak perlu minta maaf untuk itu. Kamu bebas melakukan apa saja... asalkan tidak mempengaruhi progress dari tugas tersebut.",
  ui_story_5057_50570501_62_dialog_content = "Oh... Maaf. Jadi, apa yang membuat kamu memutuskan untuk memancing lalu?",
  ui_story_5057_50570501_63_dialog_content = "Karena sangat tenang dan pemandangannya bagus.",
  ui_story_5057_50570501_64_dialog_content = "Ini juga tidak seintensif wahana. Menurutmu tidak enak untuk bersantai dan mengobrol dengan bebas juga?",
  ui_story_5057_50570501_65_dialog_content = "Kamu terlihat lelah dari semua urusan juga... Ini seharusnya memberi kamu lebih banyak waktu untuk bersantai.",
  ui_story_5057_50570501_66_dialog_content = "Benar, akhir-akhir ini aku merasa kehilangan akal... Kamu sangat perhatian, Florine.",
  ui_story_5057_50570501_67_dialog_content = "...",
  ui_story_5057_50570501_68_dialog_content = "Namun, saya belum menangkap satu pun ikan.",
  ui_story_5057_50570501_69_dialog_content = "Takut kalau aku mengusir mereka.",
  ui_story_5057_50570501_70_dialog_content = "Maukah kamu mencoba, Mr. Caelestite yang lembut dan tampan?",
  ui_story_5057_50570501_71_dialog_content = "Aku? Jujur saja, aku cukup pandai dalam hal memancing.",
  ui_story_5057_50570501_72_dialog_content = "Jadi, izinkan saya mencobanya!",
  ui_story_5057_50570501_73_dialog_content = "Baiklah, santai dan bernapas...",
  ui_story_5057_50570501_74_dialog_content = "(Florine telah fokus padaku selama ini.)",
  ui_story_5057_50570501_75_dialog_content = "Uh, seharusnya kamu melihat air, Florine?",
  ui_story_5057_50570501_76_dialog_content = "Sst, saya ingin mempelajari gaya memancingmu.",
  ui_story_5057_50570501_77_dialog_content = "Benarkah? Oke.",
  ui_story_5057_50570501_78_dialog_content = "...!",
  ui_story_5057_50570501_79_dialog_content = "Aku dapat gigitan! Gigitan yang kuat juga!",
  ui_story_5057_50570501_80_dialog_content = "A-Aku tidak bisa menggulungnya. Ini menyeretku ke bawah!",
  ui_story_5057_50570501_81_dialog_content = "Lepaskan saja, PlayerName!",
  ui_story_5057_50570501_82_dialog_content = "<color=#e8d9bb>Guyuran!</color>",
  ui_story_5057_50570501_83_dialog_content = "(Oh, apa yang terjadi...? Sepertinya aku ditarik ke dalam air oleh ikan besar...)",
  ui_story_5057_50570501_84_dialog_content = "(Apa ini benda lembut di bawah kepalaku...?)",
  ui_story_5057_50570501_85_dialog_content = "Hmm... tunggu, apakah itu... Florine?",
  ui_story_5057_50570501_86_dialog_content = "Tentu saja ini aku, PlayerName.",
  ui_story_5057_50570501_87_dialog_content = "Maukah kamu berhenti bermain-main? Seharusnya aku menggunakan kaktus sebagai bantal kamu...",
  ui_story_5057_50570501_88_dialog_content = "M-maaf! Aku akan berdiri sekarang!",
  ui_story_5057_50570501_89_dialog_content = "<color=#e8d9bb>Kemudian, dalam suasana yang cukup halus, saya makan malam bersama Florine. Apakah dia marah atau bagaimana...?</color>",
  ui_story_5057_50570502_1_dialog_content = "Terima kasih atas yang telah kamu lakukan, Florine.",
  ui_story_5057_50570502_2_dialog_content = "Hah?",
  ui_story_5057_50570502_3_dialog_content = "Kamu baru saja menyelamatkan hidupku.",
  ui_story_5057_50570502_4_dialog_content = "Saya akan mengambil ikan, memanggangnya, atau membuatnya menjadi panci panas Longzhou yang saya pelajari terakhir kali untuk mentraktir Anda.",
  ui_story_5057_50570502_5_dialog_content = "Saya tidak menyangka itu akan sekuat ini...",
  ui_story_5057_50570502_6_dialog_content = "Sama-sama.",
  ui_story_5057_50570502_7_dialog_content = "Tapi lupakan ide itu. Ikan itu cukup besar untuk menelan kita berdua.",
  ui_story_5057_50570502_8_dialog_content = "Hah?",
  ui_story_5057_50570502_9_dialog_content = "(Mengapa ada ikan berbahaya seperti ini di sini?)",
  ui_story_5057_50570502_10_dialog_content = "Untungnya, saya mengambil pertolongan pertama sebagai mata kuliah pilihan di semester kedua saya di Dawn Academy.",
  ui_story_5057_50570502_11_dialog_content = "Ehem, padahal hampir tidak ada yang memilih jurusan dan itu benar-benar terlewatkan.",
  ui_story_5057_50570502_X11_dialog_content = "Saya percaya setiap pengetahuan yang menyelamatkan jiwa sangat berharga.",
  ui_story_5057_50570502_12_dialog_content = "Saya berdoa agar tidak perlu menggunakan pengetahuan itu, hanya untuk PlayerName menjadi korban tenggelam pertama yang berhasil saya selamatkan.",
  ui_story_5057_50570502_13_dialog_content = "Menyelamatkan korban tenggelam... Aku ingat Soroz mengajari saya itu.",
  ui_story_5057_50570502_14_dialog_content = "PlayerName, apakah kamu masih ingat cara menyelamatkan seseorang yang tenggelam?",
  ui_story_5057_50570502_15_dialog_content = "Pertama, Anda perlu mengeluarkan orang yang tenggelam dari air.",
  ui_story_5057_50570502_16_dialog_content = "Kemudian, periksa apakah mereka masih bernapas dan memiliki denyut nadi.",
  ui_story_5057_50570502_17_dialog_content = "Jika tidak, segera lakukan tindakan seperti kompresi dada dan pernapasan penyelamatan sampai mereka sadar kembali atau bantuan profesional tiba.",
  ui_story_5057_50570502_18_dialog_content = "Selain itu, jaga agar kepala mereka lebih rendah dari tubuh untuk mencegah muntah masuk ke saluran pernapasan.",
  ui_story_5057_50570502_19_dialog_content = "Lagi, Soroz? Tidak masalah berapa kali kamu mengajari saya, saya tidak akan mendapatkan kesempatan untuk menggunakannya...",
  ui_story_5057_50570502_20_dialog_content = "Tetap semangat, PlayerName. Saya benar-benar berharap kamu tidak perlu menggunakan barang ini.",
  ui_story_5057_50570502_21_dialog_content = "Tetapi jika terjadi insiden yang tak terduga, saya harap Anda dapat menyelamatkan seseorang yang Anda cintai dengan pengetahuan ini.",
  ui_story_5057_50570502_22_dialog_content = "Hmm, biarkan aku berpikir...",
  ui_story_5057_50570502_23_dialog_content = "Aku berbaring di atas pahamu, kan?",
  ui_story_5057_50570502_24_dialog_content = "Ya, karena kamu bernapas lagi.",
  ui_story_5057_50570502_25_dialog_content = "Bernapas lagi? Itu berarti saya berhenti bernapas...",
  ui_story_5057_50570502_26_option_content = "Jadi kamu pasti...!",
  ui_story_5057_50570502_27_dialog_content = "Ini hanya prosedur medis biasa, tidak perlu berteriak!",
  ui_story_5057_50570502_28_dialog_content = "Saya hanya melakukan itu karena kamu tidak sengaja jatuh ke air...",
  ui_story_5057_50570502_29_dialog_content = "A-Dan kamu bangun tepat setelah aku melakukan kompresi dada.",
  ui_story_5057_50570502_30_dialog_content = "Oh begitu...",
  ui_story_5057_50570502_31_option_content = "Jadi, saya pada dasarnya melanjutkan bernapas sendiri!",
  ui_story_5057_50570502_32_dialog_content = "Ya. Siapa tahu, mungkin kamu sebenarnya adalah ikan.",
  ui_story_5057_50570502_33_dialog_content = "Maaf, semua yang bisa kupikirkan saat itu adalah masakan apa yang harus dibuat...",
  ui_story_5057_50570502_34_dialog_content = "Belum lagi aku merasa aneh aman setiap kali bersamamu, Florine.",
  ui_story_5057_50570502_35_dialog_content = "... Sudahlah. Yang penting kamu baik-baik saja. Cukup sulit untuk menjaga kamu sepanjang waktu.",
  ui_story_5057_50570502_36_dialog_content = "Tidak, tidak bisa melupakan begitu saja!",
  ui_story_5057_50570502_37_dialog_content = "Saya harus membayar utang ini kepada kamu!",
  ui_story_5057_50570502_38_dialog_content = "A-Apa yang sedang kamu lakukan...?",
  ui_story_5057_50570502_39_dialog_content = "Aku tahu kamu bersyukur, PlayerName, tapi ini terlalu berlebihan.",
  ui_story_5057_50570502_40_dialog_content = "Ini akan menghabiskan setiap sen dari gajimu!",
  ui_story_5057_50570502_41_dialog_content = "Tidak, itu sama sekali tidak terlalu banyak untuk penyelamatku! Saya selalu bisa mendapatkan kembali penghasilan saya!",
  ui_story_5057_50570502_42_dialog_content = "Biarkan saya melihat, jadi di sini kita membeli Marshmallow Stardust, es krim rasa kadal, dan jus mint-kaktus.",
  ui_story_5057_50570502_43_dialog_content = "Tambahkan minuman air terjun ngarai, dan Sosis Galaksi.",
  ui_story_5057_50570502_44_dialog_content = "Benar, dan kedua lengan saya penuh.",
  ui_story_5057_50570502_45_dialog_content = "Ini harusnya cukup, kan?",
  ui_story_5057_50570502_46_dialog_content = "Uh, saya merasa itu belum cukup.",
  ui_story_5057_50570502_47_dialog_content = "Lihat ini, satu-satunya manisan hawthorn Longzhou di seluruh Gurun Rediesel!",
  ui_story_5057_50570502_48_dialog_content = "Baru saja dilapisi sirup segar. Cicipi, dan kamu tidak akan menyesalinya!",
  ui_story_5057_50570502_49_dialog_content = "Beri aku satu, kumohon!",
  ui_story_5057_50570502_50_dialog_content = "Ini pertama kalinya saya melihat makanan ringan Longzhou ini. Cobalah, Florine!",
  ui_story_5057_50570502_51_dialog_content = "Saya sangat ingin melakukannya, tetapi saat ini setengah dari makanan di jalan ini ada di pelukan saya...",
  ui_story_5057_50570502_52_dialog_content = "Benar... Hei, bagaimana kalau aku memberimu makan?",
  ui_story_5057_50570502_53_dialog_content = "Apa? T-Tidak, itu tidak benar. Aku tidak mau.",
  ui_story_5057_50570502_54_dialog_content = "Ayo, coba gigit... Ups, lapisan gula nya jatuh!",
  ui_story_5057_50570502_55_dialog_content = "Oh, serius?",
  ui_story_5057_50570502_56_dialog_content = "<color=#e8d9bb>Florine dengan cepat menggigit buah paling bawah itu, permukaan merah cerahnya menetes dengan sirup manis.</color>",
  ui_story_5057_50570502_57_dialog_content = "Kurasa tidak apa-apa.",
  ui_story_5057_50570502_58_dialog_content = "Oh! Betapa aku iri pada kalian anak muda, bisa berfoya-foya di jalan seperti ini.",
  ui_story_5057_50570502_59_dialog_content = "...!",
  ui_story_5057_50570502_60_dialog_content = "Apakah kita melakukan sesuatu yang salah?",
  ui_story_5057_50570502_61_dialog_content = "Mengapa wajahmu begitu merah, Florine? Apakah makanan Anda membuat wajah orang menjadi merah, Pak?",
  ui_story_5057_50570502_62_dialog_content = "PlayerName!",
  ui_story_5057_50570502_63_dialog_content = "Aku di sini! Ada apa?",
  ui_story_5057_50570502_64_dialog_content = "Buka saja. Kentang panggangnya juga sangat enak.",
  ui_story_5057_50570502_65_dialog_content = "Tinggal berikan padaku... Oh!",
  ui_story_5057_50570502_66_dialog_content = "<color=#e8d9bb>Florine, dengan wajah memerah, menyumbatkan kentang panggang ke mulutku.</color>",
  ui_story_5057_50570502_67_dialog_content = "Kalian punya ikatan yang sangat erat! Ini, biar aku ambilkan mangkuk lain untuk kalian, gratis!",
  ui_story_5057_50570502_68_dialog_content = "<color=#e8d9bb>Nantinya, Florine bersikeras untuk membagi biaya dengan aku. Itu sangat... Florine.</color>",
  ui_story_5057_50570601_1_dialog_content = "A-Aku gugup.",
  ui_story_5057_50570601_2_dialog_content = "Tentu, saya berteman dengan Yang Mulia Ratu Bethlehem...",
  ui_story_5057_50570601_3_dialog_content = "Tapi saya masih merasa stres saat bertemu dengannya sendirian, entah mengapa...",
  ui_story_5057_50570601_4_dialog_content = "Belum lagi saya mewakili resor atas nama Lorelei...",
  ui_story_5057_50570601_5_dialog_content = "Saya tampak rapi, kan...? Oh, ternyata saya pakai ini sejak tadi.",
  ui_story_5057_50570601_6_dialog_content = "Lalu mungkin saya tidak akan mengecewakan Kaum Caelestite... Semoga tidak...",
  ui_story_5057_50570601_7_dialog_content = "Dan semoga tidak akan menjadi aib bagi resor tersebut.",
  ui_story_5057_50570601_8_dialog_content = "PlayerName…",
  ui_story_5057_50570601_9_dialog_content = "Lorelei tidak akan mengurangi gajiku, bukan?",
  ui_story_5057_50570601_10_dialog_content = "PlayerName?",
  ui_story_5057_50570601_11_dialog_content = "Y-Ya!",
  ui_story_5057_50570601_12_dialog_content = "Yang Mulia Ratu!",
  ui_story_5057_50570601_13_dialog_content = "Saya tidak mengganggu apa-apa, bukan?",
  ui_story_5057_50570601_14_dialog_content = "Kamu tampak bermasalah?",
  ui_story_5057_50570601_15_dialog_content = "Tidak, tidak, sama sekali tidak! Menjadi tuan rumah bagi Yang Mulia selalu menjadi kebahagiaan.",
  ui_story_5057_50570601_16_dialog_content = "Lorelei menyalahkan dirinya sendiri karena tidak menghibur kamu sebelumnya karena dia sibuk dengan Eclipsite.",
  ui_story_5057_50570601_17_dialog_content = "Dan aku harap kamu akan menikmati liburan langka ini di resor.",
  ui_story_5057_50570601_18_dialog_content = "Karena saya bayangkan urusan pengadilan mungkin membuatmu lelah.",
  ui_story_5057_50570601_19_dialog_content = "Aku tahu. Kuhargai kepedulianmu.",
  ui_story_5057_50570601_20_dialog_content = "Hahaha, tidak peduli berapa kali saya menunggang Naga Putih Malam, tetap saja mendebarkan.",
  ui_story_5057_50570601_21_dialog_content = "Kaki saya masih gemetar saat ini...",
  ui_story_5057_50570601_22_dialog_content = "Tapi Anda tampak tenang dan terkumpul, Yang Mulia.",
  ui_story_5057_50570601_23_dialog_content = "Memang, karena saya terbiasa mengendarai naga terbang.",
  ui_story_5057_50570601_24_dialog_content = "Anda benar-benar mengalami segalanya, Yang Mulia.",
  ui_story_5057_50570601_25_dialog_content = "Teh dan camilan untukmu.",
  ui_story_5057_50570601_26_dialog_content = "Terima kasih, PlayerName.",
  ui_story_5057_50570601_27_dialog_content = "Di mana bagianmu?",
  ui_story_5057_50570601_28_dialog_content = "Oh, Lorelei bilang ke koki untuk menyiapkan ini khusus untukmu.",
  ui_story_5057_50570601_29_dialog_content = "Saya dengar banyak menggunakan bahan-bahan berharga dan mahal.",
  ui_story_5057_50570601_30_dialog_content = "Benarkah?",
  ui_story_5057_50570601_31_dialog_content = "(Hmm, saya tidak yakin Queen Bethlehem sedang dalam suasana hati yang sangat baik.)",
  ui_story_5057_50570601_32_dialog_content = "PlayerName.",
  ui_story_5057_50570601_33_dialog_content = "Ya, Yang Mulia!",
  ui_story_5057_50570601_34_dialog_content = "Aku ingin bertanya.",
  ui_story_5057_50570601_35_dialog_content = "Silakan bertanya.",
  ui_story_5057_50570601_36_dialog_content = "Dalam peran apa kamu menemani saya, PlayerName?",
  ui_story_5057_50570601_37_option_content = "Uh, pemandu untuk resor?",
  ui_story_5057_50570601_38_dialog_content = "Saya dibayar gaji oleh Lorelei lagi pula...",
  ui_story_5057_50570601_39_option_content = "Uh, teman dekat Yang Mulia?",
  ui_story_5057_50570601_40_dialog_content = "Nah, itu mungkin terlalu berlebihan.",
  ui_story_5057_50570601_41_dialog_content = "Tapi saya rasa saya bisa menangani pekerjaan ini, kan?",
  ui_story_5057_50570601_42_dialog_content = "Saya tidak yakin itu akan membuat saya benar-benar merasa nyaman.",
  ui_story_5057_50570601_43_dialog_content = "Terima kasih untuk takdir, kita sudah saling mengenal cukup lama sekarang, namun kamu masih terpaku pada posisi saya.",
  ui_story_5057_50570601_44_dialog_content = "Tapi kamu adalah Queen dari Utara... Saya lebih baik tidak menyinggung kamu dengan terlalu kasual.",
  ui_story_5057_50570601_45_dialog_content = "Tidak, kamu tidak menyinggungku.",
  ui_story_5057_50570601_46_dialog_content = "Saya hanya merasa suasana sekarang membuat jarak antara kita.",
  ui_story_5057_50570601_47_dialog_content = "Sikap Anda membuat saya merasa seperti berada di acara resmi.",
  ui_story_5057_50570601_48_dialog_content = "Maaf...",
  ui_story_5057_50570601_49_dialog_content = "Jangan tundukkan kepalamu, Caelestite. Apakah kamu masih ingat bahwa kamu adalah yang terpilih?",
  ui_story_5057_50570601_50_dialog_content = "Tentu saja aku tahu!",
  ui_story_5057_50570601_51_dialog_content = "Jika kamu benar-benar ingin membantu saya mengurangi stres...",
  ui_story_5057_50570601_52_dialog_content = "Lalu bantu saya melupakan status saya sebagai ratu dan lewati protokol-protokol yang kaku itu.",
  ui_story_5057_50570601_53_dialog_content = "Santai saja, terutama saat hanya kita berdua.",
  ui_story_5057_50570601_54_dialog_content = "Untuk saat ini, aku ingin hang out dan chill bersama kamu sebagai teman, PlayerName.",
  ui_story_5057_50570601_55_dialog_content = "Tapi aku agak kecewa karena kamu selalu menaruhku di atas pedestal yang tinggi.",
  ui_story_5057_50570601_56_dialog_content = "Tolong perlakukan saya sebagai teman saja untuk sementara waktu. Jangan ragu untuk menggoda dan bercanda.",
  ui_story_5057_50570601_57_dialog_content = "Aku tidak keberatan dengan kesalahan apa pun yang mungkin kamu lakukan, dan ini akan membuat liburan ini lebih baik dan membuat kita semakin dekat.",
  ui_story_5057_50570601_58_dialog_content = "Mohon maaf atas ketidaktahuan saya. Saya mengerti apa yang kamu katakan sekarang.",
  ui_story_5057_50570601_59_dialog_content = "Mulai sekarang, saya akan memperlakukan Anda seperti teman, Yang Mulia.",
  ui_story_5057_50570601_60_dialog_content = "Baiklah.",
  ui_story_5057_50570601_61_dialog_content = "(Dia tersenyum akhirnya...)",
  ui_story_5057_50570601_62_dialog_content = "Kurasa aku bisa santai sekarang.",
  ui_story_5057_50570601_63_dialog_content = "Oh, satu hal lagi.",
  ui_story_5057_50570601_64_dialog_content = "Apa itu, Yang Mulia?",
  ui_story_5057_50570601_65_dialog_content = "Mulai sekarang, tolong berhenti menyebut saya sebagai Yang Mulia atau Queen.",
  ui_story_5057_50570601_66_dialog_content = "Saya tidak ingin tamu lain mengetahui identitas saya.",
  ui_story_5057_50570601_67_dialog_content = "Nah, bagaimana cara mengatasinya...?",
  ui_story_5057_50570601_68_dialog_content = "Belen.",
  ui_story_5057_50570601_69_dialog_content = "Panggil aku Belen selama aku disini.",
  ui_story_5057_50570601_70_dialog_content = "Apa?",
  ui_story_5057_50570601_71_dialog_content = "<color=#e8d9bb>EveMeskipun Queen Bethlehem tetap tenang dan berwajah datar, saya bisa melihat bahwa suasana hatinya telah cerah cukup banyak.</color>",
  ui_story_5057_50570602_1_dialog_content = "Langit Biru memang terlalu banyak untukku...",
  ui_story_5057_50570602_2_dialog_content = "Saya merasa sebagian dari diri saya tercabik setiap kali saya tersingkir dan terpental ke atas dan ke bawah.",
  ui_story_5057_50570602_3_dialog_content = "Tapi Queen Bethlehem sepertinya sedang menikmati waktu yang menyenangkan.",
  ui_story_5057_50570602_4_dialog_content = "Saya bertanya-tanya apakah itu mungkin berbahaya untuknya.",
  ui_story_5057_50570602_5_dialog_content = "Kayaknya aku khawatir sia-sia.",
  ui_story_5057_50570602_6_dialog_content = "Fiuh...",
  ui_story_5057_50570602_7_dialog_content = "Beth... Belen, rambutmu berantakan.",
  ui_story_5057_50570602_8_option_content = "Bantu Bethlehem merapikan",
  ui_story_5057_50570602_9_dialog_content = "Izinkan saya untuk membantu Anda.",
  ui_story_5057_50570602_10_dialog_content = "Tentu, terima kasih.",
  ui_story_5057_50570602_11_option_content = "Tunggu Bethlehem untuk merapikan dirinya sendiri",
  ui_story_5057_50570602_12_dialog_content = "Tidak apa-apa, saya bisa menanganinya sendiri.",
  ui_story_5057_50570602_13_dialog_content = "Maaf, hampir saja aku memanggilmu dengan nama yang salah lagi.",
  ui_story_5057_50570602_14_dialog_content = "Jangan gugup, aku tahu itu akan butuh waktu sejenak untuk terbiasa. Tak usah cemas.",
  ui_story_5057_50570602_15_dialog_content = "Akan melakukan! Kamu tampak dalam suasana hati yang jauh lebih baik. Apakah kamu menikmati Langit Biru?",
  ui_story_5057_50570602_16_dialog_content = "(Ini hanya mengingatkan saya pada Queen Bethlehem menembak lebih dari selusin senjata api saat bermain game Lucky Roulette.)",
  ui_story_5057_50570602_17_dialog_content = "(Kemungkinan mendapatkan pistol yang tidak terisi dalam permainan itu adalah satu-dari-enam... Dia sangat beruntung.)",
  ui_story_5057_50570602_18_dialog_content = "Yang ini lebih menyenangkan untukku... Aku hanya tidak mendapatkan kesempatan untuk bersantai seperti orang normal, biasanya.",
  ui_story_5057_50570602_19_dialog_content = "Saya bisa melihat itu, karena kamu memiliki banyak hal di piringmu sebagai ratu.",
  ui_story_5057_50570602_20_dialog_content = "Terima kasih, tapi jangan lupa sekarang aku Belen.",
  ui_story_5057_50570602_21_dialog_content = "Maaf! Sebagai permintaan maaf, silakan menikmati segelas jus kaktus bintang dari saya! Rasanya sangat lezat.",
  ui_story_5057_50570602_22_dialog_content = "Kemudian kita bisa santai di bianglala dan mengabaikan pemandangan resort.",
  ui_story_5057_50570602_23_dialog_content = "Aku akan kembali sebentar.",
  ui_story_5057_50570602_24_dialog_content = "Tak bisa percaya betapa ramainya penjual itu. Lama sekali menunggunya.",
  ui_story_5057_50570602_25_dialog_content = "Saya harus kembali. Queen Bethlehem pasti bertanya-tanya di mana saya.",
  ui_story_5057_50570602_26_dialog_content = "Jadi, bagaimana pendapat Anda, Nona?",
  ui_story_5057_50570602_27_dialog_content = "Jangan ragu untuk mengutarakan pikiranmu.",
  ui_story_5057_50570602_28_dialog_content = "...",
  ui_story_5057_50570602_29_dialog_content = "Siapa orang-orang ini?",
  ui_story_5057_50570602_30_dialog_content = "Hai, teman. Apakah kamu dan wanita muda ini teman?",
  ui_story_5057_50570602_31_dialog_content = "Siapa kau?",
  ui_story_5057_50570602_32_dialog_content = "Maaf atas ketidaknyamanan. Saya sebenarnya seorang pencari bakat dari Umbraton Beatitude Entertainment.",
  ui_story_5057_50570602_33_dialog_content = "Dan saya harus mengatakan bahwa wanita muda di sini memiliki penampilan yang sangat menakjubkan. Dia seperti bintang yang lahir.",
  ui_story_5057_50570602_34_dialog_content = "Perusahaan kami sangat berpengaruh, dan jika kamu tertarik untuk bergabung dengan kami, saya bisa memberikan beberapa persyaratan yang sangat menarik!",
  ui_story_5057_50570602_35_dialog_content = "Kami di sini untuk berlibur dan tidak ada rencana untuk menjadi idola atau semacamnya.",
  ui_story_5057_50570602_36_dialog_content = "Sungguh sayang untuk membuang bakat dan potensi luar biasa seperti ini!",
  ui_story_5057_50570602_37_dialog_content = "Hei, sobat. Apakah Anda agen nona muda ini?",
  ui_story_5057_50570602_38_dialog_content = "Kita bisa melakukan diskusi tiga arah, dan saya bisa janjikan kamu komisi yang cukup besar.",
  ui_story_5057_50570602_39_dialog_content = "Maafkan saya, tetapi kami tidak ingin diganggu.",
  ui_story_5057_50570602_40_dialog_content = "Sayang sekali. Yah, saya harus mencari orang lain.",
  ui_story_5057_50570602_41_dialog_content = "Nona, bolehkah saya meninggalkan informasi kontak saya? Saya memiliki beberapa peluang menarik untuk Anda!",
  ui_story_5057_50570602_42_dialog_content = "Tolong tinggalkan sekarang, atau saya akan panggil keamanan.",
  ui_story_5057_50570602_43_dialog_content = "Brengsek, apa yang baru saja kamu katakan...?",
  ui_story_5057_50570602_44_dialog_content = "Tolong berdiri di belakang saya, Nona Belen.",
  ui_story_5057_50570602_45_dialog_content = "Cukup, Duke. Kita sekarang pengusaha.",
  ui_story_5057_50570602_46_dialog_content = "Hahaha, teman saya di sini memang memiliki sifat pemarah.",
  ui_story_5057_50570602_47_dialog_content = "Kami akan tinggalkan kalian berdua. Harus diakui, temanmu cukup tangguh, Nona.",
  ui_story_5057_50570602_48_dialog_content = "Cih.",
  ui_story_5057_50570602_49_dialog_content = "Tak bisa dipercaya, orang itu nggak mau berhenti.",
  ui_story_5057_50570602_50_dialog_content = "Apa kabar, Yang Mulia? Maaf saya terlambat.",
  ui_story_5057_50570602_51_dialog_content = "Saya baik-baik saja, PlayerName. Saya tidak terganggu oleh orang seperti itu atau pelecehan.",
  ui_story_5057_50570602_52_dialog_content = "Aku sudah mengawasimu.",
  ui_story_5057_50570602_53_dialog_content = "Menonton aku?",
  ui_story_5057_50570602_54_dialog_content = "<color=#e8d9bb>Bethlehem meletakkan tangannya di bahu saya.</color>",
  ui_story_5057_50570602_55_dialog_content = "Ya. Keberanian yang kamu tunjukkan sangat patut diacungi jempol.",
  ui_story_5057_50570602_56_dialog_content = "Berdasarkan cara mereka bertindak, mereka mungkin bekerja sebagai penegak di Umbraton.",
  ui_story_5057_50570602_57_dialog_content = "Jika ada bentrokan, saya tidak pikir kamu bisa mengalahkan salah satu dari mereka, apalagi kamu kalah jumlah.",
  ui_story_5057_50570602_58_dialog_content = "Ah, itu berbahaya, bukan? Tidak terlintas di pikiran saya...",
  ui_story_5057_50570602_59_dialog_content = "Dan itulah mengapa kamu dikagumi.",
  ui_story_5057_50570602_60_dialog_content = "Kamu menjadi lebih berani dan lebih dapat diandalkan.",
  ui_story_5057_50570602_61_dialog_content = "Kamu memang yang terpilih.",
  ui_story_5057_50570602_62_dialog_content = "Anda membuat saya tersipu, Yang Mulia.",
  ui_story_5057_50570602_63_dialog_content = "Oke, mari menuju ke bianglala. Dan jangan lupa, aku Belen sekarang.",
  ui_story_5057_50570602_64_dialog_content = "<color=#e8d9bb>Kemudian aku naik bianglala bersama Bethlehem... Maksudku, Belen. Aku tak bisa tidak menyadari bahwa Yang Mulia Ratu, yang biasanya memiliki tatapan dingin, terlihat lebih lembut di matanya hari ini.</color>",
  ui_story_5057_50570701_1_dialog_content = "A-Aku gugup.",
  ui_story_5057_50570701_2_dialog_content = "Tentu, saya berteman dengan Yang Mulia Ratu Bethlehem...",
  ui_story_5057_50570701_3_dialog_content = "Tapi entah kenapa, saya masih merasa stres saat bertemu dengannya sendirian...",
  ui_story_5057_50570701_4_dialog_content = "Belum lagi saya mewakili resor atas nama Lorelei...",
  ui_story_5057_50570701_5_dialog_content = "Saya tampak rapi, kan...? Oh, ternyata saya pakai ini sepanjang waktu.",
  ui_story_5057_50570701_6_dialog_content = "Lalu mungkin saya tidak akan mengecewakan Kaum Caelestite... Semoga tidak...",
  ui_story_5057_50570701_7_dialog_content = "Dan semoga tidak akan menjadi aib bagi resor juga.",
  ui_story_5057_50570701_8_dialog_content = "PlayerName…",
  ui_story_5057_50570701_9_dialog_content = "Lorelei tidak akan mengurangi gajiku, bukan?",
  ui_story_5057_50570701_10_dialog_content = "PlayerName?",
  ui_story_5057_50570701_11_dialog_content = "Ya!",
  ui_story_5057_50570701_12_dialog_content = "Yang Mulia Ratu!",
  ui_story_5057_50570701_13_dialog_content = "Saya tidak mengganggu apa-apa, bukan?",
  ui_story_5057_50570701_14_dialog_content = "Kamu tampak bermasalah?",
  ui_story_5057_50570701_15_dialog_content = "Tidak, tidak, sama sekali tidak! Menjadi tuan rumah bagi Yang Mulia selalu menjadi kebahagiaan.",
  ui_story_5057_50570701_16_dialog_content = "Lorelei menyalahkan dirinya sendiri karena tidak menghibur kamu sebelumnya karena dia sibuk dengan Eclipsite.",
  ui_story_5057_50570701_17_dialog_content = "Dan aku harap kamu akan menikmati liburan langka ini di resor.",
  ui_story_5057_50570701_18_dialog_content = "Karena saya bayangkan urusan pengadilan mungkin membuatmu lelah.",
  ui_story_5057_50570701_19_dialog_content = "Aku tahu. Kuhargai kepedulianmu.",
  ui_story_5057_50570701_20_dialog_content = "Hahaha, tidak peduli berapa kali saya menunggang Naga Putih Malam, tetap saja mendebarkan.",
  ui_story_5057_50570701_21_dialog_content = "Kaki saya masih gemetar saat ini...",
  ui_story_5057_50570701_22_dialog_content = "Tapi Anda tampak tenang dan terkendali, Yang Mulia.",
  ui_story_5057_50570701_23_dialog_content = "Memang, karena saya terbiasa mengendarai naga terbang.",
  ui_story_5057_50570701_24_dialog_content = "Anda benar-benar mengalami segalanya, Yang Mulia.",
  ui_story_5057_50570701_25_dialog_content = "Teh dan camilan untukmu.",
  ui_story_5057_50570701_26_dialog_content = "Terima kasih, PlayerName.",
  ui_story_5057_50570701_27_dialog_content = "Di mana bagianmu?",
  ui_story_5057_50570701_28_dialog_content = "Oh, Lorelei bilang ke koki untuk menyiapkan ini khusus untuk kamu.",
  ui_story_5057_50570701_29_dialog_content = "Saya dengar banyak menggunakan bahan-bahan berharga dan mahal.",
  ui_story_5057_50570701_30_dialog_content = "Benarkah?",
  ui_story_5057_50570701_31_dialog_content = "(Hmm, saya tidak yakin Queen Bethlehem sedang dalam mood yang sangat baik.)",
  ui_story_5057_50570701_32_dialog_content = "PlayerName.",
  ui_story_5057_50570701_33_dialog_content = "Ya, Yang Mulia!",
  ui_story_5057_50570701_34_dialog_content = "Aku ingin bertanya.",
  ui_story_5057_50570701_35_dialog_content = "Silakan bertanya.",
  ui_story_5057_50570701_36_dialog_content = "Dalam peran apa kamu menemani saya, PlayerName?",
  ui_story_5057_50570701_37_option_content = "Uh, pemandu untuk resor?",
  ui_story_5057_50570701_38_dialog_content = "Saya dibayar gaji oleh Lorelei lagi pula...",
  ui_story_5057_50570701_39_option_content = "Uh, teman dekat Yang Mulia?",
  ui_story_5057_50570701_40_dialog_content = "Nah, itu mungkin terlalu berlebihan.",
  ui_story_5057_50570701_41_dialog_content = "Tapi saya rasa saya bisa menangani pekerjaan ini, kan?",
  ui_story_5057_50570701_42_dialog_content = "Saya tidak yakin itu akan membuat saya benar-benar merasa nyaman.",
  ui_story_5057_50570701_43_dialog_content = "Terima kasih untuk takdir, kita sudah saling mengenal cukup lama sekarang, namun kamu masih terus terpaku pada posisi saya.",
  ui_story_5057_50570701_44_dialog_content = "Tapi kamu adalah Queen dari Utara... Saya lebih baik tidak menyinggungmu dengan terlalu kasual.",
  ui_story_5057_50570701_45_dialog_content = "Tidak, kamu tidak menyinggungku.",
  ui_story_5057_50570701_46_dialog_content = "Saya merasa suasana sekarang membuat jarak antara kita.",
  ui_story_5057_50570701_47_dialog_content = "Sikap Anda membuat saya merasa seperti berada di acara resmi.",
  ui_story_5057_50570701_48_dialog_content = "Maaf...",
  ui_story_5057_50570701_49_dialog_content = "Jangan tundukkan kepalamu, Caelestite. Apakah kamu masih ingat bahwa kamu adalah yang terpilih?",
  ui_story_5057_50570701_50_dialog_content = "Tentu saja aku tahu!",
  ui_story_5057_50570701_51_dialog_content = "Jika kamu benar-benar ingin membantu saya mengurangi stres...",
  ui_story_5057_50570701_52_dialog_content = "Lalu bantu saya melupakan status saya sebagai ratu dan lewati protokol-protokol yang kaku itu.",
  ui_story_5057_50570701_53_dialog_content = "Santai saja, terutama saat hanya kita berdua.",
  ui_story_5057_50570701_54_dialog_content = "Untuk saat ini, aku ingin hang out dan chill bersama kamu sebagai teman, PlayerName.",
  ui_story_5057_50570701_55_dialog_content = "Tapi aku agak kecewa karena kamu selalu menaruhku di atas pedestal yang tinggi.",
  ui_story_5057_50570701_56_dialog_content = "Tolong perlakukan saya sebagai teman saja untuk sementara waktu. Jangan ragu untuk menggoda dan bercanda.",
  ui_story_5057_50570701_57_dialog_content = "Saya tidak keberatan dengan kesalahan apa pun yang mungkin kamu lakukan, dan ini akan membuat liburan ini lebih baik dan membuat kita semakin dekat.",
  ui_story_5057_50570701_58_dialog_content = "Mohon maaf atas ketidaktahuan saya. Saya mengerti apa yang Anda katakan sekarang.",
  ui_story_5057_50570701_59_dialog_content = "Mulai sekarang, saya akan memperlakukan Anda seperti teman, Yang Mulia.",
  ui_story_5057_50570701_60_dialog_content = "Baiklah.",
  ui_story_5057_50570701_61_dialog_content = "(Dia tersenyum akhirnya...)",
  ui_story_5057_50570701_62_dialog_content = "Kurasa aku bisa santai sekarang.",
  ui_story_5057_50570701_63_dialog_content = "Oh, satu hal lagi.",
  ui_story_5057_50570701_64_dialog_content = "Apa itu, Yang Mulia?",
  ui_story_5057_50570701_65_dialog_content = "Mulai sekarang, tolong berhenti menyebut saya sebagai Yang Mulia atau Queen.",
  ui_story_5057_50570701_66_dialog_content = "Saya tidak ingin tamu lain mengetahui identitas saya.",
  ui_story_5057_50570701_67_dialog_content = "Nah, bagaimana cara mengatasinya...?",
  ui_story_5057_50570701_68_dialog_content = "Belen.",
  ui_story_5057_50570701_69_dialog_content = "Panggil aku Belen selama aku disini.",
  ui_story_5057_50570701_70_dialog_content = "Apa?",
  ui_story_5057_50570701_71_dialog_content = "<color=#e8d9bb>EveMeskipun Queen Bethlehem tetap tenang dan berwajah datar, saya bisa melihat bahwa suasana hatinya telah menjadi lebih cerah sedikit.</color>",
  ui_story_5057_50570702_1_dialog_content = "Langit Biru memang terlalu banyak bagiku...",
  ui_story_5057_50570702_2_dialog_content = "Saya merasa sebagian dari diri saya tercabik setiap kali saya tersingkir dan terpental ke atas dan ke bawah.",
  ui_story_5057_50570702_3_dialog_content = "Tapi Queen Bethlehem sepertinya sedang menikmati waktu yang menyenangkan.",
  ui_story_5057_50570702_4_dialog_content = "Saya bertanya-tanya apakah itu mungkin berbahaya untuknya.",
  ui_story_5057_50570702_5_dialog_content = "Kayaknya aku khawatir sia-sia.",
  ui_story_5057_50570702_6_dialog_content = "Fiuh...",
