  ui_story_5057_50570702_9_dialog_content = "Izinkan saya untuk membantu Anda.",
  ui_story_5057_50570702_10_dialog_content = "Tentu, terima kasih.",
  ui_story_5057_50570702_11_option_content = "Tunggu Bethlehem untuk merapikan dirinya sendiri",
