  ui_story_5057_50570702_53_dialog_content = "Menonton aku?",
  ui_story_5057_50570702_54_dialog_content = "(Bethlehem menaruh tangan di bahu saya.)",
  ui_story_5057_50570702_55_dialog_content = "Ya. Keberanian yang kamu tunjukkan sangat patut diacungi jempol.",
  ui_story_5057_50570702_56_dialog_content = "Berdasarkan cara mereka bertindak, mereka mungkin bekerja sebagai penegak di Umbraton.",
  ui_story_5057_50570702_57_dialog_content = "Jika ada bentrokan, saya tidak yakin kamu bisa mengalahkan salah satu dari mereka, apalagi kamu kalah jumlah.",
  ui_story_5057_50570702_58_dialog_content = "Ah, itu berbahaya, bukan? Tidak terlintas di pikiran saya...",
  ui_story_5057_50570702_59_dialog_content = "Dan itulah mengapa kamu dikagumi.",
  ui_story_5057_50570702_60_dialog_content = "Kamu menjadi lebih berani dan lebih dapat diandalkan.",
  ui_story_5057_50570702_61_dialog_content = "Kamu memang Orang Pilihan sejati.",
  ui_story_5057_50570702_62_dialog_content = "Anda membuat saya tersipu, Yang Mulia.",
  ui_story_5057_50570702_63_dialog_content = "Oke, mari menuju ke bianglala. Dan jangan lupa, aku Belen sekarang.",
  ui_story_5057_50570702_64_dialog_content = "<color=#e8d9bb>Kemudian aku naik bianglala bersama Bethlehem... Maksudku, Belen. Aku tidak bisa tidak memperhatikan bahwa Yang Mulia Ratu, yang biasanya memiliki tatapan dingin, terlihat lebih lembut di matanya hari ini.</color>",
  ui_story_5057_50570801_1_dialog_content = "PlayerName!",
  ui_story_5057_50570801_2_dialog_content = "Hah?",
  ui_story_5057_50570801_3_dialog_content = "PlayerName!!",
  ui_story_5057_50570801_4_dialog_content = "Kurasa aku mendengar suara mengganggu yang memanggil namaku...",
  ui_story_5057_50570801_5_dialog_content = "Saya harus pergi.",
  ui_story_5057_50570801_6_dialog_content = "PlayerName—",
  ui_story_5057_50570801_7_dialog_content = "T-Tunggu, saya tidak bisa mengimbangi Anda.",
  ui_story_5057_50570801_8_dialog_content = "Aku akan pingsan jika kamu terus begini—",
  ui_story_5057_50570801_9_dialog_content = "Vic?",
  ui_story_5057_50570801_10_dialog_content = "Maaf, saya merasakan masalah datang dan langsung meningkatkan kecepatan.",
  ui_story_5057_50570801_11_dialog_content = "Apakah itu pendapatmu tentang aku? Itu membuatku sedih.",
  ui_story_5057_50570801_12_dialog_content = "Jadi, kenapa kamu tidak menebusnya dengan mengajak saya makan siang?",
  ui_story_5057_50570801_13_dialog_content = "Ahli ekstrozoologi paling terkenal di dunia pasti akan menghiasi kamu dengan kehadirannya.",
  ui_story_5057_50570801_14_dialog_content = "Berhenti mencoba mengemis!",
  ui_story_5057_50570801_15_dialog_content = "Dan apa yang kamu omongkan? Aku bukan salah satu muridmu.",
  ui_story_5057_50570801_16_dialog_content = "Apa bedanya itu? Saya cukup yakin kamu bisa bergaul dengan baik dengan Fia dan Shira.",
  ui_story_5057_50570801_17_dialog_content = "Tidak... Lupakan Fia, bagaimana kamu bisa tahu dengan Shira?",
  ui_story_5057_50570801_18_dialog_content = "Sebut saja firasat seorang master, dan saya tidak akan membahas lebih detail.",
  ui_story_5057_50570801_19_dialog_content = "Jadi, pernahkah kamu mempertimbangkan untuk melangkah lebih jauh dalam hubungan ini?",
  ui_story_5057_50570801_20_dialog_content = "Lalu kita semua akan menjadi keluarga dan kamu juga harus memanggilku \"Master\".",
  ui_story_5057_50570801_21_dialog_content = "Menurut kamu, siapa yang lebih cocok untukmu, Fia atau Shira?",
  ui_story_5057_50570801_22_option_content = "Binatang Menakjubkan!",
  ui_story_5057_50570801_23_dialog_content = "Hei, aku tidak menyangka kamu memiliki minat yang sama.",
  ui_story_5057_50570801_24_dialog_content = "Beberapa makhluk sehebat diriku, tidak hanya dalam kepribadian tetapi juga warna yang sama indahnya...",
  ui_story_5057_50570801_25_dialog_content = "Apakah kamu merujuk pada boros apa pun yang pernah kita temui sebelumnya?",
  ui_story_5057_50570801_26_dialog_content = "Benar sekali. Silakan lihat buku baru saya, \"Misteri Antara Saya dan Ouroboros\" untuk detailnya.",
  ui_story_5057_50570801_27_dialog_content = "Saya masih mengerjakannya, jadi kamu bisa menantikannya untuk saat ini.",
  ui_story_5057_50570801_28_dialog_content = "Ngomong-ngomong, apakah kamu juga terpesona oleh sosok cantiknya?",
  ui_story_5057_50570801_29_dialog_content = "Ayo, mari kita mulai petualangan di jalur Ouroboros dan menjadi ahli zoologi ekstrem yang hebat!",
  ui_story_5057_50570801_30_dialog_content = "Tidak, terima kasih, aku hanya bercanda!",
  ui_story_5057_50570801_31_dialog_content = "Dan apa ini tiba-tiba tentang hal yang luar biasa?",
  ui_story_5057_50570801_32_dialog_content = "Tolong hentikan asumsi gila itu!",
  ui_story_5057_50570801_33_dialog_content = "Saya akan pergi bersama Tuan Vic!",
  ui_story_5057_50570801_34_option_content = "Pilih Tuan Vic!",
  ui_story_5057_50570801_35_dialog_content = "...",
  ui_story_5057_50570801_36_dialog_content = "eh...",
  ui_story_5057_50570801_37_dialog_content = "...",
  ui_story_5057_50570801_38_dialog_content = "Tunggu, ekspresi macam apa itu?",
  ui_story_5057_50570801_39_dialog_content = "Tidak apa-apa, aku hanya terharu sampai menangis.",
  ui_story_5057_50570801_40_dialog_content = "Itulah yang ingin saya ketahui. Mengapa kamu menangis?",
  ui_story_5057_50570801_41_dialog_content = "Aku tidak menyangka kamu akan membuka diri seperti itu padaku, PlayerName.",
  ui_story_5057_50570801_42_dialog_content = "Emosi dan semangat yang kamu tunjukkan padaku...",
  ui_story_5057_50570801_43_dialog_content = "Ini sangat mengharukan bagi saya.",
  ui_story_5057_50570801_44_dialog_content = "Tidak bisakah kamu tahu aku mengejekmu? Tidak, kamu pasti pura-pura.",
  ui_story_5057_50570801_45_dialog_content = "Sayangnya, saya mengambil sumpah.",
  ui_story_5057_50570801_46_dialog_content = "Aku akan menghabiskan seluruh hidupku bersama binatang menakjubkan. Bukankah begitu, bola bulu kecil.",
  ui_story_5057_50570801_47_dialog_content = "Cuit!",
  ui_story_5057_50570801_48_dialog_content = "Apa? Kamu bilang kaum Caelestite itu binatang menakjubkan dalam arti tertentu?",
  ui_story_5057_50570801_49_dialog_content = "Jadi dia termasuk dalam rentang pilihan saya?",
  ui_story_5057_50570801_50_dialog_content = "Kamu juga akan bahagia, jika aku bersama PlayerName?",
  ui_story_5057_50570801_51_dialog_content = "Hanya cuitan saja... Bagaimana kamu bisa mendapatkan begitu banyak dari itu?",
  ui_story_5057_50570801_52_dialog_content = "Sekarang saya pikir Anda menarik kaki saya.",
  ui_story_5057_50570801_53_dialog_content = "Heehee, bercanda.",
  ui_story_5057_50570801_54_dialog_content = "Dan tentu saja itu tidak bisa melewati kepala cerdas PlayerName, kan?",
  ui_story_5057_50570801_55_dialog_content = "Ha, baik sang guru maupun murid-muridnya sulit untuk dihadapi.",
  ui_story_5057_50570801_56_dialog_content = "Jadi apa yang kamu inginkan dariku, karena kamu mungkin bukan hanya di sini untuk mengobrol?",
  ui_story_5057_50570801_57_dialog_content = "Saya tahu Anda adalah penembak lurus!",
  ui_story_5057_50570801_58_dialog_content = "Itu firasat yang saya dapatkan setelah berurusan dengan kamu dan murid-muridmu berkali-kali.",
  ui_story_5057_50570801_59_dialog_content = "Jangan menunggu lagi! Cepat, ke ecozone.",
  ui_story_5057_50570801_60_dialog_content = "Ecozone?",
  ui_story_5057_50570801_61_dialog_content = "Berhenti menyeret saya! Kenapa kamu dan Fia selalu melakukannya?",
  ui_story_5057_50570801_62_dialog_content = "<color=#e8d9bb>Di perjalanan kami, Vic mentraktir saya es krim yang lezat.</color>",
  ui_story_5057_50570801_63_dialog_content = "<color=#e8d9bb>Namun, baru setelah kami selesai, dia memberi tahu saya bahwa dia lupa membawa dompetnya...</color>",
  ui_story_5057_50570802_1_dialog_content = "Ah, es krimnya lumayan.",
  ui_story_5057_50570802_2_dialog_content = "Terima kasih untuk traktirannya, PlayerName!",
  ui_story_5057_50570802_3_dialog_content = "Tak bisa kupercaya kamu punya keberanian untuk mengatakan itu.",
  ui_story_5057_50570802_4_dialog_content = "Terima kasih, Vice telah memberikan beberapa uang ganti di saku saya.",
  ui_story_5057_50570802_5_dialog_content = "Kalau tidak, kita akan sial.",
  ui_story_5057_50570802_6_dialog_content = "Kamu beruntung, PlayerName, karena ada Vice yang menjagamu dan memberimu uang.",
  ui_story_5057_50570802_7_dialog_content = "Semua muridku tahu hanya memeras aku.",
  ui_story_5057_50570802_8_dialog_content = "Tapi, bukankah kamu juga memerintah mereka sepanjang hari?",
  ui_story_5057_50570802_9_dialog_content = "Apa yang beredar, akan kembali lagi.",
  ui_story_5057_50570802_10_dialog_content = "Itu bukan memerintah mereka. Itu disebut pelatihan.",
  ui_story_5057_50570802_11_dialog_content = "Tanpa pelatihan sepanjang tahun tanpa waktu libur yang saya siapkan untuk mereka, mereka tidak akan begitu luar biasa secepat ini.",
  ui_story_5057_50570802_12_dialog_content = "Pembohong sekali...",
  ui_story_5057_50570802_13_dialog_content = "Hahaha... Tidak apa-apa, kita di sini.",
  ui_story_5057_50570802_14_dialog_content = "Apakah ini zona ekologi?",
  ui_story_5057_50570802_15_dialog_content = "Hai hai!",
  ui_story_5057_50570802_16_dialog_content = "Hai hai!",
  ui_story_5057_50570802_17_dialog_content = "gelap...",
  ui_story_5057_50570802_18_dialog_content = "Bukankah mereka Bica dan Glooey?",
  ui_story_5057_50570802_19_dialog_content = "Saya sama sekali tidak menyangka melihat mereka di sini.",
  ui_story_5057_50570802_20_dialog_content = "Sejujurnya, saya juga tidak berpikir mereka bisa bertahan di sini.",
  ui_story_5057_50570802_21_dialog_content = "Bica umumnya lebih suka tinggal di pegunungan terpencil.",
  ui_story_5057_50570802_22_dialog_content = "Dan Glooey menyukai habitat dengan sumber air yang melimpah.",
  ui_story_5057_50570802_23_dialog_content = "Even ketika Glooey penampakan dilaporkan di daerah kering, mereka sudah pergi saat kami tiba di sana.",
  ui_story_5057_50570802_24_dialog_content = "Fia tidak ada di sana saat terakhir kali, dan saya bekerja keras selama tiga hari tanpa henti untuk mencapainya.",
  ui_story_5057_50570802_25_dialog_content = "Saya menyisir seluruh tempat sepanjang hari, lalu berkemah selama dua minggu lagi hanya karena itu.",
  ui_story_5057_50570802_26_dialog_content = "Saya terburu-buru sehingga lupa membawa perlengkapan berkemah, jadi setiap malam saya tidur dengan bola bulu kecil di pelukan saya.",
  ui_story_5057_50570802_27_dialog_content = "Saya tidak kembali sampai saya benar-benar yakin tidak ada Glooey yang akan muncul.",
  ui_story_5057_50570802_28_dialog_content = "Pekerjaan yang sulit kamu miliki...",
  ui_story_5057_50570802_29_dialog_content = "Nah, tak usahlah.",
  ui_story_5057_50570802_30_dialog_content = "Semua dalam sehari kerja seorang ahli ekstrozoologi.",
  ui_story_5057_50570802_31_dialog_content = "Saya terus mengingatkan Fia untuk bersiap sebelum pergi, tetapi saya selalu lupa saat menyangkut diri saya sendiri.",
  ui_story_5057_50570802_32_option_content = "Maybe Saya dapat membantu dengan itu.",
  ui_story_5057_50570802_33_dialog_content = "Hubungi aku sebelum kamu pergi dalam perjalanan jauh. Jika waktu memungkinkan, Soroz bisa mengantarmu kesana.",
  ui_story_5057_50570802_34_dialog_content = "Dan kamu bisa menyimpan beberapa perlengkapan di Soroz agar tidak lupa.",
  ui_story_5057_50570802_35_dialog_content = "Hmm... ide yang bagus.",
  ui_story_5057_50570802_36_dialog_content = "Sangat perhatian sekali dari kamu, PlayerName.",
  ui_story_5057_50570802_37_option_content = "Kirim Fia waktu berikutnya",
  ui_story_5057_50570802_38_dialog_content = "Kamu benar, haha.",
  ui_story_5057_50570802_39_dialog_content = "Tubuhku terlalu tua untuk menangani penyiksaan ini!",
  ui_story_5057_50570802_40_dialog_content = "Lebih baik saya tinggal di rumah, bekerja di kebun, dan mengawasi binatang-binatang kecil.",
  ui_story_5057_50570802_41_dialog_content = "Tapi itu mendesak saat itu karena Glooey yang muncul di daerah kering bisa jadi subspesies yang langka.",
  ui_story_5057_50570802_42_dialog_content = "Jika saya bisa mendokumentasikannya, saya bisa membuat orang lebih mengerti dan mencintai mereka...",
  ui_story_5057_50570802_43_dialog_content = "gelap...",
  ui_story_5057_50570802_44_dialog_content = "Tentu saja, Buck juga sangat istimewa.",
  ui_story_5057_50570802_45_dialog_content = "Every Glooey adalah satu-satunya bagi aku.",
  ui_story_5057_50570802_46_dialog_content = "gelap...",
  ui_story_5057_50570802_47_dialog_content = "gelap...",
  ui_story_5057_50570802_48_dialog_content = "Master Vic, apakah Glooey dan Bica yang tinggal di Rediesel Desert juga merupakan spesies khusus?",
  ui_story_5057_50570802_49_dialog_content = "Tidak, mereka tidak.",
  ui_story_5057_50570802_50_dialog_content = "Mereka ditinggalkan di Gurun Rediesel.",
  ui_story_5057_50570802_51_dialog_content = "Apa?!",
  ui_story_5057_50570802_52_dialog_content = "Ya, saya menduga orang-orang yang melakukan perdagangan binatang menakjubkan ini bertanggung jawab.",
  ui_story_5057_50570802_53_dialog_content = "Aku belum tahu kenapa. Maymungkin karena mereka tidak bisa mendapatkan harga yang diinginkan atau apa pun itu.",
  ui_story_5057_50570802_54_dialog_content = "Tapi hal-hal mengerikan itu justru meninggalkan para binatang dalam kesulitan untuk bertahan hidup...",
  ui_story_5057_50570802_55_dialog_content = "gelap...",
  ui_story_5057_50570802_56_dialog_content = "Saya punya permintaan untukmu, PlayerName.",
  ui_story_5057_50570802_57_dialog_content = "Saya mengerti cara beberapa binatang menakjubkan berbicara, tetapi tidak benar-benar dapat memahami apa yang mereka pikirkan.",
  ui_story_5057_50570802_58_dialog_content = "Bisakah kamu menggunakan kemampuan psikis kamu pada mereka dan meyakinkan mereka untuk memberitahu siapa yang melakukannya?",
  ui_story_5057_50570802_59_dialog_content = "Saya harus mendapatkan keadilan untuk mereka.",
  ui_story_5057_50570802_60_dialog_content = "Aku paham.",
  ui_story_5057_50570802_61_dialog_content = "Gelap... Tn. Vic...",
  ui_story_5057_50570802_62_dialog_content = "Saya bisa mendengarnya sekarang... Katakan padaku, siapa yang melakukan ini padamu, dan mereka termasuk geng apa?",
  ui_story_5057_50570802_63_dialog_content = "Orang itu... gelap...",
  ui_story_5057_50570802_64_dialog_content = "Itu adalah Bica...",
  ui_story_5057_50570802_65_dialog_content = "Jadi kami tumpangan di kapal terbang...",
  ui_story_5057_50570802_66_dialog_content = "Tapi Bica membuat semuanya berantakan... Dan sekarang kita akhirnya jatuh ke sini.",
  ui_story_5057_50570802_67_dialog_content = "Hai hai!",
  ui_story_5057_50570802_68_dialog_content = "Oke…",
  ui_story_5057_50570802_69_dialog_content = "Sepertinya kamu sudah mendapatkan jawabanmu, Vic.",
  ui_story_5057_50570802_70_dialog_content = "Ya, semuanya baik-baik saja dan lancar sekarang.",
  ui_story_5057_50570802_71_dialog_content = "Siapa tahu, mungkin saja saya bahkan berhasil menyingkirkan beberapa anggota dari geng kriminal itu tanpa sengaja sebelumnya.",
  ui_story_5057_50570802_72_dialog_content = "Semakin banyak semakin baik. Mereka kan penjahat.",
  ui_story_5057_50570802_73_dialog_content = "Sekarang aku tahu mengapa Fia senang berpetualang bersama kamu, PlayerName.",
  ui_story_5057_50570802_74_dialog_content = "Evepertimbangkan untuk mengikuti aku?",
  ui_story_5057_50570802_75_dialog_content = "Saya bisa menemukan Kyllo untuk kamu...",
  ui_story_5057_50570802_76_dialog_content = "Berhenti menggangguku!",
  ui_story_5057_50570802_77_dialog_content = "<color=#e8d9bb>Kemudian, Vic terus mengganggu saya sampai saya tidak tahan dan menandatangani beberapa perjanjian yang tidak adil.</color>",
  ui_story_5057_50570901_1_dialog_content = "Kamu hampir terlambat, PlayerName.",
  ui_story_5057_50570901_2_dialog_content = "Huft, huft... Maaf... tapi kamu baru saja mengirimkan pesan itu beberapa menit yang lalu.",
  ui_story_5057_50570901_3_dialog_content = "Saya berlari kencang sepanjang jalan ke sini...",
  ui_story_5057_50570901_4_dialog_content = "Yah, itu benar.",
  ui_story_5057_50570901_5_dialog_content = "Ini salahku memanggil kamu begitu mendadak. Seharusnya aku tidak menyalahkan kamu dan aku minta maaf.",
  ui_story_5057_50570901_6_dialog_content = "Tapi kamu berhasil berlari ke sini... Sepertinya kamu telah menjadi jauh lebih kuat daripada sebelumnya.",
  ui_story_5057_50570901_7_dialog_content = "Ever sejak meninggalkan bawah tanah, hal-hal terus terjadi, terkadang bahkan berbahaya.",
  ui_story_5057_50570901_8_dialog_content = "Dikejar oleh berbagai Eclipsite sepanjang tahun pasti akan membuat siapa saja bugar.",
  ui_story_5057_50570901_9_dialog_content = "Saya juga dengar kamu sekarang cocok untuk Eclipsites umum.",
  ui_story_5057_50570901_10_dialog_content = "TakiMenggunakan kemampuan psikis kamu, mungkin saja suatu hari kamu akan melampaui para Aurorian sebagai seorang prajurit.",
  ui_story_5057_50570901_11_dialog_content = "Tidak mungkin, saya masih memiliki jalan panjang yang harus ditempuh. Saya ingin cukup kuat untuk melindungi semua orang, tetapi saya belum sampai di sana.",
  ui_story_5057_50570901_12_dialog_content = "Cerdik dan rendah hati sekarang... Saya terkesan.",
  ui_story_5057_50570901_13_dialog_content = "Cukup basa-basi, sekarang untuk alasan spesifik mengapa saya ingin bertemu dengan Anda.",
  ui_story_5057_50570901_14_dialog_content = "Mengerjakan saya sekarang? Saya mencoba membeli lebih banyak waktu dengan berbicara...",
  ui_story_5057_50570901_15_dialog_content = "Jangan kamu mengeluh.",
  ui_story_5057_50570901_16_dialog_content = "Saya baru saja mendapatkan pekerjaan dengan seseorang yang memberikan tips tentang penyelundup di Umbraton yang menyamar di antara tamu-tamu di Denuo Valley Resort.",
  ui_story_5057_50570901_17_dialog_content = "Dia pedagang informasi yang cerdik dan memiliki banyak koneksi. Dia berhasil mengelabui setiap orang yang dikirim untuk mengawasi atau menangkapnya.",
  ui_story_5057_50570901_18_dialog_content = "Tapi berbeda untukku. Karena jarang aku mengerjakan pekerjaan seperti ini, dia tidak akan mengenali aku.",
  ui_story_5057_50570901_19_dialog_content = "Apakah kamu mengambilnya karena uang mulai menipis?",
  ui_story_5057_50570901_20_dialog_content = "Tidak ada komentar tentang situasi keuangan saya, kecuali Anda ingin saya menjual Anda ke pasar gelap.",
  ui_story_5057_50570901_21_dialog_content = "M-maaf! Lanjutkan.",
  ui_story_5057_50570901_22_dialog_content = "Menurut majikan saya, pedagang keliling memiliki kemampuan khusus untuk merasakan kedatangan pihak yang bermusuhan.",
  ui_story_5057_50570901_23_dialog_content = "Jadi kita harus bersiap dan menunggu dia muncul di sini.",
  ui_story_5057_50570901_24_dialog_content = "Saya membutuhkan bantuan Anda untuk menangani semua aspek.",
  ui_story_5057_50570901_25_dialog_content = "Pura-pura jadi teman kencanku, mengerti?",
  ui_story_5057_50570901_26_dialog_content = "Aku paham, dia bisa merasakan pihak yang bermusuhan...",
  ui_story_5057_50570901_27_dialog_content = "... jadi aku akan jadi teman kencanmu... Kencan?!",
  ui_story_5057_50570901_28_dialog_content = "Oh, ada apa, sayang?",
  ui_story_5057_50570901_29_dialog_content = "SAYANG!",
  ui_story_5057_50570901_30_option_content = "Ya! Ada apa?",
  ui_story_5057_50570901_31_dialog_content = "Tak usahlah. Ingat peranmu dan berhenti melamun.",
  ui_story_5057_50570901_32_option_content = "...",
  ui_story_5057_50570901_33_dialog_content = "PlayerName!",
  ui_story_5057_50570901_34_dialog_content = "Ya!",
  ui_story_5057_50570901_35_dialog_content = "Maaf, saya belum terbiasa dengan ini...",
  ui_story_5057_50570901_36_dialog_content = "Jangan minta maaf. Ini hanya pekerjaan.",
  ui_story_5057_50570901_37_dialog_content = "Namun tetap waspada. Jika target ada di sekitar, aku akan membutuhkan kekuatanmu untuk menemukan posisinya.",
  ui_story_5057_50570901_38_dialog_content = "Bertindaklah natural... Jika dia menyadari bahwa identitasnya terbongkar, orang-orang yang tidak bersalah bisa terluka.",
  ui_story_5057_50570901_39_dialog_content = "Kamu hanya perlu fokus pada tugas yang sedang dihadapi. Di sini.",
  ui_story_5057_50570901_40_dialog_content = "Apa ini?",
  ui_story_5057_50570901_41_dialog_content = "Tabir surya.",
  ui_story_5057_50570901_42_dialog_content = "Aku tahu ini tabir surya... Tapi, eh...",
  ui_story_5057_50570901_43_dialog_content = "Apakah kamu ingin bersikap canggung dan menarik perhatian yang tidak diinginkan?",
  ui_story_5057_50570901_44_dialog_content = "Tentu saja tidak!",
  ui_story_5057_50570901_45_dialog_content = "Kamu ingin aku terkena sengatan matahari, lalu?",
  ui_story_5057_50570901_46_dialog_content = "<color=#e8d9bb>Untuk sesaat, saya terpesona saat punggung Paloma yang putih seperti salju, tampak memancarkan cahaya berkilauan di bawah sinar matahari.</color>",
  ui_story_5057_50570901_47_dialog_content = "Hal pertama yang pertama, saya akan membayar Anda apa yang sudah kita sepakati. Menempatkan tabir surya pada saya tidak akan memberi Anda bonus.",
  ui_story_5057_50570901_48_dialog_content = "Itu bukan yang saya maksud...! Saya belum pernah melakukan ini sebelumnya, jadi...",
  ui_story_5057_50570901_49_dialog_content = "Jadi, kamu panik?",
  ui_story_5057_50570901_50_dialog_content = "Tidak mungkin! Aku akan menggosokkannya pada dirimu!",
  ui_story_5057_50570901_51_dialog_content = "Nah, gitu dong, lebih pas seperti itu.",
  ui_story_5057_50570901_52_dialog_content = "Mengapa kamu gemetar? Bersikaplah serius dan pastikan kamu mengaplikasikannya secara merata.",
  ui_story_5057_50570901_53_dialog_content = "Baiklah, baiklah!",
  ui_story_5057_50570901_54_dialog_content = "Sementara itu, perhatikan ke arah itu untuk hal-hal mencurigakan.",
  ui_story_5057_50570901_55_dialog_content = "Ya!",
  ui_story_5057_50570901_56_dialog_content = "(Whoa, jantungku berdebar satu mil per menit.)",
  ui_story_5057_50570901_57_dialog_content = "Untuk apa kamu berhenti—",
  ui_story_5057_50570901_58_dialog_content = "Saya rasa ada seseorang yang mencurigakan di sebelah sana!",
  ui_story_5057_50570901_59_dialog_content = "Itu dia. Biar aku saja.",
  ui_story_5057_50570901_60_dialog_content = "<color=#e8d9bb>EveMeskipun Paloma dan saya telah menangkap pedagang informasi, tangan saya masih gemetar.</color>",
  ui_story_5057_50570902_1_dialog_content = "Apakah saya menjadi tuan rumah Paloma lagi hari ini?",
  ui_story_5057_50570902_2_dialog_content = "Setelah kejadian terakhir, saya rasa saya tidak bisa berhadapan dengannya.",
  ui_story_5057_50570902_3_dialog_content = "Apa dilema ini... Saya masih bisa melihatnya saat saya menutup mata.",
  ui_story_5057_50570902_4_dialog_content = "Hai, PlayerName, aku bawa minuman untukmu.",
  ui_story_5057_50570902_5_dialog_content = "Tidak, tidak, berhenti bertanya-tanya.",
  ui_story_5057_50570902_6_dialog_content = "...",
  ui_story_5057_50570902_7_dialog_content = "PlayerName!",
  ui_story_5057_50570902_8_dialog_content = "Oh, hai, Paloma!",
  ui_story_5057_50570902_9_dialog_content = "Apa yang kamu lakukan berkhayal lagi? Hati-hati atau nanti ada penjahat yang menculik dan menjualmu di toko hewan peliharaan!",
  ui_story_5057_50570902_10_dialog_content = "Tidak mungkin seburuk itu, bukan? Terima kasih untuk minumannya... *teguk*",
  ui_story_5057_50570902_11_dialog_content = "Saya memasukkan obat penenang di dalamnya.",
  ui_story_5057_50570902_12_dialog_content = "<size=50>Pfft—!</size>",
  ui_story_5057_50570902_13_dialog_content = "Hahaha, hanya bercanda.",
  ui_story_5057_50570902_14_dialog_content = "Itu nggak lucu...",
  ui_story_5057_50570902_15_dialog_content = "Ehem... Jadi, tentang terakhir kali... Aku tidak bermaksud begitu...",
  ui_story_5057_50570902_16_dialog_content = "Waktu itu? Apa maksudmu?",
  ui_story_5057_50570902_17_dialog_content = "Tahu kan, saat aku membantumu menangkap pria itu...",
  ui_story_5057_50570902_18_dialog_content = "Oh, kamu bicara tentang mengoleskan tabir surya pada diriku—",
  ui_story_5057_50570902_19_dialog_content = "Jangan terlalu keras, kumohon!",
  ui_story_5057_50570902_20_dialog_content = "<color=#e8d9bb>Paloma mengangkat alisnya, menatapku dengan kilatan nakal di matanya.</color>",
  ui_story_5057_50570902_21_dialog_content = "Kamu pikir aku akan marah padamu karena itu?",
  ui_story_5057_50570902_22_dialog_content = "Tidak... Karena... Saya...",
  ui_story_5057_50570902_23_dialog_content = "Apakah kamu minta maaf karena merasa canggung saat mengoleskan tabir surya, atau karena tindakan mengoleskan tabir surya kepadaku?",
  ui_story_5057_50570902_24_dialog_content = "Jika yang terakhir, kamu bisa berhenti karena saya sudah meminta kamu untuk melakukannya.",
  ui_story_5057_50570902_25_dialog_content = "Heh, sepertinya kamu masih polos di hati, PlayerName.",
  ui_story_5057_50570902_26_dialog_content = "Jika hal kecil seperti ini membuatmu panik, bagaimana jika harus lebih intim di lain waktu?",
  ui_story_5057_50570902_27_dialog_content = "Seperti sesuatu yang lebih pribadi?",
  ui_story_5057_50570902_28_dialog_content = "Saya rasa tidak akan ada waktu berikutnya...",
  ui_story_5057_50570902_29_dialog_content = "Dan kamu tidak akan meminta saya untuk melakukan sesuatu yang lebih intim, bukan?",
  ui_story_5057_50570902_30_dialog_content = "Oh? Jadi apa pandanganmu tentang \"keintiman\"?",
  ui_story_5057_50570902_31_dialog_content = "Y-Kamu tahu, itu!",
  ui_story_5057_50570902_32_dialog_content = "Hah?",
  ui_story_5057_50570902_33_option_content = "Kamu... memaksa aku untuk...",
  ui_story_5057_50570902_34_dialog_content = "Hahaha, aku nggak akan biarkan kamu pergi terlalu jauh.",
  ui_story_5057_50570902_35_option_content = "Saya... Aku tidak tahu!",
  ui_story_5057_50570902_36_dialog_content = "<color=#e8d9bb>Paloma mengacak rambutku dengan tangannya.</color>",
  ui_story_5057_50570902_37_dialog_content = "Pekerjaan itu akan menjadi gagal total jika kamu pingsan karena malu!",
  ui_story_5057_50570902_38_dialog_content = "Oh...",
  ui_story_5057_50570902_39_dialog_content = "Sejujurnya, meskipun, saya tidak keberatan jika pekerjaan itu mengharuskannya.",
  ui_story_5057_50570902_40_dialog_content = "Ini hanya pekerjaan. Jangan bilang kamu akan menganggapnya serius, PlayerName.",
  ui_story_5057_50570902_41_dialog_content = "Hmm…",
  ui_story_5057_50570902_42_dialog_content = "Oh, untuk menghindari masalah potensial selama pekerjaan dan keharusan untuk mengurangi gaji Anda...",
  ui_story_5057_50570902_43_dialog_content = "Ayo berlatih agar kamu terbiasa dengannya.",
  ui_story_5057_50570902_44_option_content = "A-Apa?",
  ui_story_5057_50570902_45_dialog_content = "Hanya bercanda. Kamu kira aku serius?",
  ui_story_5057_50570902_46_dialog_content = "Kamu memang tidak bersalah!",
  ui_story_5057_50570902_47_dialog_content = "Ugh—!",
  ui_story_5057_50570902_48_option_content = "Tolong hentikan itu!",
  ui_story_5057_50570902_49_dialog_content = "Hahaha, maaf.",
  ui_story_5057_50570902_50_dialog_content = "Hmm, sekarang apa?",
  ui_story_5057_50570902_51_dialog_content = "Kamu tampak tidak senang.",
  ui_story_5057_50570902_52_dialog_content = "Apakah kamu ngambek karena aku menggoda kamu?",
  ui_story_5057_50570902_53_dialog_content = "Bagaimana kalau bertarung denganku, lalu?",
  ui_story_5057_50570902_54_dialog_content = "Bertarung dengan kamu?",
  ui_story_5057_50570902_55_dialog_content = "Benar. Jika kamu menang, aku akan melakukan apapun yang kamu inginkan selama sehari. Tentu saja, itu termasuk yang sudah aku sebutkan sebelumnya.",
  ui_story_5057_50570902_56_dialog_content = "Jika kamu kalah, kamu akan bekerja bersamaku di Nun Cafe, dan aku juga mendapatkan gajimu.",
  ui_story_5057_50570902_57_dialog_content = "Tunggu dulu... Apa itu Nun Cafe? Itu terdengar aneh!",
  ui_story_5057_50570902_58_dialog_content = "Ceritanya panjang. Saat itu malam yang dingin.",
  ui_story_5057_50570902_59_dialog_content = "Saat saya menyeberangi jalan di Umbraton, angin dingin mengguncang tubuh saya.",
  ui_story_5057_50570902_60_dialog_content = "Saya sedang berusaha mengunyah dan menelan satu gigitan terakhir dari bola nasi terakhir saya.",
  ui_story_5057_50570902_61_dialog_content = "Bagaimana kamu sampai pada titik itu...",
  ui_story_5057_50570902_62_dialog_content = "Balas dendam memerlukan modal besar, PlayerName.",
  ui_story_5057_50570902_63_dialog_content = "Seorang biarawati yang baik hati memperkenalkan saya dan mendapatkan saya pekerjaan paruh waktu di sebuah kedai kopi.",
  ui_story_5057_50570902_64_dialog_content = "Itu adalah hari-hari bahagia. Saya bahkan melupakan tentang balas dendam, sampai suatu hari.",
  ui_story_5057_50570902_65_dialog_content = "<size=50>Ah—tolong berhenti, Pak.</size>",
  ui_story_5057_50570902_66_dialog_content = "Ck, ck, ck... apakah kamu sadar berapa banyak cara Ayat 50 dalam Bab 11, Volume 7 dari Ajaran Gereja White Night dapat ditafsirkan?",
  ui_story_5057_50570902_67_dialog_content = "T-Tolong lepaskan aku...",
  ui_story_5057_50570902_68_dialog_content = "Tolong berhenti, Pak.",
  ui_story_5057_50570902_69_dialog_content = "Oh, kamu rupanya.",
  ui_story_5057_50570902_70_dialog_content = "Ini aku, Mirren. Aku merekam semua yang baru saja kamu lakukan.",
  ui_story_5057_50570902_71_dialog_content = "Beri saya sepuluh miliar Nightium atau menderita!",
  ui_story_5057_50570902_72_dialog_content = "Apa? Tidak bisakah aku hanya minta maaf?",
  ui_story_5057_50570902_73_dialog_content = "Itu bukan pilihan. Aku bertaruh hidupku dari kecil hingga sekarang untuk membalas dendam kepadamu. Bagaimana mungkin permintaan maaf cukup?",
  ui_story_5057_50570902_74_dialog_content = "Sial, aku pergi dari sini!",
  ui_story_5057_50570902_75_dialog_content = "Kamu menyelamatkanku, Paloma... Aku milikmu selamanya sekarang...",
  ui_story_5057_50570902_76_dialog_content = "Terima kasih atas tawaranmu, tapi tidak.",
  ui_story_5057_50570902_77_dialog_content = "Saya tidak butuh Caelestite. Yang saya butuhkan adalah algojo yang bisa bersama saya dan dendam saya.",
  ui_story_5057_50570902_78_dialog_content = "Mengapa aku dan Mirren ada dalam cerita ini?",
  ui_story_5057_50570902_79_dialog_content = "Begitulah caranya. Pokoknya, kamu bekerja sama denganku jika kamu kalah.",
  ui_story_5057_50570902_X80_dialog_content = "<color=#e8d9bb>Paloma menantang untuk memancing, dan saya seperti, \"Oh, saya pasti akan menang ini!\"</color>",
  ui_story_5057_50570902_80_dialog_content = "<color=#e8d9bb>Jadi, untuk menguasai keadaan di Habit Cafe, saya mulai menghafal prinsip-prinsip Gereja Lumopolis.</color>",
  ui_story_5057_50571001_1_dialog_content = "Selamat pagi, PlayerName!",
  ui_story_5057_50571001_2_dialog_content = "Pagi, Vice.",
  ui_story_5057_50571001_3_dialog_content = "Kemana kamu pergi dengan semua bagasi itu?",
  ui_story_5057_50571001_4_dialog_content = "Berikut adalah beberapa alat untuk perbaikan dan perawatan.",
  ui_story_5057_50571001_5_dialog_content = "Lorelei mengatakan bahwa beberapa wahana tidak berfungsi dengan baik dan meminta saya untuk memperbaikinya.",
  ui_story_5057_50571001_6_dialog_content = "Aku paham, tapi bukankah lebih baik diserahkan kepada para Rediesel Wrench?",
  ui_story_5057_50571001_7_dialog_content = "Ya, tetapi mereka pergi dengan mobil ke entah ke mana beberapa hari yang lalu.",
  ui_story_5057_50571001_8_dialog_content = "Mereka belum terdengar kabarnya sejak itu. Saya menduga mereka...",
  ui_story_5057_50571001_9_dialog_content = "Saya cukup bisa menebak apa yang sedang kamu tebak.",
  ui_story_5057_50571001_10_dialog_content = "Ya. Lorelei juga memberikan tawaran yang sangat murah hati!",
  ui_story_5057_50571001_11_dialog_content = "Kita akan impas untuk bulan ini setelah ini!",
  ui_story_5057_50571001_12_dialog_content = "Apakah kamu memiliki rencana untuk hari ini, PlayerName?",
  ui_story_5057_50571001_13_dialog_content = "Eh... (Tidak mungkin aku bisa bilang aku ingin berjemur dan memancing...)",
  ui_story_5057_50571001_14_dialog_content = "Tidak juga, jadi bagaimana kalau saya pergi bersama kamu?",
  ui_story_5057_50571001_15_dialog_content = "Aku akan jadi pembantumu hari ini!",
  ui_story_5057_50571001_16_dialog_content = "Bagus, aku mengandalkan kamu ya!",
  ui_story_5057_50571001_17_dialog_content = "Tentu. Biar aku bantu kamu membawa alat-alatnya!",
  ui_story_5057_50571001_18_dialog_content = "Seluruh struktur tampak cukup stabil, jadi hanya sekrup cadangan ini yang sedikit kendor.",
  ui_story_5057_50571001_19_dialog_content = "Bantu saya mengencangkan sekrup, PlayerName.",
  ui_story_5057_50571001_20_dialog_content = "Tentu saja!",
  ui_story_5057_50571001_21_dialog_content = "Oke. Ini dia!",
  ui_story_5057_50571001_22_dialog_content = "Hiya!",
  ui_story_5057_50571001_23_dialog_content = "Tolong berikan itu padaku.",
  ui_story_5057_50571001_24_dialog_content = "Maksud kamu pelumas? Ini, semua siap untuk digunakan!",
  ui_story_5057_50571001_25_dialog_content = "Kamu membaca saya dengan sangat baik, PlayerName.",
  ui_story_5057_50571001_26_dialog_content = "Sangat baik sebagai seorang pembantu.",
  ui_story_5057_50571001_27_dialog_content = "Tentu saja. Kita sudah lama bersama, kita punya kecocokan yang hebat.",
  ui_story_5057_50571001_28_dialog_content = "Oke, selesai.",
  ui_story_5057_50571001_29_dialog_content = "Ini adalah tempat terakhir untuk diperiksa.",
  ui_story_5057_50571001_30_dialog_content = "Kita bisa kembali setelah kita merapikan alat-alat.",
  ui_story_5057_50571001_31_dialog_content = "Bagus!",
  ui_story_5057_50571001_32_dialog_content = "Pemeliharaan ini bahkan lebih lancar dari yang saya bayangkan.",
  ui_story_5057_50571001_33_dialog_content = "Dan saya tidak mengharapkan wahana yang dirancang oleh Rediesel Wrench memiliki kualitas estetika tertentu.",
  ui_story_5057_50571001_34_dialog_content = "Struktur mungkin sederhana, tetapi kecerdikan yang diterapkan di dalamnya memungkinkan untuk dijalankan dengan biaya perawatan yang rendah.",
  ui_story_5057_50571001_35_dialog_content = "Ternyata banyak mekanik hebat di Rediesel Wrench.",
  ui_story_5057_50571001_36_dialog_content = "Kemampuan untuk memanfaatkan sumber daya yang tersedia mungkin merupakan salah satu alasan mengapa mereka sangat baik dalam bertahan hidup.",
  ui_story_5057_50571001_37_dialog_content = "Mm, saya belajar banyak dari mereka hari ini. Illumina dapat mengambil satu atau dua halaman dari buku mereka.",
  ui_story_5057_50571001_38_dialog_content = "Itulah Vice yang saya kenal, selalu memikirkan tentang belajar dan mengambil sesuatu yang baru!",
  ui_story_5057_50571001_39_dialog_content = "Mengapa tiba-tiba memberi pujian?",
  ui_story_5057_50571001_40_dialog_content = "Sebagai teman Anda, tentu saja saya perlu terus belajar dan menjadi lebih kuat untuk melindungi Anda dan Soroz.",
  ui_story_5057_50571001_41_option_content = "Saya terharu...",
  ui_story_5057_50571001_42_option_content = "Vice…",
  ui_story_5057_50571001_43_dialog_content = "Hei, kenapa kamu menangis?",
  ui_story_5057_50571001_44_dialog_content = "Oh, saya baru saja terharu, itu saja.",
  ui_story_5057_50571001_45_dialog_content = "Mengingat kembali, pertama kali saya bertemu dengan kamu adalah ketika kamu secara tidak sengaja menghancurkan tanah...",
  ui_story_5057_50571001_46_dialog_content = "Sekarang kamu jadi sangat bisa diandalkan...!",
  ui_story_5057_50571001_47_dialog_content = "Berhenti di situ! Jangan ungkit lagi hal memalukan itu!",
  ui_story_5057_50571001_48_dialog_content = "Kamu terlalu berlebihan, PlayerName. Setiap orang terus meningkat, dan itu termasuk Anda.",
  ui_story_5057_50571001_49_dialog_content = "Aku tumbuh? Rasanya nggak seperti itu...",
  ui_story_5057_50571001_50_dialog_content = "Itu cara berpikir yang salah dan tidak enak. Saya melihat kamu menjadi lebih baik dengan mata saya sendiri.",
  ui_story_5057_50571001_51_dialog_content = "Sampai pada titik di mana aku bahkan tidak bisa membayangkan tanpa kamu di sekitar...",
  ui_story_5057_50571001_52_dialog_content = "Groar...",
  ui_story_5057_50571001_53_dialog_content = "Maaf, itu aku! Aku terburu-buru untuk datang membantumu, jadi aku melewatkan sarapan!",
  ui_story_5057_50571001_54_dialog_content = "Biar kuperiksa... Memang sudah cukup larut!",
  ui_story_5057_50571001_55_dialog_content = "Ayo makan siang bersamaku, PlayerName!",
  ui_story_5057_50571001_56_dialog_content = "<size=30>Uh, ini tidak mungkin hasil karya Vice, bukan?</size>",
  ui_story_5057_50571001_57_dialog_content = "<size=30>Kemarin, saya baru ingat dia bertanya di mana dia bisa memasak...</size>",
  ui_story_5057_50571001_58_dialog_content = "Hei, apa yang kamu gumamkan?",
  ui_story_5057_50571001_59_dialog_content = "Kamu tidak lapar? Tidak ingin makan bersama saya?",
  ui_story_5057_50571001_60_dialog_content = "(Oh-oh, apakah saatnya untuk mengambil keputusan sudah tiba?)",
  ui_story_5057_50571001_61_dialog_content = "aku, eh...",
  ui_story_5057_50571001_62_option_content = "Tidak sabar untuk mencicipi yang kamu buat, Vice!",
  ui_story_5057_50571001_63_dialog_content = "<size=30>Mengingat aku tidak menolak saat pertama kali dia memasak sesuatu...</size>",
  ui_story_5057_50571001_64_dialog_content = "<size=30>Ini tanggung jawabku untuk makan setiap hidangan yang Vice buat!</size>",
  ui_story_5057_50571001_65_dialog_content = "Aku menghargai bisikan semangat dari kamu, tapi aku tidak membuat makan siang hari ini.",
  ui_story_5057_50571001_66_dialog_content = "Karena saya bangun pagi-pagi mengumpulkan alat, kita pantas untuk bersenang-senang!",
  ui_story_5057_50571001_67_option_content = "Ini gratis untukmu hari ini!",
  ui_story_5057_50571001_68_dialog_content = "Ini adalah taman, kamu tahu! Izinkan aku mengajakmu ke restoran yang sempat aku sebutkan waktu itu!",
  ui_story_5057_50571001_69_dialog_content = "Itu memang terdengar bagus... Tapi apakah kamu punya uang, PlayerName?",
  ui_story_5057_50571001_70_dialog_content = "Aduh... yah... Gimana kalau kasih saya uang muka?",
  ui_story_5057_50571001_71_dialog_content = "Sudah kuduga!",
  ui_story_5057_50571001_72_dialog_content = "Ayo, rencananya aku mau menggunakan gaji dari pekerjaan perawatan ini untuk berfoya-foya bersamamu.",
  ui_story_5057_50571001_73_dialog_content = "<color=#e8d9bb>Kemudian Vice dan saya menghabiskan hari yang menyenangkan bersama, dan dia terlihat sangat bahagia. Luar biasa!</color>",
  ui_story_5057_50571002_1_dialog_content = "Ini dia!",
  ui_story_5057_50571002_2_dialog_content = "Pemandangan bagus. Cocok untuk berkemah.",
  ui_story_5057_50571002_3_dialog_content = "Bantulah aku, V-Vice... Lututku lemas... di bawah semua perlengkapan ini...",
  ui_story_5057_50571002_4_dialog_content = "PlayerName!",
  ui_story_5057_50571002_5_dialog_content = "Kau baik-baik saja? Ayo duduk dan santai.",
  ui_story_5057_50571002_6_dialog_content = "Aku baik-baik saja... Maksudku, aku ini yang memintamu untuk melatihku tentang bertahan hidup di alam liar, kan...",
  ui_story_5057_50571002_7_dialog_content = "Jadi, saya harus berusaha untuk mencapai akhir...!",
  ui_story_5057_50571002_8_dialog_content = "Tapi beban ini sungguh... terlalu berat!",
  ui_story_5057_50571002_9_dialog_content = "Ahaha, maaf tentang itu.",
  ui_story_5057_50571002_10_dialog_content = "Ini berisi persediaan makanan untuk sepuluh hari dan seluruh perlengkapan untuk pelatihan bertahan hidup di alam liar bagi pemula Illumina, jadi kemungkinan sedikit berat.",
  ui_story_5057_50571002_11_dialog_content = "K-Kenapa sepuluh hari? Apakah itu benar-benar perlu?",
  ui_story_5057_50571002_12_dialog_content = "Nah, bagaimana cara mengatakannya...",
  ui_story_5057_50571002_13_dialog_content = "Maymungkin tekad di matamu semalam yang membangkitkan semangat juang dalam diriku.",
  ui_story_5057_50571002_14_dialog_content = "Andalah yang berkata, \"Tolong latih saya, Letnan Vice!\"",
  ui_story_5057_50571002_15_dialog_content = "Saya sedang memikirkan keterbatasan fisik Anda saat mengeluarkan dan mengembalikan ransum berulang kali.",
  ui_story_5057_50571002_16_dialog_content = "Mengingat kita sedang mengasah tubuh dan kemauan Anda sampai MAKS, saya memutuskan untuk menetapkan jumlahnya untuk sepuluh hari.",
  ui_story_5057_50571002_17_dialog_content = "Namun, saya percaya kamu bisa melakukannya, dan kamu memang melakukannya!",
  ui_story_5057_50571002_18_dialog_content = "Maaf karena kamu memiliki harapan yang begitu tinggi terhadap aku.",
  ui_story_5057_50571002_19_dialog_content = "Untungnya, aku berhasil membawanya sampai ke sini dan tidak mengecewakanmu.",
  ui_story_5057_50571002_20_dialog_content = "Ya, kamu berhasil, PlayerName.",
  ui_story_5057_50571002_21_dialog_content = "Berjalan sejauh ini dengan beban tersebut patut diacungi jempol untuk seorang pemula Illumina.",
  ui_story_5057_50571002_22_dialog_content = "Betulkah?",
  ui_story_5057_50571002_23_dialog_content = "Y-Ya...",
  ui_story_5057_50571002_24_dialog_content = "...",
  ui_story_5057_50571002_25_dialog_content = "Oh, kamu pasti lelah, PlayerName. Mau istirahat dulu?",
  ui_story_5057_50571002_26_dialog_content = "Letakkan ranselmu dan biarkan aku memijat bahu kamu.",
  ui_story_5057_50571002_27_dialog_content = "Atau sebaiknya kita mendirikan tenda dulu?",
  ui_story_5057_50571002_28_option_content = "Saya butuh keduanya!",
  ui_story_5057_50571002_29_dialog_content = "Apa yang akan saya lakukan denganmu, PlayerName...",
  ui_story_5057_50571002_30_dialog_content = "Baik, kita sebut ini sebagai hadiah untuk kerja kerasmu!",
  ui_story_5057_50571002_31_option_content = "Pasang tenda terlebih dahulu.",
  ui_story_5057_50571002_32_dialog_content = "Ya, lebih baik punya tempat untuk istirahat.",
  ui_story_5057_50571002_33_dialog_content = "Aku akan mengajari kamu cara memasangnya, PlayerName.",
  ui_story_5057_50571002_34_dialog_content = "Cukup taruh taruhannya di sini.",
  ui_story_5057_50571002_35_dialog_content = "Ayo, PlayerName, pukul tiang ke tanah dengan sekuat tenaga.",
  ui_story_5057_50571002_36_dialog_content = "Pastikan mereka masuk dengan dalam dan aman.",
  ui_story_5057_50571002_37_dialog_content = "Siap! Bisa!",
  ui_story_5057_50571002_38_dialog_content = "Heeyeah!",
  ui_story_5057_50571002_39_dialog_content = "Hiya!",
  ui_story_5057_50571002_40_dialog_content = "Itu sudah cukup. Sekarang taruh kanvas di atas tenda. Saya sudah menutupi tanahnya.",
  ui_story_5057_50571002_41_dialog_content = "Ingat untuk menutupi area terlebih dahulu lain kali, PlayerName.",
  ui_story_5057_50571002_42_dialog_content = "Mengerti!",
  ui_story_5057_50571002_43_dialog_content = "Setelah selesai, coba tes untuk melihat apakah itu tahan lama.",
  ui_story_5057_50571002_44_dialog_content = "Tenda selesai jika tidak ada masalah.",
  ui_story_5057_50571002_45_dialog_content = "Biarkan saya melihat tenda yang kamu bangun...",
  ui_story_5057_50571002_46_dialog_content = "Sangat kokoh. Kamu akan mendapat skor 80 atau lebih dalam sebuah test.",
  ui_story_5057_50571002_47_dialog_content = "Saya sudah mengajari kamu cara membaca peta dan kompas, serta menjelaskan langkah penting dari pertolongan pertama.",
  ui_story_5057_50571002_48_dialog_content = "Ya, aku menghafal itu sebanyak yang aku bisa.",
  ui_story_5057_50571002_49_dialog_content = "Selanjutnya adalah pengawetan makanan dan air, maka kamu akan memiliki kesempatan lebih dari 70% untuk bertahan hidup di alam liar.",
  ui_story_5057_50571002_50_dialog_content = "Saya merasa bahwa Vice di sini dan sekarang telah menyelamatkan diri saya di masa depan lagi.",
  ui_story_5057_50571002_51_dialog_content = "Tenda ini terasa nyaman, seolah-olah saya baru saja membangun rumah untuk Vice dan diri saya sendiri.",
  ui_story_5057_50571002_52_dialog_content = "Oh ya? Jadi itu berarti kita keluarga, PlayerName?",
  ui_story_5057_50571002_53_dialog_content = "Tentu saja kamu keluarga, Vice.",
  ui_story_5057_50571002_54_dialog_content = "S-sungguh...?",
  ui_story_5057_50571002_55_dialog_content = "Sebenarnya, saya juga merasa begitu.",
  ui_story_5057_50571002_56_dialog_content = "Ya, memang keren untuk hang out bersama keluarga.",
  ui_story_5057_50571002_57_dialog_content = "Saya sangat bahagia saat bersama kamu.",
  ui_story_5057_50571002_58_dialog_content = "Oh, untuk berterima kasih atas pijatan dan mengajari saya cara membangun tenda, saya akan memasak malam ini!",
  ui_story_5057_50571002_59_dialog_content = "Saya memohon pada Gram untuk menunjukkan cara membuat ransum lebih lezat.",
  ui_story_5057_50571002_60_dialog_content = "Baiklah, kali ini aku akan mengandalkanmu, PlayerName.",
  ui_story_5057_50571002_61_dialog_content = "Makan makanan lezat yang kamu masak sambil menikmati pemandangan alam...",
  ui_story_5057_50571002_62_dialog_content = "Semua kelelahan dari mengambil satu pekerjaan setelah yang lainnya hilang begitu saja!",
  ui_story_5057_50571002_63_dialog_content = "Camping itu menyenangkan, aku tahu.",
  ui_story_5057_50571002_64_dialog_content = "Serahkan padaku! Aku akan menyalakan api sekarang!",
  ui_story_5057_50571002_65_dialog_content = "<color=#e8d9bb>Kemudian Vice dan aku makan sepuasnya hingga kami menghabiskan malam dengan berbaring, mengagumi bintang-bintang hingga larut, sebelum akhirnya kembali ke tenda.</color>",
  ui_story_5057_50571101_1_dialog_content = "Maaf, aku terlambat!",
  ui_story_5057_50571101_2_dialog_content = "Tidak usah khawatir, kamu masih punya dua menit. Saya baru saja tiba di sini juga.",
  ui_story_5057_50571101_3_dialog_content = "Ngomong-ngomong, kenapa kamu berpakaian seperti itu?",
  ui_story_5057_50571101_4_dialog_content = "Oh, ini adalah baju pelindung perawatan yang saya pinjam dari Lorelei.",
  ui_story_5057_50571101_5_dialog_content = "Karena sulit mencuci noda minyak dari pakaian biasa.",
  ui_story_5057_50571101_6_dialog_content = "Tapi saya ingat kamu memesan beberapa set outfit yang sama kemudian.",
  ui_story_5057_50571101_7_dialog_content = "Oh, itu awalnya diberikan kepadaku oleh Soroz, salah satu kostum langka yang cocok untukku.",
  ui_story_5057_50571101_8_dialog_content = "Sebelum itu... Bagaimana cara mengatakannya... Terkadang saya pergi tanpa pakaian.",
  ui_story_5057_50571101_9_dialog_content = "Aku tahu. Aku mulai mengerti mengapa kamu begitu sentimental terhadapnya.",
  ui_story_5057_50571101_10_dialog_content = "Tapi ini hanya satu... Bagaimana kalau nanti aku ajak kamu ke Lumopolis untuk mendapatkan dua set baru, dibuat khusus?",
  ui_story_5057_50571101_11_dialog_content = "Saya bisa mengenalkan kamu ke tukang jahit. Tuan Kota mengatakan dia telah melayani keluarga saya selama lebih dari tiga puluh tahun.",
  ui_story_5057_50571101_12_dialog_content = "Melayani keluarga Anda? Bukankah itu membuatnya menjadi penjahit yang luar biasa?",
  ui_story_5057_50571101_13_dialog_content = "Tentu saja, pasti cocok untuk para desainer terbaik di Kota Pelabuhan.",
  ui_story_5057_50571101_14_dialog_content = "Itu juga bisa sangat mahal...",
  ui_story_5057_50571101_15_dialog_content = "Saya juga tidak yakin tentang itu.",
  ui_story_5057_50571101_16_dialog_content = "Tapi saya pikir ada ruang di anggaran Lumopolis yang didedikasikan untuk pakaian bagi Tuan Kota dan keluarganya.",
  ui_story_5057_50571101_17_dialog_content = "Sebuah mode yang disesuaikan agar pas memberikan perasaan yang sangat berbeda.",
  ui_story_5057_50571101_18_dialog_content = "Benarkah? Tidak heran aku pikir semua pakaianmu cocok sempurna padamu...",
  ui_story_5057_50571101_19_dialog_content = "Kamu terlihat anggun dan cantik seperti sinar rembulan...",
  ui_story_5057_50571101_20_dialog_content = "Saya tidak bisa tidak teringat pepatah Longzhou yang pernah saya baca...",
  ui_story_5057_50571101_21_dialog_content = "Ini ditampilkan dengan cara yang indah, hanya untuk segera bersembunyi di awan cukup lama.",
  ui_story_5057_50571101_22_dialog_content = "Kurasa itu cukup menjelaskannya.",
  ui_story_5057_50571101_23_dialog_content = "Ehem, terima kasih atas pujian itu, tapi tolong berhenti.",
  ui_story_5057_50571101_24_dialog_content = "Oh, maaf. Itu terlalu berlebihan.",
  ui_story_5057_50571101_25_dialog_content = "Apa?",
  ui_story_5057_50571101_26_dialog_content = "Uh, maksudku... Omong-omong...",
  ui_story_5057_50571101_27_dialog_content = "Heheh... Ya sudah.",
  ui_story_5057_50571101_28_dialog_content = "Tidak ada pekerjaan yang harus kamu kerjakan? Haruskah kita berhenti ngobrol?",
  ui_story_5057_50571101_29_dialog_content = "Benar, saya harus memperbaiki Naga Malam Putih!",
  ui_story_5057_50571101_30_dialog_content = "Wow, sangat tinggi di sini... Rasanya seperti aku berdiri di langit.",
  ui_story_5057_50571101_31_dialog_content = "Terkadang sangat sulit untuk menghasilkan uang.",
  ui_story_5057_50571101_32_dialog_content = "Rem pada gerobak ketiga rusak, PlayerName.",
  ui_story_5057_50571101_33_dialog_content = "Cukup tukar saja seharusnya bisa.",
  ui_story_5057_50571101_34_dialog_content = "Oke, aku akan segera ke sana—!",
  ui_story_5057_50571101_35_dialog_content = "Hati-hati, hati-hati...",
  ui_story_5057_50571101_36_dialog_content = "Jangan melihat ke bawah...",
  ui_story_5057_50571101_37_dialog_content = "Ambil tanganku, PlayerName.",
  ui_story_5057_50571101_38_dialog_content = "Tentu!",
  ui_story_5057_50571101_39_dialog_content = "Kamu mengalami pengalaman yang kurang menyenangkan dengan wahana itu terakhir kali, tetapi sekarang kamu tidak takut ketinggian.",
  ui_story_5057_50571101_40_dialog_content = "Berdiri di ketinggian dan mengendarainya adalah dua hal yang berbeda... Yang terakhir adalah neraka.",
  ui_story_5057_50571101_41_dialog_content = "Oke, nanti saya akan mengurus uji stres.",
  ui_story_5057_50571101_42_dialog_content = "Saya mengganti cakram rem.",
  ui_story_5057_50571101_43_dialog_content = "<color=#e8d9bb>Beberapa menit kemudian</color>",
  ui_story_5057_50571101_44_dialog_content = "Itu harus melakukannya.",
  ui_story_5057_50571101_45_dialog_content = "Saya akan naik untuk uji coba. Cukup kontrol dengan perangkat ini, Carleen.",
  ui_story_5057_50571101_46_dialog_content = "Kau yakin? Mayharusnya aku yang naik.",
  ui_story_5057_50571101_47_dialog_content = "Jangan khawatir, jika ada masalah, saya akan menanganinya.",
  ui_story_5057_50571101_48_dialog_content = "Oke, hati-hati ya.",
  ui_story_5057_50571101_49_dialog_content = "Aku terikat... Oke, biarkan menghajar!",
  ui_story_5057_50571101_50_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_5057_50571101_51_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5057_50571101_52_dialog_content = "Whoa, roller coaster ini benar-benar iblis kecepatan.",
  ui_story_5057_50571101_53_dialog_content = "Tunggu, kenapa ini berjalan lebih cepat dari biasanya?",
  ui_story_5057_50571101_54_dialog_content = "<color=#e8d9bb>Dentang, dentang!</color>",
  ui_story_5057_50571101_55_dialog_content = "Apa-apaan ini...!",
  ui_story_5057_50571101_56_dialog_content = "Hentikan permainan, Carleen!",
  ui_story_5057_50571101_57_dialog_content = "<color=#e8d9bb>Mendesah—</color>",
  ui_story_5057_50571101_58_dialog_content = "Rem sudah diaktifkan!",
  ui_story_5057_50571101_59_dialog_content = "Saya bisa melihat gerobak keempat bergoyang dari sini!",
  ui_story_5057_50571101_60_dialog_content = "Saya mengerti! Pasti ada masalah dengan konektornya!",
  ui_story_5057_50571101_61_dialog_content = "Mengapa kamu membuka gesper, PlayerName?!",
  ui_story_5057_50571101_62_dialog_content = "Saya harus memperbaikinya sekarang, atau seluruh roller coaster mungkin akan keluar dari rel dan melukai orang-orang di tanah!",
  ui_story_5057_50571101_63_dialog_content = "Itu terlalu berbahaya!",
  ui_story_5057_50571101_64_dialog_content = "Tidak masalah, beri saya beberapa detik untuk menekannya ke bawah dan kita bisa membuatnya berhenti sempurna...",
  ui_story_5057_50571101_65_dialog_content = "<color=#e8d9bb>Klik—</color>",
  ui_story_5057_50571101_66_dialog_content = "Berhasil!",
  ui_story_5057_50571101_67_dialog_content = "<color=#e8d9bb>Dentang!</color>",
  ui_story_5057_50571101_68_dialog_content = "PlayerName!!!",
  ui_story_5057_50571101_69_dialog_content = "A-Apa yang terjadi, apakah saya terbang dari wahana ini?",
  ui_story_5057_50571101_70_dialog_content = "Aku jatuh cepat... Apakah ini hal terakhir yang aku lihat, selamanya?",
  ui_story_5057_50571101_71_dialog_content = "Pegang tanganku, PlayerName!",
  ui_story_5057_50571101_72_dialog_content = "Carleen? Tentu!",
  ui_story_5057_50571101_73_dialog_content = "Fiuh... Aku beruntung kamu ada di sekitar, Carleen.",
  ui_story_5057_50571101_74_dialog_content = "Kamu menyelamatkan aku lagi. Even tali pengaman putus. Betapa memalukannya...",
  ui_story_5057_50571101_75_dialog_content = "Tentu saja saya akan membantu secepatnya saat kamu dalam bahaya, PlayerName.",
  ui_story_5057_50571101_76_dialog_content = "Kita teman dekat, jadi kamu nggak usah berhutang apa-apa sama aku.",
  ui_story_5057_50571101_77_dialog_content = "Oke, tapi saya masih merasa sangat buruk tentang itu.",
  ui_story_5057_50571101_78_dialog_content = "Apa yang membuatmu merasa sangat buruk?",
  ui_story_5057_50571101_79_option_content = "Bahwa saya terus membutuhkan pertolongan",
  ui_story_5057_50571101_80_option_content = "Saya ingin menyimpan Carleen juga",
  ui_story_5057_50571101_81_dialog_content = "Aku ingin memiliki kekuatan untuk melindungi dan menyelamatkanmu, Carleen.",
  ui_story_5057_50571101_82_dialog_content = "Aku tahu.",
  ui_story_5057_50571101_83_dialog_content = "Tapi bukankah kamu telah menyelamatkan aku, orang lain, dan bahkan Lumopolis, berkali-kali dengan cara kamu sendiri?",
  ui_story_5057_50571101_84_dialog_content = "Yah, tapi itu tidak sama.",
  ui_story_5057_50571101_85_dialog_content = "Bagi aku, semuanya sama saja.",
  ui_story_5057_50571101_86_dialog_content = "Bagi saya, kamu telah mengawasi saya dengan cara dan usaha kamu sendiri.",
  ui_story_5057_50571101_87_dialog_content = "Kalau kamu terganggu tentang itu, kenapa tidak mentraktir aku es krim di sana?",
  ui_story_5057_50571101_88_dialog_content = "Apa? Tentu saja... Hei, tunggu, lututku masih gemetar...",
  ui_story_5057_50571101_89_dialog_content = "<color=#e8d9bb>Kemudian Carleen dan saya makan banyak es krim bersama, membuat saya mengalami sakit kepala hebat sepanjang malam.</color>",
  ui_story_5057_50571102_1_dialog_content = "Tidak masalah, tidak masalah kali ini pasti...",
  ui_story_5057_50571102_2_dialog_content = "Saya adalah bangsawan Lumopolis setelah semua.",
  ui_story_5057_50571102_3_dialog_content = "Saya Carleen de Schwartz, putri dari Daniel de Schwartz.",
  ui_story_5057_50571102_4_dialog_content = "Terlepas dari bahaya, saya akan mengatasi dengan pedang tajam saya.",
  ui_story_5057_50571102_5_dialog_content = "Terlepas dari kesulitan, saya akan bertahan dengan kehormatan.",
  ui_story_5057_50571102_6_dialog_content = "C-Carleen?",
  ui_story_5057_50571102_7_dialog_content = "Tolong berikan saya ketenangan untuk tetap tenang dalam kekacauan, dan tunjukkan belas kasihan dalam kebencian.",
  ui_story_5057_50571102_8_dialog_content = "Berikan aku iman untuk tetap teguh dalam ketidakpastian, tak terkalahkan dalam keresahan.",
  ui_story_5057_50571102_9_dialog_content = "Berikan saya ketahanan untuk tetap teguh dalam kemunduran, kuat di bawah tekanan.",
  ui_story_5057_50571102_10_dialog_content = "Dan kebaikan untuk tetap berbelas kasih di tengah apati, penuh harapan dalam putus asa.",
  ui_story_5057_50571102_11_dialog_content = "Uh, Carleen?",
  ui_story_5057_50571102_12_dialog_content = "Fiuh...",
  ui_story_5057_50571102_13_dialog_content = "Kamu tampak kurang baik... Bagaimana kalau kita melupakannya?",
  ui_story_5057_50571102_14_dialog_content = "Tidak perlu mencoba semua wahana seru.",
  ui_story_5057_50571102_15_dialog_content = "Ada wahana lain yang aman namun tetap sangat menyenangkan!",
  ui_story_5057_50571102_16_dialog_content = "Misalnya, kereta kecil yang lucu di sebelah sana. Kita bisa naik dan menjelajahi seluruh Denuo.",
  ui_story_5057_50571102_17_dialog_content = "Dan karusel sangat cantik dengan lampu di malam hari... Kamu tidak suka naik kuda, Carleen?",
  ui_story_5057_50571102_18_dialog_content = "Ditambah dengan bianglala...",
  ui_story_5057_50571102_19_dialog_content = "Tidak.",
  ui_story_5057_50571102_20_dialog_content = "Maaf, tapi ini berkaitan dengan... banyak hal.",
  ui_story_5057_50571102_21_dialog_content = "Apakah Vice salah satunya?",
  ui_story_5057_50571102_22_dialog_content = "Saya tidak akan menyangkal itu, tapi itu tidak semua...",
  ui_story_5057_50571102_23_dialog_content = "Kami berdua menerima pelatihan yang sama kerasnya. Tidak ada alasan mengapa saya tidak bisa melakukan apa yang bisa dia lakukan!",
  ui_story_5057_50571102_24_dialog_content = "Belum lagi dengan kamu sebagai saksi...",
  ui_story_5057_50571102_25_dialog_content = "Pokoknya, saya harus berlatih sampai saya memiliki ketenangan seorang ksatria sejati!",
  ui_story_5057_50571102_26_dialog_content = "Target pertama, Naga Malam Putih!",
  ui_story_5057_50571102_27_dialog_content = "<color=#e8d9bb>Tumpangan pertama di Naga Malam Putih</color>",
  ui_story_5057_50571102_28_dialog_content = "I-Saya rasa bando saya baru saja tertiup angin.",
  ui_story_5057_50571102_29_dialog_content = "Lanjutkan!",
  ui_story_5057_50571102_30_dialog_content = "<color=#e8d9bb>Tumpangan kedua di Naga Malam Putih</color>",
  ui_story_5057_50571102_31_dialog_content = "A-Aku pusing... rasanya seperti dunia ini berputar.",
  ui_story_5057_50571102_32_dialog_content = "Lagi!",
  ui_story_5057_50571102_33_dialog_content = "<color=#e8d9bb>Tumpangan ketiga di Naga Malam Putih</color>",
  ui_story_5057_50571102_34_dialog_content = "Saya rasa Eclipsite baru saja memukul perut saya... *mual*",
  ui_story_5057_50571102_35_dialog_content = "Hmm... Sial!",
  ui_story_5057_50571102_36_dialog_content = "Carleen, bagaimana kalau kita beralih ke Fantasy Matrix?",
  ui_story_5057_50571102_37_dialog_content = "Kamu sudah berusaha sangat keras.",
  ui_story_5057_50571102_38_dialog_content = "I-Ide bagus.",
  ui_story_5057_50571102_39_dialog_content = "Kurasa kita bisa menghitung ini... sebagai lulus.",
  ui_story_5057_50571102_40_dialog_content = "Target kedua, Matriks Fantasi.",
  ui_story_5057_50571102_41_dialog_content = "<color=#e8d9bb>Setelah keluar dari Fantasy Matrix dengan Carleen</color>",
  ui_story_5057_50571102_42_dialog_content = "M-Hatiku sampai naik ke tenggorokanku.",
  ui_story_5057_50571102_43_dialog_content = "Saya tidak merasa seburuk sebelumnya.",
  ui_story_5057_50571102_44_dialog_content = "Kamu tidak berpikir itu \"seburuk\" sekarang?",
  ui_story_5057_50571102_45_dialog_content = "Kamu terlalu memaksakan diri... Tiga kali lagi dan aku mungkin akan mati.",
  ui_story_5057_50571102_46_dialog_content = "Selagi masih ada tenaga di dalam diri, mari coba Blue Sky.",
  ui_story_5057_50571102_47_dialog_content = "Bukankah lebih baik menghadapi wahana yang tidak bisa kamu tangani waktu itu?",
  ui_story_5057_50571102_48_dialog_content = "...",
  ui_story_5057_50571102_49_dialog_content = "Atau kita bisa kembali dan mengambil makanan, selagi perutku masih utuh.",
  ui_story_5057_50571102_50_dialog_content = "Tidak, sama sekali tidak!",
  ui_story_5057_50571102_51_dialog_content = "Saya akan menghadapi Blue Sky kali ini! Jika saya membeku, dorong saya segera!",
  ui_story_5057_50571102_52_dialog_content = "Siap?",
  ui_story_5057_50571102_53_dialog_content = "T-Tolong berikan saya kepercayaan untuk tetap teguh dalam ketidakpastian, tak terkalahkan dalam keresahan.",
  ui_story_5057_50571102_54_option_content = "Ambil Carleen dan lompat",
  ui_story_5057_50571102_55_dialog_content = "Hah? PlayerName?",
  ui_story_5057_50571102_56_dialog_content = "Ugh—!",
  ui_story_5057_50571102_57_option_content = "Ayo kembali saja",
  ui_story_5057_50571102_58_dialog_content = "Tidak mungkin!",
  ui_story_5057_50571102_59_dialog_content = "Dorong aku seperti yang kamu janjikan!",
  ui_story_5057_50571102_60_dialog_content = "Oke, jangan bilang aku tidak mengingatkanmu!",
  ui_story_5057_50571102_61_dialog_content = "Mohon berikan saya—",
  ui_story_5057_50571102_62_dialog_content = "Ugh—!",
  ui_story_5057_50571102_63_dialog_content = "Apa kamu baik-baik saja, Carleen? Di sini, bersandarlah padaku.",
  ui_story_5057_50571102_64_dialog_content = "Terima kasih, PlayerName...",
  ui_story_5057_50571102_65_dialog_content = "Setelah semua melompat dan berayun, saya sebenarnya merasa segar sekarang.",
