  ui_story_5057_50571102_69_dialog_content = "Tapi saya sedikit haus.",
  ui_story_5057_50571102_70_dialog_content = "Ayo ambil air. Kita belum minum sejak kita tidak ingin itu kembali naik.",
  ui_story_5057_50571102_71_dialog_content = "Oh, aku lihat keran air minum di sebelah sana.",
