  ui_story_5057_50571102_73_dialog_content = "Ugh—!",
  ui_story_5057_50571102_74_dialog_content = "Ya, masih rusak... Terakhir kali juga menyemprotkan air ke seluruh tubuhku.",
  ui_story_5057_50571102_75_dialog_content = "Yah, kita harus pergi dan berganti pakaian.",
