  ui_story_5057_50571102_78_dialog_content = "... Setelah dipikirkan lagi, abaikan saja apa yang saya katakan. Terima kasih.",
  ui_story_5057_50571102_79_dialog_content = "Uh, ada apa?",
  ui_story_5057_50571102_80_dialog_content = "Rasanya enak bersandar padamu sesekali.",
  ui_story_5057_50571102_81_dialog_content = "Mari kita kembali.",
  ui_story_5057_50571102_82_dialog_content = "<color=#e8d9bb>Setelah Carleen mengganti pakaiannya, kami pergi dan bermain di korsel dan bianglala bersama-sama.</color>",
  ui_story_5057_50570002_1_dialog_content = "PlayerName!",
  ui_story_5057_50570002_2_dialog_content = "Oh, hai, Lorelei! Ada apa kamu di sini?",
