  ui_story_5057_50570002_9_dialog_content = "Kami juga memiliki Vice dan Carleen yang mengurus hal itu.",
  ui_story_5057_50570002_10_dialog_content = "Hmm... Saya ingat kamu bilang tidak banyak ruang untuk peningkatan di area hotel waktu itu, kan?",
  ui_story_5057_50570002_11_dialog_content = "Ya, kamu bisa santai sekarang, PlayerName. Tidak perlu usaha ekstra lagi.",
  ui_story_5057_50570002_12_dialog_content = "Terima kasih atas bantuan Anda, Denuo Valley Resort kini menjadi hidup dengan energi yang luar biasa.",
  ui_story_5057_50570002_13_dialog_content = "Sebagai pahlawan di balik penciptaan negeri ajaib ini dan asisten utama saya, saatnya bagi kamu untuk beristirahat sejenak dan menikmati hasil dari kerja kerasmu.",
  ui_story_5057_50570002_14_dialog_content = "Ini dia!",
  ui_story_5057_50570002_15_dialog_content = "Hmm…?",
  ui_story_5057_50570002_16_dialog_content = "Saya telah menyiapkan ini, khusus untuk kamu, tiket eksklusif untuk menghormati mereka yang telah memberikan kontribusi luar biasa untuk Denuo Valley Resort.",
  ui_story_5057_50570002_17_dialog_content = "Ini adalah hak istimewa satu-satunya!",
